WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[32315] = { title = "Anduin's Plea", description = "Ah, just the {class} I was looking for. I have received an urgent letter from the young Prince Anduin.\n\nHe is playing host to his father, King Wrynn, and several other Alliance dignitaries at the Shrine of Seven Stars in the Vale of Eternal Blossoms.\n\nAccording to his most recent correspondence, something bad is happening at the city.\n\nPlease go at once and speak with him. I must settle some affairs here at Lion's Landing, but I will join you soon.\n\nSpeak to Fennie if you'd like a ride to the Vale.", objectives = "Find Anduin at the Shrine of Seven Stars. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", completion = "Well met, <class>. We have much work to do here." }
WordHunterWoW_QuestEN[32316] = { title = "Heart Of The Alliance", description = "I can't believe this has happened, {name}. After all we have been through here on Pandaria, will our people never learn from their past mistakes?\n\nBrann's expedition returned recently from Mogujia, bearing a sample of sha for study.\n\nI had my reservations about this endeavor in the first place, and my worst fears have been realized.\n\nThe sha has escaped containment. I do not need to explain the horror of bringing the sha into the heart of the Vale.\n\nWe must dispel any sha we can find, and quickly!", objectives = "Confront 6 Sha-Touched Footmen. Should you lose Prince Anduin, speak to him at The Imperial Exchange.", progress = "We must protect this land, and our people, from the sha's influence.", completion = "I see that you and my son have been hard at work. Thank you for taking the initiative to aid our cause here in the Vale." }
WordHunterWoW_QuestEN[32317] = { title = "Seeking the Soulstones", description = "{name}, take this - the journal of Jubeka Shadowbreaker.\n\nRead the journal and use the information contained within to track down where she went.\n\nFind her soulstones and use them to locate her.", objectives = "Read Jubeka's Journal and use the clues within to locate the four soulstone fragments." }
WordHunterWoW_QuestEN[32318] = { title = "Regeneration Takes Time", description = "Vol'jin would be dead if he were any race other than a troll. His regeneration is impressive, but it is being blocked by a poison.\n\nWe need to cleanse this poison so that he can regenerate the damage.\n\nTake to the skies and travel southeast. Across the mountain tops of the Secret Aerie you will find needle sprites. Bring me some of the hardest needles from them you can find.\n\nWith them I can attempt an acupuncture technique that should purge the poison from his body and accelerate his regeneration.", objectives = "Collect 10 Sturdy Needles.", progress = "My herbs are the only thing keeping Vol'jin from death. I dare not leave his side.", completion = "Very good. These should work nicely." }
WordHunterWoW_QuestEN[32319] = { title = "Find Thrall!", description = "<Vol'jin half opens an eye and begins to move his lips as if to speak.  Though no sound comes, you decipher two words.>\n\nFind Thrall.\n\n<With an effort, Vol'jin thrusts a hearthstone into your hands and then passes out.>", objectives = "Find Thrall by using Vol'jin's Hearthstone.", progress = "You have come a long way to see me, <race>. Speak.", completion = "<Thrall stares at the stone you have handed him.>\n\nVol'jin's hearthstone? My friend, has it come to this?" }
WordHunterWoW_QuestEN[32320] = { title = "The Horde Is Family", description = "This hearthstone was part of a conversation Vol'jin and I shared a long time ago.\n\nHe believes his people are in danger. I don't know what all has transpired in my absence, but I can at least do this for my friend.\n\nCome, {name}, travel with me to the Echo Isles. We must make sure that the Darkspear are safe.", objectives = "Escort Thrall to the Echo Isles.", completion = "Vol'jin has saved my life many times in the past. To see my own Kor'kron used against his people cuts deeper than I can put into words." }
WordHunterWoW_QuestEN[32321] = { title = "The Monkey King", description = "Ever since the Horde captured the Divine Bell I have been searching for a means to counter its power.\n\nMy research got as far as this tomb. I am going inside. If you follow me, I will share the rest as we go.\n\nIf we get separated, meet me back here at the entrance to the tomb. Speak to me when you are ready to proceed.", objectives = "Help Anduin Wrynn find the Monkey King in the Valley of Emperors.", completion = "You come asking for the Monkey King?\n\nLet us see how well you ookin' sing.\n\nWho are you, so tiny and boring?\n\nYour cause is silly! You leave me snoring.\n\nThree riddles I will ask,\n\nThese riddles are a task,\n\nFinish each without pause,\n\nAnd we shall see if I help your cause." }
WordHunterWoW_QuestEN[32324] = { title = "Seek the Signal", description = "The soulstone shards fuse together easily in your hands.\n\nStrangely, no soul is stored within the stone. Instead, the stone seems to be drawing power from somewhere in Shadowmoon Valley. Looking east, you feel the power linked beyond the mountains, to the very gates of the Black Temple.", objectives = "Follow the soulstone to the gates of the Black Temple." }
WordHunterWoW_QuestEN[32325] = { title = "Infiltrating the Black Temple", description = "It's clear that Jubeka's soulstone has lead you here to the Black Temple. \n\nThe question remains... why?\n\nThe only remaining option is to head inside and figure out why they were here.", objectives = "Look for Jubeka's mark on the main entrance of the Black Temple. Once inside, speak to Jubeka at the Temple Summit.", completion = "You have done more for this world than you can know, <class>. It is... something of a shame Kanrethad met this end. A shame, but inevitable." }
WordHunterWoW_QuestEN[32326] = { title = "Insertion", description = "{name}! You'll do perfectly.\n\nWe know where the Alliance have hidden the Divine Bell. We've already inserted an agent into enemy territory, we just need you to help him execute his mission.\n\nPack up, {name}. You're headed to Darnassus.", objectives = "Use the Sunreaver Portal in Domination Point to secure a teleport to Darnassus.", completion = "<name>! So glad Nazgrim selected you.\n\nIt's taken a great deal of the Horde's effort to get you here through Jaina's traps. Maintaining our illusion this close to Darnassus is considerably expensive.\n\nFurthermore, the Sunreavers of Dalaran are risking their neutrality by assisting the Horde with this operation.\n\nIn other words, we expect only the best from you." }
WordHunterWoW_QuestEN[32327] = { title = "The Darnassus Mission", description = "The Divine Bell is in the city. We don't want to cause a scene, we just want the artifact. I need you to find a way in, WITHOUT getting caught. That means no mounts, no flying, no fighting.\n\nI can provide aid. I will magically cloak you, so you may move with stealth. I will also give you a small charm that you may use to return to safety, should you get in trouble.\n\nNow go, {name}. Go, locate the bell, and tag it to be teleported back with you.", objectives = "Locate the Divine Bell.\n\nYou may use the Silvermoon Charm to return to Fanlyr if you get in trouble.", progress = "The bell, <name>!", completion = "Well executed, <race>! I knew we could count on you.\n\nNow to get off this wretched tree." }
WordHunterWoW_QuestEN[32328] = { title = "Victorious Return", description = "The portal by my side will return you safely to Domination Point. I will return behind you; I must clean up our tracks a bit before we leave, so that Proudmoore doesn't discover our involvement.", objectives = "Report your success to Nazgrim at Domination Point in Krasarang Wilds.", completion = "You found the bell! And Fanlyr teleported it to Silvermoon for study, as instructed? The Horde will put this to good use.\n\nYou have done the Horde a great service today. Lok'tar, friend!" }
WordHunterWoW_QuestEN[32329] = { title = "Get My Results!", description = "Ah, {name}. The Warchief has instructed me to dispatch you to Silvermoon.\n\nHe grows impatient with the progress of Lor'themar's research and feels they might benefit from your... unique... experiences with the mogu.\n\nGo to Silvermoon and demand that Lor'themar increase the speed of his research.", objectives = "Speak with Lor'themar Theron in Silvermoon City.", completion = "The Warchief \"demands\" progress? His impatience is growing more destructive with each command.\n\nAs it stands, we could use your expertise." }
WordHunterWoW_QuestEN[32330] = { title = "What's in the Box?", description = "We are trying to uncover the secrets of one of the mogu artifacts Garrosh insisted we investigate. It is proving most difficult, as anyone who probes it magically is greatly affected by raw, negative emotions.\n\nI called in the assistance of Arch-mage Aethas of the Sunreavers in the hopes that he and Rommath could crack this puzzle. They asked for you specifically - apparently you have some relevant experience?\n\nGo to the chamber below Farstrider Square east of here and see if you can assist them.", objectives = "Assist with Aethas and Rommath's experiment.", completion = "This reckless use of my people by Garrosh is becoming intolerable. If you had not been here to assist I dread to think what might have happened." }
WordHunterWoW_QuestEN[32331] = { title = "The Kirin Tor", description = "{name}, King Varian has asked that I send you after his son to Dalaran. He believes you can help negotiate the withdrawal of blood elves there.\n\nThese \"Sunreavers\" claim fealty to the Horde and represent a major threat to the war effort.\n\nNow that our very own Jaina Proudmoore is in charge of the Kirin Tor it should be easy to convince her to remove this Horde threat to her city.\n\nUse the portal here in Lion's Landing to go to the Purple Parlor and lend what aid you can to Prince Anduin.", objectives = "Use the Portal to the Purple Parlor in Lion's Landing and meet with Anduin Wrynn.", completion = "I am glad to see you friend. While I have learned much about diplomacy I think Jaina is too familiar with my tactics.\n\nI could use a friendly hand in resolving this conflict." }
WordHunterWoW_QuestEN[32332] = { title = "The First Riddle: Mercy", description = "So, you wake up the Monkey King for a mallet hmmm? Answer first, these riddles three, and then the mallet you shall see.\n\nFirst riddle!\n\n  \"Softly singing a song of pain\n\n    There is a creature tortured and lame.\n\n    Way down south and beyond the wall,\n\n    It hides from its wikket masters' call.\n\n    Seek out the creature sad and somber,\n\n    And free it from its untamed amber.\"\n\nBring me the untamed amber.", objectives = "Find the object the Monkey King described in his riddle.", progress = "Ah, the wise-ish thing returns. Have you my amber?", completion = "Ah! Amber! Fresh and untamed. Did you kill to get it? But of course.\n\nThough free, the untamed amber is a dangerous thing, and many might die because of it.\n\nMercy comes in many forms, like spikes and mantid and really ookin' spooky storms." }
WordHunterWoW_QuestEN[32333] = { title = "The Second Riddle: Fellowship", description = "You want to stop the Divine Bell? We need the mallet first.\n\nYou want the mallet? We need to be friends first.\n\nYou want to be friends? We need a Metal brew first. \n\nYou want a Metal brew? You need to go to the Shrine of Fellowship first. \n\nYou want to go to the Shrine of Fellowship? Great! It's in the Jade Forest southeast of the Tian Monastery.\n\nRing the bell and get the Monkey King some brew while there. Oh... you may have to fight for it.", objectives = "Obtain Metal Brew.", progress = "You have the Metal Brew?", completion = "The Metal Brew is strong and lasting, a brew to be shared with friends after a battle.\n\nEmperor Shaohao and his Monkey King had many a round in our day. Many battles, and many good friends." }
WordHunterWoW_QuestEN[32334] = { title = "The Third Riddle: Strength", description = "The mallet you seek is not a toy for children,\n\nIt calls trouble like the song of a siren.\n\nA test of strength the Monkey King will require,\n\nBefore you receive this tool of your desire.\n\nAt the Temple of the White Tiger you will find\n\nA challenger to test how well you are resigned\n\nStep through the main door and then turn right down the ramp\n\nChallenge the ook waiting for you there like a champ!", objectives = "Defeat the Challenger at the Tiger Temple.", completion = "Why engage in duelery? Why engage in foolery?\n\nYou ask the Monkey King for an artifact of power, I have to make sure when the time comes you will not cower. One tough dooker you think you might ookin be, but against mogu, many will turn and flee." }
WordHunterWoW_QuestEN[32335] = { title = "The Greatest Prank", description = "So riddles three you answered me. Good good. The Monkey King is not so old that he tells just anyone his tricks.\n\nIt was the greatest prank ever!\n\nYou want to hear story of the Mallet and the Monkey? Too bad! No choice!", objectives = "Listen to the Monkey King's story.", progress = "What you think?", completion = "It looks like it is going to take us a few days to track all of these \"minions\" down.\n\nThank you for your help, <name>. Meet me in Lion's Landing in a few days and we will embark to track down these objects." }
WordHunterWoW_QuestEN[32336] = { title = "The Handle", description = "There once was a Chief named Ingoo Ingoo,\n\nWho beat me in a drink drink boogaloo.\n\nHe took the mallet's handle for winning,\n\nNot knowing you can't beat the King in drinking.\n\nMonkey King had to hide the mallet from the bell,\n\nBut Ingoo's children do not use the handle well.\n\nOver the years they have used the handle to do harm,\n\nNow we must find the current chief so we can disarm.\n\nGo south to Unga Ingoo, Monkey King meet you there.\n\nOnly wikkets show to a party with hands bare.", objectives = "Recover the Mallet Handle.", progress = "Ingoo was a great hozen. Good leader, nice parties, and good booze.", completion = "Artifacts not make people great. Artifacts allow people to be more of themselves. Good becomes gooder. Bad becomes badder. And Chief Ingoo Ingoo became worser." }
WordHunterWoW_QuestEN[32337] = { title = "The Head", description = "Monkey King receive word on where to find the head,\n\nThe hozen who got it has long since been dead. \n\nKunzen chiefs pass the relic from father to son, \n\nBut then virmen Skiggit came and the head it won. \n\nNow the wikket worships it in a hollow. \n\nSince it was too ookin' big for him to swallow. \n\nI sent a royal finder north to find him and stand. \n\nLook for finder in mountains west of the Heartland.", objectives = "Recover the Mallet Head.", progress = "You got head?", completion = "What virmen do not understand, they worship, fight or flee.\n\nI should send them a few statues of me." }
WordHunterWoW_QuestEN[32338] = { title = "The Harmonic Ointment", description = "Legends are not born, they are made.\n\nMuch like your next target, a mogu named \"The Blade.\" \n\nIn his bags you will find,\n\nAn ointment whose sound plays with the mind.\n\nBring this nibby ointment to the Monkey King!\n\nAnd with it, he shall make the mallet sing!\n\nTravel north along the wall, and when you reach the end, turn left.", objectives = "Recover the Harmonic Ointment.", progress = "How the mogu found the ointment is a wonder.\n\nBut a lot has happened since the world tore assunder.", completion = "Woot woot!" }
WordHunterWoW_QuestEN[32339] = { title = "Rebuilding the Mallet (Tracker)", description = "Time for the fixing and then time for the mixing!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Obtain the Harmonic Mallet." }
WordHunterWoW_QuestEN[32340] = { title = "Plunder the Black Temple", description = "While Akama and his men are dealing with the demons, there is nobody to stop you from stealing a relic or two...", objectives = "Loot everything you can grab and reach the end of the Den of Mortal Delights.", completion = "You've looted everything you could grab on your way up. Time to tally up your plunder and hide it before Akama catches up..." }
WordHunterWoW_QuestEN[32341] = { title = "Demonstrate Your Power", description = "Akama and his men are under siege by the forces you unleashed in the Reliquary of Souls. \n\nDemonstrate your power to Akama by saving his men from the demonic forces!", objectives = "Slay the demons who are attacking Akama's men in the Halls of Anguish." }
WordHunterWoW_QuestEN[32342] = { title = "The Spirit Trap", description = "Within the ruins we have identified several powerful mogu artifacts. They trapped spirits within, probably to use them in some ritual or conjuration.\n\nThey are a type of device that we haven't identified and desperately need to study - they may reveal more of the secrets of the mogu's spirit binding techniques. \n\nGo, find us a few samples so that we may continue a proper study.", objectives = "Collect 3 Spirit Traps.", progress = "Have you brought the traps?", completion = "Ahh, yes. Hmm. Hand that over. Carefully." }
WordHunterWoW_QuestEN[32343] = { title = "Ogudei's Lieutenants", description = "There are two extremely powerful mogu spirits that the Alliance unearthed in their ineptitude.\n\nThese are choice targets for us, {class}. If you kill them and collect each of their essences, we could make great progress on decoding the history of this strange ruin.", objectives = "Collect Meng-do's Essence and Gen-li's Essence in the Ruins of Ogudei.", progress = "The essence isn't going to make itself, <race>.", completion = "What treasures! With any luck, the spirits will return and we will be able to sample their essence further." }
WordHunterWoW_QuestEN[32344] = { title = "It Is A Mystery", description = "We have detected several... anomalies in these mines, of an arcane or spiritual nature. They are disrupting our attempts to discern the nature of the magic used in the spirit binding rituals here.\n\nThey are quite elusive, but we've managed to isolate the arcane signature of one of these anomalies, and one of our mages has enchanted this bauble with its signature.\n\nTake the bauble. It will begin to glow more brightly as you approach the anomaly. Once you reach it, you can use the bauble to draw it out.", objectives = "Use the Arcane Bauble to find an anomaly within the Ruins of Ogudei.", progress = "We are still dealing with that anomaly! Hurry!", completion = "Ahh, yes. I received word from one of our researchers that they are no longer troubled by that anomaly. Well done." }
WordHunterWoW_QuestEN[32345] = { title = "We're Not Monsters!", description = "The Reliquary may have had a bad name in the past, but we're not monsters. We simply hold different views about archaeology than the Explorers' League.\n\nWe do focus on performing acts of heroism from time to time. So go, liberate some of the pandaren slave spirits in the ruins.", objectives = "Liberate 14 Troubled Slave Spirits.", completion = "Ah, good work. As much as it may seem trivial in comparison to our larger research goals, it is important that we maintain appearances, <name>." }
WordHunterWoW_QuestEN[32346] = { title = "Oi Ain't Afraid o' No Ghosts!", description = "Look. We got a nasty problem here, and ol' Troteman back at Lion's Landing's gonna throw us out of here if we don't get things under control.\n\nGive us a hand, please!", objectives = "Kill 12 Spiritbound Mogu.", completion = "Alright! We'll be back up and runnin' in no time!" }
WordHunterWoW_QuestEN[32347] = { title = "Eviction Notice", description = "The bloody Reliquary's snuck into the ruins. They've taken the lower section and are conducting all kinds of magical shenanigans down there.\n\nIt's time we gave 'em an eviction notice, in the form of your boot in their rear!", objectives = "Kill any 10 members of the Reliquary in the Ruins of Ogudei.", progress = "Did ye' deliver the message?", completion = "Ha! That should send 'em runnin' back to Silvermoon with their tail 'tween their legs!" }
WordHunterWoW_QuestEN[32348] = { title = "Kick 'em While They're Down", description = "The Alliance may think they have a stranglehold on the ruins, given that their base of operations is close.\n\nWe're going to disabuse them of that notion. Go take out some of their guards.", objectives = "Kill 12 Lion's Landing military units.", completion = "Oh, what a fine day. Alliance fools defeated, and our research is moving ahead quite nicely." }
WordHunterWoW_QuestEN[32351] = { title = "Echoes of Thunder", description = "Ah, {name}, we meet again. I have heard some wondrous news.\n\nHigh Chieftain Baine Bloodhoof of the tauren has arrived here on Pandaria.\n\nHe meets with Warchief Garrosh Hellscream and Regent Lord Lor'themar Theron now, at the Shrine of Two Moons in the Vale of Eternal Blossoms.\n\nHe sent me a strange request - to send him a loyal champion of the Horde, capable of combat... and discretion.\n\nI can think of none better to send than you. Speak to Tak-Tak if you seek transport.", objectives = "Find High Chieftain Baine Bloodhoof at the Shrine of Two Moons. Speak to Tak-Tak at Domination Point for transportation.", completion = "Well met, <class>. You were sent from Domination Point? Very well. We have much to discuss." }
WordHunterWoW_QuestEN[32352] = { title = "A Gathering Storm", description = "If General Nazgrim sent you, then I trust you are capable of discretion.\n\nWhen I arrived here, I found Garrosh... experimenting... with some ancient power that he found in the mountains to the north.\n\nHe believes that this \"sha\" can strengthen our soldiers.\n\nUnfortunately, so far the results have been quite the opposite.\n\nOur troops are erupting into random violence. Go and interrogate them. If they threaten you, be prepared to defend yourself.", objectives = "Confront 6 Sha-Touched Grunts.", progress = "There is great power here... Why is it that so many fear it?", completion = "You bested my defenders? Finally, one who can control his hatred and violence!\n\nI need more men like you." }
WordHunterWoW_QuestEN[32355] = { title = "The Harmonic Mallet", description = "{name}! Prince Anduin has somehow slipped his guards again. His control over the light is greatly increasing.\n\nHe was last seen heading to Kun-Lai Summit. He gave our mages the slip around the Valley of Emperors.\n\nCan you find him? He insists on searching for what he claims is a counter to the Divine Bell. Perhaps you can talk some sense into him before he seizes control of your mind and has you dance your way back here.\n\nTalk to Fennie for a ride into the mountains.", objectives = "Find Anduin at the Tomb of Conquerors. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", completion = "I am glad you made it, my friend. I could really use your help with what is to come. My father would prefer I remain in the safe custody of his legion.\n\nBut if there is one thing Pandaria has taught me, it is a few people in the right place at the right time can make a bigger difference than the greatest of armies." }
WordHunterWoW_QuestEN[32356] = { title = "Tracking Event: Ambassadors Summoned", description = "It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly.\n\nI'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "See the scouts off, then speak to Big Lu." }
WordHunterWoW_QuestEN[32357] = { title = "Tracking Event: Event Complete", description = "It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly.\n\nI'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "See the scouts off, then speak to Big Lu." }
WordHunterWoW_QuestEN[32358] = { title = "The Soulcore", description = "The naaru looks at you expectantly and an image of the soulcore appears in your mind.", objectives = "" }
WordHunterWoW_QuestEN[32359] = { title = "The Eye of the Naaru", description = "The soulcore has transformed into a crystal. This is clearly the artifact that Kanrethad and Jubeka were attempting to create, but you still have no idea where they went.\n\nSeek out the Black Prince in the Tavern of the Mists and see if you can acquire some information on where they went.", objectives = "Bring the Eye of the Storm to Wrathion in the Tavern in the Mists." }
WordHunterWoW_QuestEN[32360] = { title = "Awaiting the Black Harvest", description = "{name}, I have never heard of this Council of the Black Harvest. However, the fact that they are interested in my father's power concerns me greatly.\n\nHowever, I do have... contacts, who may be able to help us track them down. Most of my agents are preoccupied with the Alliance and Horde battle in Krasarang. Once that has settled down, I will help you.\n\nFor now, feel free to leave the Naaru relic in my protection, or not - just don't end up dead somewhere at the bottom of a swamp.", objectives = "Wait for Wrathion to contact you.\n\n[To Be Continued in Patch 5.2...]<name>, I have never heard of this Council of the Black Harvest. However, the fact that they are interested in my father's power concerns me greatly.\n\nHowever, I do have... contacts, who may be able to help us track them down. Most of my agents are preoccupied with the Alliance and Horde battle in Krasarang. Once that has settled down, I will help you.\n\nFor now, feel free to leave the Naaru relic in my protection, or not - just don't end up dead somewhere at the bottom of a swamp." }
WordHunterWoW_QuestEN[32361] = { title = "Tracking Event: Event Complete", description = "It's time for Sully and I to leave. We'll keep our eyes out for any sign of the White Pawn and report back shortly.\n\nI'm afraid I must leave you in charge while Admiral Taylor is recovering. Learn as much as you can from these jinyu while we are away. I expect a full report when we return.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "See the scouts off, then speak to Big Lu." }
WordHunterWoW_QuestEN[32362] = { title = "The Fate of Dalaran", description = "Jaina is refusing to hear me out. Father was hoping I would have some pull with her, but I think she still sees me as a child.\n\nYou, on the other hand, are a hero of the Alliance and I know she respects your deeds.\n\nIs there something you can say to her to convince her we need her help?", objectives = "Speak with Jaina Proudmoore and hear her story.", progress = "We are not asking for military forces. But we do need the magical support of Dalaran if we are to stop Garrosh's reckless advances.", completion = "Thank you for your help, hero. I hear the wisdom in Jaina's words.\n\nLet's hope her faith in the Sunreavers is justified." }
WordHunterWoW_QuestEN[32363] = { title = "The Kun-Lai Expedition", description = "I have another message for you from High Chieftain Bloodhoof.\n\nIt seems you've made quite the impression on him.\n\nHe travels with the Warchief's vanguard into Kun-Lai Summit, to the north. They have set up an outpost, Garrosh'ar Advance, just east of One Keg.\n\nYou had best not keep him waiting. Speak to Tak-Tak for swift travel.", objectives = "Find Baine Bloodhoof at Garrosh'ar Advance. Speak to Tak-Tak at Domination Point for transportation.", progress = "Thank you for coming so quickly.", completion = "Thank you for coming, <name>." }
WordHunterWoW_QuestEN[32364] = { title = "Pandaren Medicine", description = "While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien.\n\nI am needed here, so I have no choice but to ask you to find the ingredients for me.\n\nThe recipe can be found in a book near my other things, just behind me.", objectives = "Find the recipe for Memory Wine.While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien.\n\nI am needed here, so I have no choice but to ask you to find the ingredients for me.\n\nThe recipe can be found in a book near my other things, just behind me.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32365] = { title = "Tracking Event: Epilogue Complete", description = "", objectives = "" }
WordHunterWoW_QuestEN[32366] = { title = "A Lick of Fire", description = "6 Ruqin Firewine. This intense liquor helps relax the mind, allowing the recovery of past memories.\n\n<Scrawled along the side is another note.>\n\n(Note: May result in a terrible hangover.)", objectives = "Collect 6 Ruqin Firewine." }
WordHunterWoW_QuestEN[32367] = { title = "A Bit of Yak", description = "3 Fresh Yak's Milk. Helps strengthen teeth and bones. Allows imbibers to return from their dream state.\n\n<The now-familiar handwriting now leaves a cryptic message.>\n\n(Why do all yaks look alike!?)", objectives = "Collect 3 Fresh Yak's Milk." }
WordHunterWoW_QuestEN[32368] = { title = "Memory Wine", description = "The tincture is ready. Now, drink.", objectives = "Drink the Memory Wine and witness Shan Kien's Past.", progress = "What did you see?", completion = "What did you see, <class>?" }
WordHunterWoW_QuestEN[32369] = { title = "Secrets of the Past", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32370] = { title = "The Kun-Lai Expedition", description = "Glory to the Alliance, {class}. We are making gains against the Horde in the Krasarang Wilds, albeit slowly.\n\nWhile we hold the front here, we need your help to fight a different battle - one that strikes at our enemy's heart.\n\nOur SI:7 informant, Agent Connelly, has sent word that a Horde vanguard is moving up into the northern reaches of Kun-Lai Summit.\n\nGo without delay. Make contact with Agent Connelly in the field, and find out what is going on.\n\nSpeak to Fennie over there for a flight in.", objectives = "Find Connelly at the Grummle Bazaar. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", completion = "<You do a doubletake when the Pandaren suddenly speaks with Connelly's voice.>\n\n'Bout time, laddie! I've been waitin' fer ya to show up.\n\nThese Pandaren are good people but can't mix a martini fer nothin'." }
WordHunterWoW_QuestEN[32371] = { title = "Memory Wine", description = "<The radio static crackles, and Agent Connelly continues speaking.>\n\nNow comes the real challenge, laddie. \n\nHead on over to the center of camp and see what you can overhear.", objectives = "Use the Kor'kron Disguise to enter the camp. Then drink the Memory Brew and witness Shan Kien's past.", completion = "Back so fast, rookie? So what did ye learn?" }
WordHunterWoW_QuestEN[32372] = { title = "De-Subjugation", description = "The Kor'kron have been trained to be the finest, most loyal soldiers of the Warchief. Their presence here means that Garrosh fears an uprising.\n\nVol'jin and his people are as much a part of the Horde as any orc.\n\nWe must break this occupation and free the trolls. It pains me to say this, but you must eliminate enough of the Kor'kron so that the trolls can retake their city. Then meet me at Darkspear Hold so we might challenge their officer directly.", objectives = "Defeat 10 Kor'kron Overseers, 5 Kor'kron Subjugators, and Gul'tar the Subjugator.", progress = "How did it come to this? It is as if the word \"honor\" is lost on these orcs.", completion = "The orcs have changed. My Horde has changed. Do I kill my fellow orcs until it is once again \"my\" Horde? Do I have any right to try force the Horde to be what it once was?\n\nThese are troubling times. But for now, I must see to Vol'jin's people." }
WordHunterWoW_QuestEN[32373] = { title = "The Measure of a Leader", description = "We've progressed to a new part of the Pandaren campaign. The Alliance has landed on the shores with the full might of its navy. Your King aims to check Horde aggression in this new land.\n\nGarrosh Hellscream is propelling the Horde headfirst into battle, but King Varian Wrynn is a little more of a mystery to me. Do you have a moment? I'd like to talk to you about this leader of yours.", objectives = "Speak with Wrathion at the Tavern in the Mists.", completion = "I am curious to see how King Wrynn rises to the occasion.\n\nI am even more curious to see what YOU are capable of. Let's find out..." }
WordHunterWoW_QuestEN[32374] = { title = "The Prince's Pursuit", description = "My goal is an expedient end to this costly war. Prove to me that the Alliance deserves to win. Show me your prowess on the battlefield.\n\nYou are not fighting some abstract force like the sha: You are facing your enemy head-on, eye-to-eye.\n\nWill you triumph?", objectives = "Kill Horde forces along the southern shores of Krasarang Wilds until you are Revered with the Black Prince.", completion = "Marvelous! Even in the midst of the chaos of battle you've proven that an individual can have an impact. The Horde has learned that their actions in Pandaria will not be unopposed.\n\nI believe it is time for a more substantial challenge..." }
WordHunterWoW_QuestEN[32375] = { title = "A Dash of That", description = "100 Buttonbelly Mushrooms. Must be freshly harvested from a wet, dark place.\n\n<Scrawled along the edge of the page is a hand-written note.>\n\nFungus is very good for the health! (Or it might kill you, cause serious illness, rash, hallucination, or loosen bowels. Note to self - MUST be careful when selecting wild mushrooms!)", objectives = "Collect 100 Buttonbelly Mushrooms." }
WordHunterWoW_QuestEN[32376] = { title = "To the Valley!", description = "This sealed communication was sent for you, along with urgent orders to travel to the Valley of Emperors in Kun-Lai Summit.\n\nThis looks serious. I'd not delay if I were you.\n\nSpeak to Tak-Tak for transportation.", objectives = "Find your \"Friend from Silvermoon\" at the Valley of Emperors. Speak to Tak-Tak at Domination Point for transportation.", completion = "Ah, good. You have come. \n\nAgain, I apologize for the cryptic note - but Garrosh is increasingly distrustful of us. I do not want this operation disturbed by hasty action on his part." }
WordHunterWoW_QuestEN[32377] = { title = "A Kor'kron In Our Midst", description = "Garrosh is hell-bent on finding that Divine Bell. I wouldn't be surprised if he tore Kun-Lai Summit apart to find that artifact.\n\nThe Warchief's called a gathering at Garrosh'ar Advance, just to our north.\n\nI need to stay here to monitor troop movements, so you'll have to infiltrate their camp and overhear their discussion.\n\nGo to Garrosh'ar Advance and steal some Kor'kron Armor from Reavers, Honor Guards, and Scouts.\n\nTake this radio earpiece. Don't contact me... I'll contact you.", objectives = "Collect 1 Kor'kron Helmet, 1 Kor'kron Armor, and 1 Kor'kron Boots, then combine them into a Kor'kron Disguise.", progress = "Just as you look at the assembled Kor'kron disguise, your radio earpiece crackles.", completion = "<Agent Connelly's voice comes over the radio.>\n\nEy, you're good! I knew those Kor'kron wouldn't be a problem fer ya. Couldn't've done much better meself." }
WordHunterWoW_QuestEN[32378] = { title = "Clearing a Path", description = "First thing's first. If we're going to take the leader captive, we'll need to thin the numbers of his agents.\n\nBe careful. These mogu are particularly dangerous - they appear to be manipulating the sha in ways we haven't seen before.", objectives = "Kill 10 Korune Mogu.", completion = "Good. We should be ready to make our move." }
WordHunterWoW_QuestEN[32379] = { title = "Legacy of the Korune", description = "I'm not prepared to throw away more of our people fighting against an enemy we don't know or understand. \n\nSee if you can find any clues in the area as to who exactly these \"Korune\" mogu are. A contingency in case this operation doesn't go as planned.", objectives = "Find the document Legacy of the Korune in the Valley of the Emperors, and collect the Sealed Korune Artifact and Korune Orders from Korune Mogu.", progress = "Have you found anything on the mogu?", completion = "Good. There's quite a bit to pore through here... \n\nI will have the Reliquary investigate these. Surely we can use them to discern more of the secrets of these Korune mogu." }
WordHunterWoW_QuestEN[32380] = { title = "The Best Around", description = "We're going to need help if we hope to figure out Garrosh's plans for Pandaria.\n\nI have someone specific in mind, but he will not be easy to convince.\n\nAgent Connelly considers himself retired, but one does not simply leave the SI: 7. We've had an undercover agent following his every move for months.\n\nCurrently, he is disguising himself as a high roller at Bizmo's Brawlpub. Something about settling an old debt.\n\nMeet with our undercover agent in the Brawler's Guild.", objectives = "Report to undercover agent Townsley in Bizmo's Brawlpub in the Stormwind side of Deeprun Tram.", progress = "So you think you are going to talk Connelly out of retirement? Good luck!", completion = "Following Connelly has been interesting to say the least. The man is a master of disguise!\n\nTalking him into joining you won't be the hard part, <class>. Figuring out which of these lively individuals is him will be next to impossble." }
WordHunterWoW_QuestEN[32381] = { title = "To Catch A Spy", description = "Now, I could tell you who Connelly is, but that would be too easy! To catch a spy you have to think like a spy.\n\nYou have to pass the test first!\n\nThe small things can say a lot about a person. It's all in the details.\n\nI'm going to give you a drink to deliver. I will give you a small detail about something the recipient is wearing. From there it will be up to you.\n\nBe careful who you pick to give drinks to. People here tend to get pretty hostile if you give them the wrong order!", objectives = "Deliver the Pink Marmot, the Mogu Melon Twist, and the Rusty Dagger to the correct patron.", progress = "You learn to look at the details when you barkeep.", completion = "You have a keen eye, <class>! I think you are ready to meet Connelly." }
WordHunterWoW_QuestEN[32382] = { title = "He's In Deep", description = "Agent Connelly has managed to infiltrate Garrosh's camp in Kun-Lai! He's been following their every move.\n\nConnelly requested you specifically to assist him in gathering some vital intelligence.\n\nHe sent along a disguise for you. Make sure you put it on before approaching the camp! It will no doubt be heavily guarded.\n\nHe insists you will know him when you see him. Something about your keen eye for details...\n\nGo talk to Fennie over there for a drop-off.", objectives = "Meet Connelly in Kun-Lai Summit. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", completion = "You've arrived just in time. From the intel I've gathered, Garrosh is hot on the trail of some sort of ancient mogu artifact of power.\n\nIf we can figure out what he's after, we can stop him from getting it!\n\nWe have to act fast to gather as much information as possible." }
WordHunterWoW_QuestEN[32383] = { title = "Bugging Out", description = "I've managed to plant a few bugs around the camp, but there could always be more.\n\nI disguised the bugs to look like statues. They blend in perfectly with the other artifacts lying around.\n\nYour disguise should allow you to move freely around the camp. Just don't go near the dog and don't linger around Garrosh! Nero and Garrosh will see through your disguise.\n\nIf you get caught I can't help you. I can't compromise the mission!", objectives = "Plant the Cleverly Disguised Bugs in the large tent, near the small tents, and in the supplies.", progress = "How'd it go?", completion = "Well done! Everyone always underestimates the little guys and it is always a grave mistake!" }
WordHunterWoW_QuestEN[32384] = { title = "Trapping the Leader", description = "It is time to make our move. Go to the Tomb of Shadows, weaken him, and take him captive.\n\nI will stay here in case Garrosh arrives. He must be delayed so that we can take our prize before he destroys it in his anger.\n\nHurry!", objectives = "Weaken and capture Shan Kien at the Tomb of Shadows in Kun-Lai Summit.", progress = "Move, <name>!", completion = "We managed to capture our quarry. \n\nIn truth, though, I am not sure what our next move should be. I will contact the leaders of our allies and see if they have ideas - I don't know that our arcane talents are going to pry the secrets of our mogu captive." }
WordHunterWoW_QuestEN[32388] = { title = "A Change of Command", description = "There's an orc general I've been keeping a close eye on. Warlord Bloodhilt curried a lot of favor with Garrosh Hellscream by beating back an Alliance advance in Southern Barrens. He's now entrenched within the fortress at Domination Point.\n\nI doubt the Alliance can take him out. But... you've proven me wrong before.\n\nIf you wish to finish him off, bring friends. Lots of friends.  ", objectives = "Kill Warlord Bloodhilt at Domination Point in Krasarang Wilds. You will need a group.", completion = "<Wrathion grins.>\n\nYou were being tested, <class>. I knew you were capable of great things by yourself.\n\nBut you have proven to me that you have the makings of a leader, cobbling together support among a group of strangers in the midst of a battlefield.\n\nThe Alliance is fortunate to have you." }
WordHunterWoW_QuestEN[32389] = { title = "The Lion Roars", description = "This is a global war, {name}. It has spilled onto Pandaria, and it has set hot spots across Kalimdor and the Eastern Kingdoms ablaze. How will you fare on an organized battlefront? I would like to see for myself.\n\nI look forward to hearing your report from the front lines.", objectives = "Win battles at the Temple of Kotmogu and the Silvershard Mines.", completion = "<Wrathion hungrily listens to tales of your exploits on the battlefield, his eyes gleaming bright red.>\n\nOhh... oh! Incredible! In the very eye of battle, one's true heart is revealed.\n\nYou do not disappoint, <name>.\n\nNeither does your Alliance." }
WordHunterWoW_QuestEN[32390] = { title = "Call of the Packmaster", description = "{class}, through your eyes I've been able to witness the fighting along the coast, and the epic course of battles around the world. You've been very patient... and most informative.\n\nI've also been keeping a close eye on your King. Would you be interested to hear what I've learned?", objectives = "Speak with Wrathion.", completion = "<A strange device sits within an ornate silk-lined chest. It appears as though it can be fastened to your sha-touched weapon as an additional upgrade. The empty socket is disconcerting; you feel as though it is staring back at you. A single, hollow, judgmental eye...>" }
WordHunterWoW_QuestEN[32391] = { title = "The Ruins of Korune", description = "Garrosh sent a hundred riders to search the northern coast of Kun-Lai Summit, to seek a mogu crypt matching the one you saw in Shan Kien's memory.\n\nOut of those, one found the resting place of the Divine Bell.\n\nBlademaster Ishi is leading an advance party to secure the bell now.\n\nGo and assist him. Defend that artifact from anyone who might stand in your way!\n\nSpeak to Tak-Tak without delay. He can take you there.", objectives = "Find Ishi at the Ruins of Korune. Speak to Tak-Tak at Domination Point for transportation.", completion = "The Alliance beat us here. How could this happen?" }
WordHunterWoW_QuestEN[32392] = { title = "The Divine Bell", description = "If the Alliance thought they could steal the Divine Bell from us, they were wrong!\n\nEven now, we have them trapped in the crypts beneath us.\n\nDeath will be the price they pay for defying us.\n\nCome, {class}. Let us show them the error of their ways.", objectives = "Kill Sarannha Skyglaive.", completion = "Darnassus, is it?\n\nThe Alliance believes they have won the day. Now, when their arrogance is at its greatest, is our opportunity to pluck the prize from their fingers." }
WordHunterWoW_QuestEN[32393] = { title = "The Ruins of Korune", description = "It's time for our boldest move yet, {name}.\n\nSince you acquired intel on the location of the Divine Bell, we've amassed a top team to excavate the artifact without delay.\n\nCommander Sarannha Skyglaive leads the expedition into the northern-most reaches of Kun-Lai Summit.\n\nJoin them at once, and use whatever skills you need to make the endeavor a success.\n\nGood luck, {class}. I don't need to tell you how important this mission is to the Alliance.\n\nSpeak to Fennie. She'll get you there quickly.", objectives = "Find Sarannha Skyglaive at the Ruins of Korune. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", progress = "Looks like we're well ahead of the Horde. Not surprising, but we must act swiftly.", completion = "We blasted the doors open moments ago, <class>. You arrived just in time to join us for the excavation." }
WordHunterWoW_QuestEN[32394] = { title = "The Divine Bell", description = "There's no telling what lies below, so I will lead the initial scouting party myself.\n\nIf your report was correct, then the Korune mogu hid the Divine Bell in the rooms below our very feet.\n\nI have a feeling they would not have left such a precious artifact unguarded.\n\nI could use a capable {class} such as yourself to watch my back. Let me know when you're ready.", objectives = "Kill Dreadweaver Avartu and recover the Divine Bell.", completion = "Fantastic work, <name>. I could not even imagine the atrocity that Garrosh would commit if this bell were to fall into his hands.\n\nToday, we have secured a safe future for the Alliance. I will see to it that the bell makes it safely to Darnassus.\n\nI will extoll your deeds to the King." }
WordHunterWoW_QuestEN[32395] = { title = "Tracking Event: Saw Avartu", description = "", objectives = "" }
WordHunterWoW_QuestEN[32396] = { title = "Uncompletable Binding Quest [DND]", description = "", objectives = "" }
WordHunterWoW_QuestEN[32397] = { title = "He Won't Even Miss It", description = "I've noticed Garrosh and that Reliquary blood elf carrying around some sort of journal.\n\nThe journal is never more than a stone's throw away. It must be important!\n\nIf you can cause enough of a distraction, you may be able to swipe the journal off the table.\n\nThese yaks might just do the trick. Give one of 'em a tap and they'll do the rest.\n\nJust be ready to move fast!", objectives = "Create a distraction in the camp and steal the Weathered Journal.", progress = "What did you find?", completion = "Phew! That was a close one! I never doubted you for a minute though.\n\nNow let me take a look at that journal..." }
WordHunterWoW_QuestEN[32398] = { title = "The Bell Speaks", description = "Your efforts have culminated in this moment, {class}.\n\nWarchief Garrosh gathers the most elite champions of the Horde in Kun-Lai Summit to witness the ringing of the Divine Bell.\n\nYou have more than earned the right to participate.\n\nGo now. The dawn of the new Horde begins today.\n\nSpeak to Tak-Tak. He should be able to secure your travel arrangements.", objectives = "Find Malkorok at Emperor's Reach. Speak to Tak-Tak at Domination Point for transportation.", completion = "I was wondering when you would arrive, <name>." }
WordHunterWoW_QuestEN[32399] = { title = "Breath of Darkest Shadow", description = "It is time, {name}. We have traveled a long path to reach this moment.\n\nToday, our Warchief, Garrosh Hellscream, will change the course of our people's history forever.\n\nToday, we witness the birth of Garrosh's Horde!\n\nDo not let anything interfere with the ceremony!", objectives = "Witness the ringing of the Divine Bell.", progress = "We cannot rely on fate or destiny. We must carve out our own future... the future that WE deserve!", completion = "They may have destroyed the Divine Bell, but I have taken the life of the Alliance's prodigal son!\n\nIt is nothing less than my own father would have expected of me.\n\nThis victory may have come at a high cost, but it is of little consequence.\n\nI will find other ways to destroy my enemies, and bring glory to the Horde!" }
WordHunterWoW_QuestEN[32400] = { title = "The Bell Speaks", description = "Horde forces are amassing in huge numbers at the Emperor's Reach, high up in the mountains of Kun-Lai Summit.\n\nThe area is an ancient mogu palace, and certainly a source of untold power.\n\nThis can only mean one thing. Garrosh is going to use the Divine Bell, and Anduin... and the Harmonic Mallet... are both missing.\n\nI have no doubt that the fool boy went north by himself.\n\nI don't have time to gather an elite force to detain him. You must go and stop Anduin.\n\nFennie can take you.", objectives = "Find Anduin at Emperor's Reach. Speak to Fennie Hornswaggle at Lion's Landing for transportation.", completion = "<name>! Just the <class> I was hoping to see. You couldn't have arrived at a better time." }
WordHunterWoW_QuestEN[32401] = { title = "Breath of Darkest Shadow", description = "Garrosh is right over there, and he's going to ring that bell at any moment.\n\nWe don't have time to wait for my father's army. This is our only chance to stop him!\n\nI'll attempt to appeal to his senses before resorting to using the Harmonic Mallet.\n\nCharge in whenever you're ready, {name}. I'll be right behind you.", objectives = "Defeat Ishi and destroy the Divine Bell.", completion = "<Anduin looks like a crumpled doll. He lays as still as a stone, and the only movement comes from the frigid air ruffling his fair, golden hair.>\n\n<You sit quietly for a while, until the cold settles into your bones. The bell is destroyed, but the silence is deafening.>\n\n<Out of the corner of your eye, you see the slightest flicker from the boy's hand. You lean in close. He breathes - but just barely! Anduin is alive!>" }
WordHunterWoW_QuestEN[32402] = { title = "The Situation In Dalaran", description = "The night elves learned that the Divine Bell was stolen. This much we anticipated.\n\nHowever, they've also found out that the \"neutral\" Sunreavers of Dalaran were complicit. Now, we've got a situation.\n\nI need you to go to Dalaran. Speak with Kromthar for a ride. You are to rendezvous with Grand Magister Rommath once you arrive.", objectives = "Speak with Kromthar to obtain a ride to Dalaran.", completion = "Good... you've arrived. It's not a good day to be Horde in Dalaran.\n\nJaina's called for the exile of all the Sunreavers. You and I are going to save as many as we can - including Archmage Aethas Sunreaver himself - and then get out of here as fast as possible." }
WordHunterWoW_QuestEN[32403] = { title = "It Starts in the Sewers", description = "Compared to the rest of the city, this part of the sewers is relatively calm. This is good - we can extract more Sunreavers in peace than we can in war.\n\nFind as many citizens as you can. Tell them that it is not safe here, that they must leave the city at once.\n\nAnd try to stay clear of the Silver Covenant. We don't want to cause a scene if we can avoid it. Not yet, anyhow.", objectives = "Evacuate 9 Sunreaver Citizens.", progress = "I think I see a few more Sunreavers over there...", completion = "Let's press on." }
WordHunterWoW_QuestEN[32404] = { title = "Violence in the Arena", description = "As I suspected, it gets worse up ahead. The Silver Covenant is outright attacking innocent Sunreavers!\n\nThis cannot stand. While our prime directive is to rescue Aethas Sunreaver, we must also protect as many blood elves as we can.\n\nI will continue to scout ahead. Fight well, {class}!", objectives = "Slay 6 Silver Covenant Enforcers and 4 Silver Covenant Spellbows.", completion = "So much bloodshed! In a place of peace!\n\nJaina has gone too far this time." }
WordHunterWoW_QuestEN[32405] = { title = "Hand of the Silver Covenant", description = "Every Sunreaver Jaina expels from this city is a new blade that fights for the Horde. For US.\n\nI'm off to gather more strong elves. You've proven your hand in combat thus far - go take care of that creep in the black market.\n\nWhen you're done, we'll meet at the ramp and prepare to go aboveground.", objectives = "Slay Sorin Magehand.", completion = "The first stage of our mission is complete. That was the easy part.\n\n<Rommath takes a deep, measured breath, then continues...>" }
WordHunterWoW_QuestEN[32406] = { title = "A Tactical Assault", description = "If we're to survive up above ground, we're going to need a base of operations.\n\nI'm going to try to take the center of the city. It's risky, but hopefully Jaina and the Silver Covenant won't expect it.\n\nStay by my side now, {name}.", objectives = "Follow Grand Magister Rommath into the center of Dalaran.", completion = "Now, let's move quickly." }
WordHunterWoW_QuestEN[32408] = { title = "The Silver Covenant's Stronghold", description = "I have it on good authority that Archmage Aethas Sunreaver is being held in the Silver Enclave, home of the Silver Covenant. Arcanist Rathaella holds him in captivity.\n\nMost Covenant agents are out slaughtering Sunreavers right now, which means our chance is ripe. Slay Rathaella, and spring Aethas from his prison.", objectives = "Slay Arcanist Rathaella.", completion = "We will continue saving Sunreavers for a while longer. Aethas' location may become clearer as we press on." }
WordHunterWoW_QuestEN[32409] = { title = "The Kirin Tor's True Colors", description = "Any pretense that the Kirin Tor might have had at being a \"neutral\" group can officially be discarded. I'm now hearing that Jaina's got Alliance troops stowed away near Antonidas Memorial.\n\nThe area's free of Sunreavers, but it still makes my blood boil to see such blatant favoritism from the Kirin Tor.\n\nGo visit the memorial, {name}... and give those Alliance dogs a good kick on your way through.", objectives = "Slay Lieutenant Corwin and 10 of his troops.", progress = "<Rommath looks displeased.>", completion = "Thank you for that, <name>.\n\nIt unsettles me to have to fight directly with the high elves of the Silver Covenant... but I never tire of slaying Alliance." }
WordHunterWoW_QuestEN[32410] = { title = "Krasus' Landing", description = "We can rescue as many Sunreavers as we want, but if they can't escape, then there's no point.\n\nThe Silver Covenant will certainly be subduing and killing the Sunreavers' dragonhawks. Put a stop to it.", objectives = "Free 6 Sunreaver Dragonhawks.", progress = "The depravity of this Silver Covenant sickens me. Attacking innocent creatures!", completion = "Well done, <name>. Well done." }
WordHunterWoW_QuestEN[32411] = { title = "The Remaining Sunreavers", description = "There's still a number of significant Sunreavers who haven't been accounted for. Odds are that they're in the Sunreaver's Sanctuary, caught by surprise.\n\n<Rommath hands you an artifact, clearly made by blood elf hands.>\n\nThe place is crawling with Silver Covenant. You'll need to get in, use the Tear to evacuate the VIPs, and then get out.\n\nStay alive, {name}.", objectives = "Use the Tear of the Sin'dorei on Uda the Beast, High Arcanist Savor, Magister Hathorel, Magister Surdiel, and Magistrix Vesara.", progress = "Be on the lookout for Aethas while you're in there.", completion = "Excellent. They should be waiting for us in Silvermoon when we return." }
WordHunterWoW_QuestEN[32412] = { title = "One Last Grasp", description = "We've looked everywhere he's likely to be, except for one place: the Violet Citadel.\n\nFind out if Archmage Aethas is being held within the citadel, {name}. We may get lucky. If not... at least we saved a number of lives today.", objectives = "Slay Mage-Commander Zuros, then escape from Dalaran.", completion = "Is this... <name>? What's going on here?" }
WordHunterWoW_QuestEN[32413] = { title = "A Return to Krasarang", description = "Wherever your loyalties might lie - with Rommath and I, with Garrosh, or elsewhere - one thing is true: your acts today were truly heroic.\n\nI can arrange for your transport back to Krasarang Wilds. Speak with me if you would like passage back to Pandaria, {name}.", objectives = "Report to General Nazgrim at Domination Point in Krasarang Wilds.", completion = "<Nazgrim listens as you recount the day's events.>\n\nWe take the bell... and the Alliance takes Dalaran. That escalated quickly.\n\nWar is coming, <name>. Be on your toes." }
WordHunterWoW_QuestEN[32414] = { title = "Darnassus Attacked?", description = "As you know, our night elven allies moved the Divine Bell you retrieved to Darnassus for safekeeping and study. Moments ago, they portaled some Highbourne mages over here to ask for backup. Details are hazy - some sort of stealth attack on the city?\n\nI don't know what to make of it, but Jaina Proudmoore is already on the scene and I suspect they need all the help they can get.\n\nSpeak to Seamus Goldenkicks over there for a quick portal to Darnassus. Find Jaina!", objectives = "Speak with Seamus Goldenkicks in Lion's Landing to be ported to Darnassus, then speak with Jaina once you arrive.", completion = "The Bell is gone...\n\nAt the scene of the crime, we found traces of arcane magic... I may be able to use my skills to track the thieves." }
WordHunterWoW_QuestEN[32415] = { title = "Their Tracks", description = "", objectives = "" }
WordHunterWoW_QuestEN[32416] = { title = "Jaina's Resolution", description = "For too long, I have toiled to mend fences between Alliance and Horde. Time and time again, I've given the Horde the benefit of the doubt - and time and time again, they stab me in the back.\n\nI refuse to be betrayed again! If the Horde intends to use the Kirin Tor as a weapon against the Alliance, then they have no place in Dalaran.\n\nCome with me, {name}.", objectives = "Use the portal from Darnassus to Dalaran, then speak with Vereesa Windrunner on the other side.", progress = "<Jaina looks angry.>", completion = "I will instruct you from here on out.\n\nJaina will be going down into the city to enforce our new rules." }
WordHunterWoW_QuestEN[32417] = { title = "Sewer Cleaning", description = "Jaina's doing a good job taking care of Sunreavers above ground, but there's still plenty rooting around in the sewers.\n\nGo find those lying rats and exterminate them!", objectives = "Slay 12 Sunreavers in the Dalaran Sewers.", progress = "<Vereesa looks out over her city.>", completion = "It's nice to have those rats out of here for good. Well done, hero." }
WordHunterWoW_QuestEN[32418] = { title = "Unfair Trade", description = "Most shopkeepers in the Magus Commerce Exchange have sided with the Silver Covenant, but there remain a few holdouts that must be taken care of.\n\n<Vereesa shows you a list of names.>\n\nThey will not go easily.", objectives = "Slay Inkmaster Aelon, Tolyria, Gearmage Astalon, and Sintharia Cinderweave.", completion = "While I can't say I agree completely with Jaina's methods, I do understand her motives.\n\nSometimes, you have to fight back." }
WordHunterWoW_QuestEN[32419] = { title = "Nowhere to Hide", description = "The Sunreaver's Sanctuary is still crawling with those Horde-loving Sunreavers.\n\nJaina will have sent the reasonable ones to the Violet Hold. The rest refuse to leave, raising their weapons against us.\n\nShow them the cost of their defiance. They now face the judgment of the Alliance, the Silver Covenant, and the Kirin Tor!", objectives = "Slay 16 Sunreavers in the Sunreaver's Sanctuary.", completion = "This is a bloody day, <name>, and this is bloody work.\n\nBut do not forget what the Sunreavers did to bring this on: They used neutral Kirin Tor resources to aid the Horde in their fight against the Alliance.\n\nDo not hesitate to believe that they would do the same to us, given the chance." }
WordHunterWoW_QuestEN[32420] = { title = "Cashing Out", description = "I just saw one of the Sunreavers - Brasael, I think his name was - running off in the direction of the bank to the north. No doubt he's trying to gather whatever assets he can before he leaves.\n\nHead him off and make sure he doesn't steal any resources from our coffers. He relinquished whatever funds he left in the bank when he and his Sunreaver kind betrayed us.", objectives = "Slay Magister Brasael.", completion = "I suppose it wasn't enough for him to be a coward and a backstabber... he had to be a greedy thief as well.\n\nHmph. The Horde and the Sunreavers aren't all that different. They deserve one another." }
WordHunterWoW_QuestEN[32421] = { title = "Nowhere to Run", description = "Compliant Sunreavers will be sent to the Violet Hold. Defiant ones are put to the sword.\n\nNONE are to escape.\n\nThe Sunreavers keep their dragonhawk mounts on Krasus' Landing. Take this dust, and use it to render them incapable of flying.\n\nOr kill them. I don't care.", objectives = "Render 5 Sunreaver Dragonhawks incapable of flying.", progress = "We can't have the Sunreavers escaping and plotting counterattacks against Dalaran. We need to be quick, precise, and thorough.", completion = "Now, the Sunreavers have to answer to us. Jail or death - their fate is in their own hands." }
WordHunterWoW_QuestEN[32423] = { title = "What Had To Be Done", description = "Thank you for your aid today, {name}. I will be handling the purge from here on out.\n\nJaina will soon be off to Lion's Landing, to speak with King Varian. She asked for your attendance.", objectives = "Speak with Vereesa Windrunner to travel to Lion's Landing, then speak with King Varian Wrynn.", completion = "I can't fault you for following orders. In fact, I can't really fault Jaina for acting on her own behalf, for once.\n\nBut still... we aren't playing a game here. We are dealing with war, with people's lives, with the future of the Alliance itself.\n\nAt the very least, we now have the Kirin Tor on our side. Today will be remembered by all as a victory for the Alliance." }
WordHunterWoW_QuestEN[32426] = { title = "Stirred, Not Shaken", description = "Alright, I'll tell you how to find Connelly.\n\nAgent Connelly is currently posing as the high roller, Professor Kilt. He spends most of his time in the Boom Room. Rumor has it he's after one of the fighters for some long forgotten betrayal.\n\nUnfortunately, the lounge is by invitation only. Lucky for you I just happen to have an invitation.\n\nTry not to look too obvious when you walk past the bouncers. If you get caught you didn't get this pass from me.\n\nIn fact you and I have never met!", objectives = "Find Professor Kilt in the Boom Room in Bizmo's Brawlpub.", completion = "So the SI: 7 needs a reminder in what the word retirement means?\n\nI suppose they wouldn't be comin' to me if the situation weren't dire.\n\nI'll help, but I'll need a few days to gather some intel." }
WordHunterWoW_QuestEN[32427] = { title = "The Measure of a Leader", description = "We've progressed to a new part of the Pandaren campaign. Your Warchief aims to impress the Pandaren with the full might of the Horde's military. He will lay claim to the resources of this land, with or without Pandaren aid.\n\nI understand your leader's aims, but I really want to understand the Warchief himself. What drives him? And where is the Horde ultimately going? I'd like to talk to you about this leader of yours.", objectives = "Speak with Wrathion at the Tavern in the Mists.", completion = "Like all great leaders, Garrosh has greatly extended himself. Just what is he ultimately capable of?\n\nMore importantly, what YOU are capable of? Fresh bloodshed along the coast gives us an opportunity to find out..." }
WordHunterWoW_QuestEN[32428] = { title = "Pandaren Spirit Tamer", description = "Legend tells of legendary pandaren spirits that roam the lands of Pandaria.  Find them and defeat them in a pet battle.", objectives = "Defeat all of the Pandaren Spirits in a pet battle.", completion = "I can't belive you took out those spirits!" }
WordHunterWoW_QuestEN[32429] = { title = "The Prince's Pursuit", description = "My goal is an expedient end to this costly war. Prove to me that the Horde deserves to win. Show me your prowess on the battlefield.\n\nYou are not fighting some abstract force like the sha: You are facing your enemy head-on, eye-to-eye.\n\nWill you triumph?", objectives = "Kill Alliance forces along the southern shores of Krasarang Wilds until you are Revered with the Black Prince.", completion = "Marvelous! Even in the midst of the chaos of battle you've proven that an individual can have an impact. The Alliance buckles under Horde might, although their King refuses to break.\n\nI believe it is time for a more substantial challenge..." }
WordHunterWoW_QuestEN[32430] = { title = "A Change of Command", description = "There's an Alliance dwarf I've been keeping a close eye on. High Marshal Twinbraid proved to be a nuisance in Southern Barrens when he struck back at the Horde after the loss of Bael Modan. He's now entrenched within the Alliance stronghold in Lion's Landing, helping to orchestrate the Krasarang counter-offensive.\n\nOnly a legendary group of Horde heroes could possibly defeat him.\n\nIf you wish to finish him off, bring friends. Lots of friends.", objectives = "Kill High Marshal Twinbraid at Lion's Landing in Krasarang Wilds. You will need a group.", completion = "<Wrathion grins.>\n\nYou were being tested, <class>. I knew you were capable of great things by yourself.\n\nBut you have proven to me that you have the makings of a leader, cobbling together support among a group of strangers in the midst of a battlefield.\n\nThe Horde is fortunate to have you." }
WordHunterWoW_QuestEN[32431] = { title = "Glory to the Horde", description = "This is a global war, {name}. It has spilled onto Pandaria, and it has set hot spots across Kalimdor and the Eastern Kingdoms ablaze. How will you fare on an organized battlefront? I would like to see for myself.\n\nI look forward to hearing your report from the front lines.", objectives = "Win battles at the Temple of Kotmogu and the Silvershard Mines.", completion = "<Wrathion hungrily listens to tales of your exploits on the battlefield, his eyes gleaming bright red.>\n\nOhh... oh! Incredible! In the very eye of battle, one's true heart is revealed.\n\nYou do not disappoint, <name>.\n\nNeither does this Horde of yours." }
WordHunterWoW_QuestEN[32432] = { title = "The Soul of the Horde", description = "{class}, through your eyes I've been able to witness the fighting along the coast, and the epic course of battles around the world. You've been very patient... and most informative.\n\nI've also been keeping a close eye on Garrosh Hellscream. Would you be interested to hear what I've learned?", objectives = "Speak with Wrathion.", completion = "<A strange device sits within an ornate silk-lined chest. It appears as though it can be fastened to your sha-touched weapon as an additional upgrade. The empty socket is disconcerting; you feel as though it is staring back at you. A single, hollow, judgmental eye...>" }
WordHunterWoW_QuestEN[32433] = { title = "Undermining the Under Miner", description = "Grezik Oregrind has become a nuisance that must be eliminated.\n\nThis land responds to all of our actions as I am sure you are aware, {class}. Because of this, we cannot allow the goblins to haphazardly destroy it.\n\nOur scouts have reported Sha emerging from Oregrind's Dig. The brains behind the operation is a goblin named Grezik Oregrind.\n\nDestroy him and perhaps we will stall the operation just long enough to contain the Sha.", objectives = "Destroy Grezik Oregrind at Oregrind's Dig." }
WordHunterWoW_QuestEN[32434] = { title = "Burning Pandaren Spirit", description = "You're back!  Up for another battle with me?", objectives = "Defeat Burning Pandaren Spirit in a pet battle.", progress = "Think you can take me?", completion = "I will get you next time!" }
WordHunterWoW_QuestEN[32435] = { title = "Second Place", description = "", objectives = "Today we have a contest for extreme anglers! Just be one of the FIRST THREE to bring me 40 Tastyfish fished from the schools found along the coast of Stranglethorn before anyone else, and you will be declared the winner and receive a prize!\n\nIf you are not one of the first three to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish.\n\n Oh, and don't delay, Tastyfish go bad quickly!", progress = "Today we have a contest for extreme anglers! Just be one of the FIRST THREE to bring me 40 Tastyfish fished from the schools found along the coast of Stranglethorn before anyone else, and you will be declared the winner and receive a prize!\n\nIf you are not one of the first three to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish.\n\n Oh, and don't delay, Tastyfish go bad quickly!", completion = "Hurry up and turn those in if you want to get second place!  I have been standing around here for HOURS with nothing to eat!   Hand those suckers over!" }
WordHunterWoW_QuestEN[32436] = { title = "Third Place", description = "", objectives = "Today we have a contest for extreme anglers! Just be one of the FIRST THREE to bring me 40 Tastyfish fished from the schools found along the coast of Stranglethorn before anyone else, and you will be declared the winner and receive a prize!\n\nIf you are not one of the first three to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish.\n\n Oh, and don't delay, Tastyfish go bad quickly!", progress = "Today we have a contest for extreme anglers! Just be one of the FIRST THREE to bring me 40 Tastyfish fished from the schools found along the coast of Stranglethorn before anyone else, and you will be declared the winner and receive a prize!\n\nIf you are not one of the first three to bring me 40 fish, my apprentice here will still reward you with money for each 5 Tastyfish.\n\n Oh, and don't delay, Tastyfish go bad quickly!", completion = "Hurry up and turn those in if you want to be awarded the third and final prize!  I have been standing around here for HOURS with nothing to eat!   Hand those suckers over!" }
WordHunterWoW_QuestEN[32437] = { title = "Tracking Event: Saw Sarannha 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[32438] = { title = "Tracking Event: Saw Sarannha 2", description = "", objectives = "" }
WordHunterWoW_QuestEN[32439] = { title = "Flowing Pandaren Spirit", description = "You're back!  Up for another battle with me?", objectives = "Defeat Flowing Pandaren Spirit in a pet battle.", progress = "Think you can take me?", completion = "I will get you next time!" }
WordHunterWoW_QuestEN[32440] = { title = "Whispering Pandaren Spirit", description = "You're back!  Up for another battle with me?", objectives = "Defeat Whispering Pandaren Spirit in a pet battle.", progress = "Think you can take me?", completion = "I will get you next time!" }
WordHunterWoW_QuestEN[32441] = { title = "Thundering Pandaren Spirit", description = "You're back!  Up for another battle with me?", objectives = "Defeat Thundering Pandaren Spirit in a pet battle.", progress = "Think you can take me?", completion = "I will get you next time!" }
WordHunterWoW_QuestEN[32442] = { title = "Impending Danger", description = "Our scouts have sighted a fel command ship looming on the horizon, Grandmaster. It appears to be headed on a collision course with the Wandering Isle.\n\nWe should prepare our troops for the worst case situation - an all out attack.\n\nIn the meantime, let us send our champions ahead to try and divert the Legion ship's attention.", objectives = "Complete the mission, \"Impending Danger.\"", progress = "The command ship appears to be gunning straight for us. We need everyone on alert, now!", completion = "Our champions defeated the first wave of attackers, but the command ship is nearly upon us!" }
WordHunterWoW_QuestEN[32444] = { title = "FLAG - Earned Brawler Title (Weekly)", description = "", objectives = "" }
WordHunterWoW_QuestEN[32446] = { title = "Dis-Assembly Required", description = "Those shredders are becoming a problem down there, {class}.\n\nWe've sent in the Mecha-Pounders, but it just isn't enough. They're getting damaged faster than we can repair 'em!\n\nI happened upon this strange remote while scouting. With a little bit of re-configurin' I think we can use it.\n\nTry usin' it on the Jungle Shredders. Hopefully it will destroy them and then you can bring me the scrap metal.", objectives = "Destroy the Jungle Shredders using the Re-Configured Remote and then collect 6 pieces of Scrap Metal.", progress = "So what did that remote do?", completion = "Goblin construction leaves somethin' to be desired, but it'll have to do. Good work, <name>!" }
WordHunterWoW_QuestEN[32448] = { title = "Ties with the Past", description = "While I was in the Vale, I came across an ancient pandaren recipe for Memory Wine. I believe this brew can coax some helpful information out of Shan Kien.\n\nI am needed here, so I have no choice but to ask you to recover the essential ingredient for me. We need the spirit essence of a mogu that lived in the time of the memory we wish to see.\n\nYou should be able to find just such a spirit inside the Path of Conquerors, to the northeast.", objectives = "Recover the Spirit Essence of Varatus.", progress = "You never know what you will find in a book. Especially an ancient pandaren one.\n\nI'm eager to see how this Memory Wine works.", completion = "Ah, very good. This is the last thing we needed." }
WordHunterWoW_QuestEN[32449] = { title = "The Ruins of Ogudei", description = "Our scouts at Sparkrocket Outpost have reported some new activity near an area called the Ruins of Ogudei.\n\nWe need to gather intelligence on what it is the Alliance are doing, and more importantly what it is they found. We cannot afford to have any unknowns.\n\nMeet up with Belloc Brightblade in Sparkrocket Outpost and find out what he knows.", objectives = "Report to Belloc Brightblade in Sparkrocket Outpost.", completion = "We have a lot of work to do, <class>. Who knows what has already been uncovered in Ogudei!" }
WordHunterWoW_QuestEN[32450] = { title = "The Time Is Now!", description = "Now we take the fight to them, {class}!\n\nReport to Shademaster Kiryn in Sparkrocket Outpost. She will have your orders.\n\nNow we'll see how they handle the full might of the Horde rushing at their precious keep!", objectives = "Report to Shademaster Kiryn in Sparkrocket Outpost.", completion = "Now things can get interesting! I have a few plans for Lion's Landing..." }
WordHunterWoW_QuestEN[32451] = { title = "Send A Message", description = "It's time we show these Horde mongrels the full strength of the Alliance! Today we bring the battle to their door.\n\nReport to Admiral Rogers aboard the Skyfire. She will have further instructions.\n\nGood luck out there, {class}. Do the Alliance proud!", objectives = "Report to Sky Admiral Rogers aboard the Skyfire in Krasarang Wilds.", completion = "The battle is already underway, <class>. Let's get you out there!" }
WordHunterWoW_QuestEN[32452] = { title = "And Then There Were Goblins", description = "We're fighting a war on all fronts, {class}. Even Pandaria itself needs our protection.\n\nThe Bilgewater goblins are destroying land that doesn't belong to them. They must be stopped!\n\nReport to Sky Admiral Rogers aboard the Skyfire. From her vantage point she should have a good idea of where their weak spots are.", objectives = "Report to Sky Admiral Rogers aboard the Skyfire in Krasarang Wilds.", completion = "It's about time we dealt with this nuisance. Those Bilgewater runts need to be taught a lesson!" }
WordHunterWoW_QuestEN[32455] = { title = "The Silence", description = "D..did we... do it?\n\n<Anduin mumbles the words, even though the effort clearly costs him.>\n\nL..look... in.. my... bag...\n\nUse... flare...", objectives = "Use the Alliance Flare Gun.", completion = "I hesitate to guess what would have happened if you had not been there with the young Prince, <name>.\n\nToday, you put an end to Garrosh's plans.\n\nYou have undoubtedly saved thousands of lives, and most importantly, you brought Anduin back to us.\n\nWe are doing everything we can for the boy, but we can only wait and see.\n\nI believe he has the fight in him. I must believe it..." }
WordHunterWoW_QuestEN[32457] = { title = "The Thunder King", description = "Are you aware of recent events in Kun-Lai Summit? The Zandalari have landed on the northern shores in great numbers and have set about renewing old alliances. To that end, they have resurrected The Thunder King.\n\nEven among the mogu, the name of the first emperor commands awe and fear. The Thunder King founded a vast empire of slavery and suffering... but also of power, riches, and splendor.\n\nWe will take the fight to him soon. Find me when your faction makes its move.", objectives = "Contact Wrathion on the second floor of the Tavern in the Mists in the Veiled Stair.", completion = "The Sunreavers and the Kirin-Tor are mounting an assault on the Thunder King's base of operations! My new friend here and I were just discussing the ramifications of their attack.\n\nYou and I can stand to benefit from the situation, <name>. I have a few ideas..." }
WordHunterWoW_QuestEN[32458] = { title = "With the Wind's Blessing...", description = "<An urgent plea reaches your ears.>\n\n{name}! My father's fleet is making its way to Pandaria. With favorable winds, they could arrive any moment.\n\nThe Pandaren have a blessing that will give us good luck with the weather and speed our ships to these shores. We just need to collect charms of good fortune to make it happen.\n\nAs our ships draw closer to the island, less charms will be required. But if you have enough, we can speed them here right away...", objectives = "Collect Charms of Good Fortune." }
WordHunterWoW_QuestEN[32459] = { title = "With the Wind's Blessing...", description = "<An urgent plea reaches your ears.>\n\n<name>! The Horde fleet is making its way to Pandaria. With favorable winds, they could arrive any moment.\n\nThe Pandaren have a blessing that will give us good luck with the weather and speed our brothers and sisters to these shores. We simply need to collect charms of good fortune to gain fortune's favor.\n\nAs our ships draw closer to the island, less charms will be required. But if you have enough, we can speed them here right away...", objectives = "Collect Charms of Good Fortune." }
WordHunterWoW_QuestEN[32460] = { title = "Tracking the Thieves", description = "We WILL get to the bottom of this.\n\n{name}, you're coming with me. We'll search every inch of this city if we have to, but we'll find out how they took the bell... and where.\n\nI'm picking up traces of arcane magic here... we need to follow the trail!", objectives = "Help Jaina discover who took the Divine Bell, and where they took it. You may speak with Seamus Goldenkicks in Lion's Landing to be ported to Darnassus.", completion = "I've decided.\n\nCertain members of the Kirin Tor have put their allegiance to the Horde above the order, and I will NOT tolerate it. This is nothing short of a betrayal.\n\n<Jaina's eyes flare with rage.>\n\nCome with me, <name>. We're going to clean up Dalaran." }
WordHunterWoW_QuestEN[32461] = { title = "The Order of the Cloud Serpent", description = "Ahhh, it seems you have found yourself the proud owner of a majestic cloud serpent.\n\nBefore you may fly the skies on this powerful creature, you must first earn the skill to ride it.\n\nThe Order of the Cloud Serpent can teach you the knowledge that you seek.\n\nIf you wish to follow our way, you should speak to Instructor Skythorn at The Arboretum in the Jade Forest.\n\nI wish you luck, {race}.", objectives = "Speak to Instructor Skythorn at The Arboretum in The Jade Forest.", completion = "Ah, have you come to join the Order?" }
WordHunterWoW_QuestEN[32467] = { title = "Sacrificial Prevention [PH]", description = "The Zandalari Priests in the town to the north prepare the bodies of our fallen allies for sacrifice.\n\nThe best way to prevent this from happening? Kill them. Kill them all.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 5 Zandalari Priests.The Zandalari Priests in the town to the north prepare the bodies of our fallen allies for sacrifice.\n\nThe best way to prevent this from happening? Kill them. Kill them all.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32468] = { title = "Crystal Clarity", description = "You know, there is a way we can improve your S.E.L.F.I.E. cam, if you're interested. With the right focusing lens, I could add all kinds of features to that thing.\n\nI've heard that way out on old Yojamba Isle in Stranglethorn Vale, the mother of all basilisks has been seen. Her hide is dotted with gems that'd make the perfect lens, if I could get my hands on them.\n\nShe's not going to go down easy, though. You might want to bring some friends along.", objectives = "Collect 1 Pristine Crystal Shard from the Crystal Spine Matriarch on Yojamba Isle in Stranglethorn Vale.", progress = "That crystal spine matriarch has the gems we need to upgrade your lens, any luck with that?", completion = "Count me surprised to hear from you again, you must be tougher than I thought. You've earned my respect, kid, here's your lens upgrade kit. Now get out there and take some S.E.L.F.I.E.S!" }
WordHunterWoW_QuestEN[32469] = { title = "Crystal Clarity", description = "Hi again! Oh, I forgot to tell you! I've devised a foolproof way to improve your S.E.L.F.I.E. cam! \n\nIn fact, with just the right gemstones, I can make a lens that would allow us to do all sorts of things!\n\nSome fellow explorers have told me about a large basilisk out on Yojamba Isle in Stranglethorn Vale. Her hide is dotted with tons of high-quality crystals! What a perfect coincidence!\n\nShe sounds pretty tough, though! You should bring some friends!", objectives = "Collect 1 Pristine Crystal Shard from the Crystal Spine Matriarch on Yojamba Isle in Stranglethorn Vale.", progress = "Hey, stay out of my shot! Oh, it's you! Did you take down that basilisk yet?", completion = "I knew from the moment we met that you were an adventurer, just like me! Here's your lens upgrade kit, now get out there and take some S.E.L.F.I.E.S!" }
WordHunterWoW_QuestEN[32470] = { title = "Light Camera Action", description = "Oh, hi! Isn't this a great shot? I love my S.E.L.F.I.E. camera!\n\nDo you want me to make you one, too? I only need a few parts!\n\nFor the strap, I'll need a Russet Belt from one of the armor merchants in Stormwind.\n\nI've already ordered more housings, you're welcome to take one, you just have to find where my shipment ended up!\n\nOh, and a Standard Scope, most any engineer can make you one of those.\n\nOk, are you ready for a little photography action?!", objectives = "Collect an Iron Box and a Russet Belt from locations within the capital, and a Standard Scope from an engineer.", progress = "Look at this shot? I could shoot here all day! Did you get those parts yet?", completion = "Great! I've just gotta put this box here, and jam this part in here... and done!\n\nHere's your new S.E.L.F.I.E. cam, enjoy!" }
WordHunterWoW_QuestEN[32471] = { title = "Light Camera Action", description = "You look like you've got a discerning eye for the visual arts, want to try your hand at photography?\n\nI can make you one of these S.E.L.F.I.E. cameras, I just need a few parts.\n\nFor the strap, grab me a Russet Belt from one of the armor merchants around here.\n\nI've got a shipment of extra housings waiting by the back entrance to the city, grab me one when you're over there.\n\nOh, and a Standard Scope, most any engineer can make you one of those.\n\nNow get out there, kid. Fame awaits!", objectives = "Collect an Iron Box and a Russet Belt from locations within the capital, and a Standard Scope from an engineer.", progress = "You got those parts for me, or what? I'm busy here!", completion = "You're all set, kid. You've got a face the camera will love, now get out there and get shooting!" }
WordHunterWoW_QuestEN[32472] = { title = "Frighten Pterodactyls [PH]", description = "The Pterodactyl Hatchlings being trained by Zandalari to the north are not yet the violent and savage beasts they are to become.\n\nI believe we should save these creatures before the trolls corrupt them. If you could just frighten them off, perhaps some of them will be spared an unfortunate fate.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Frighten 12 Pterodactyl Hatchlings." }
WordHunterWoW_QuestEN[32474] = { title = "A Test of Valor", description = "<Without warning Wrathion slices his thumb and presses it against your forehead. His blood burns to the touch, but rapidly disappears into your skin.>\n\nThere! My eye is upon you, <class>. I am watching.\n\nThe Pandaren, like the Alliance, value the concept of \"Valor.\" There are many ways to prove yourself valorous on this continent, from daily tasks to the defeat of heroic enemies within their lair. I will let you choose your own course.\n\nProve your bravery to me, <name>!", objectives = "Gain the \"A Test of Valor\" Achievement by earning a total of 3000 Valor Points.", completion = "<Wrathion nods slowly.>\n\nYes, <name>. I saw your deeds, and I was most impressed.\n\nYou are truly an instrument of change." }
WordHunterWoW_QuestEN[32475] = { title = "A Spark of Life", description = "The Thunder-Laced Egg burns your hand as you hold it. You recall that Yalia Sagewhisper of the Shado-Pan discussing the history of the Thundering Cloud Serpents, perhaps she will know what to do with it.", objectives = "Deliver the Thunder-Laced Egg to Yalia Sagewhisper on the Isle of Thunder." }
WordHunterWoW_QuestEN[32476] = { title = "A Test of Valor", description = "<Without warning Wrathion slices his thumb and presses it against your forehead. His blood burns to the touch, but rapidly disappears into your skin.>\n\nThere! My eye is upon you, <class>. I am watching.\n\nThe Pandaren, like the Horde, value the concept of \"Valor.\" There are many ways to prove yourself valorous on this continent, from daily tasks to the defeat of heroic enemies within their lair. I will let you choose your own course.\n\nProve your bravery to me, <name>!", objectives = "Gain the \"A Test of Valor\" Achievement by earning a total of 3000 Valor Points.", completion = "<Wrathion nods slowly.>\n\nYes, <name>. I saw your deeds, and I was most impressed.\n\nYou are truly an instrument of change." }
WordHunterWoW_QuestEN[32477] = { title = "Tracking Event: Player is Back in Time", description = "", objectives = "" }
WordHunterWoW_QuestEN[32482] = { title = "Shwayder's Test Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[32485] = { title = "Bolstering the Defenses", description = "This island is a dangerous place, {name}. We have to worry about attacks from the Zandalari, mogu, saurok, and worst of all the Sunreavers.\n\nI had perimeter wards placed on the outskirts of our camp for additional protection. In their current state they will only injure an attacker, but I'm done with warnings!\n\nWith your help we can super-charge the wards into a more deadly defense system.", objectives = "Empower 6 Kirin Tor Perimeter Wards around Violet Rise.", completion = "Excellent work, <name>. Those perimeter wards should keep out all manner of filth.\n\nWith Violet Rise protected we can focus on more pressing matters." }
WordHunterWoW_QuestEN[32489] = { title = "The Creeping Carpet of Ihgaluk", description = "Ah, roaches! I once bought a pet roach in the Undercity.\n\nRoaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far.\n\nIhgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.", objectives = "Crush 75 Ihgaluk Roaches.", progress = "This should be fairly simple. Just smush them.", completion = "Every little bit helps." }
WordHunterWoW_QuestEN[32490] = { title = "UNUSED", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32491] = { title = "Left To Rot", description = "The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease.\n\nWe can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.", objectives = "Destroy 3 Fetid Meat Piles.", completion = "Left standing, those piles of discarded food are the perfect breeding ground for disease.\n\nWere I still in the disease-spreading business, I'd consider using them myself." }
WordHunterWoW_QuestEN[32492] = { title = "Destroy Cauldrons", description = "", objectives = "" }
WordHunterWoW_QuestEN[32493] = { title = "They All Fall Down", description = "The Zandalari do not tolerate weakness in their ranks, {class}.\n\nThose that are deemed weak are often sacrificed in barbaric ceremonies. The victims' spirits are captured and entombed within the sentries you see guarding the grounds.\n\nI wish to study their essence. For this I will need your help.\n\nTake this resonance crystal and siphon the spirits from the sentry corpses.\n\n Do not allow them to escape!", objectives = "Kill 5 Spirit-Bound Sentries and then use the Resonance Crystal to capture the Zandalari Spirits trapped within.", progress = "Have you completed your task, <class>?", completion = "Excellent work, <class>! This will aid my studies greatly, as well as advance our cause here." }
WordHunterWoW_QuestEN[32494] = { title = "Power Play", description = "The Zandalari have found a way to infuse items of great power with the essence of their loa. These items are often passed from one generation to another, each recipient adding to the item's power.\n\nTwo such items exist here. To be specific, two masks, worn by two brothers.\n\nSpiritbinder Tu'chek and Arcanital Ra'kul must be stopped and their masks destroyed.\n\nKill them and return their masks to me. I will make sure the masks are disposed of.", objectives = "Retrieve the Mask of the Dark Mystic and the Mask of the Spirit-Caller from Spiritbinder Tu'chek and Arcanital Ra'kul within Conqueror's Terrace.", progress = "Do you have the masks?", completion = "Getting these masks was no easy task, <class>. I am grateful for your service." }
WordHunterWoW_QuestEN[32495] = { title = "The Bloodletter", description = "I have heard a disturbing report, {class}.\n\nJust beyond our position, in the Court of Bone, the mogu bring captives to a general named Kaida the Bloodletter.\n\nI will spare you the details, but he thrives on torturing his victims.\n\nThis monster must be stopped. If you fall to his blade, I wish you a swift death.", objectives = "Kill Kaida the Bloodletter.", progress = "The mogu are capable of unimaginable cruelty.", completion = "I am glad to hear that this piece of filth is slain. You have done us all a great favor, <name>." }
WordHunterWoW_QuestEN[32496] = { title = "Desecrate this Fire!", description = "", objectives = "Desecrate the Horde's Vale of Eternal Blossoms bonfire!" }
WordHunterWoW_QuestEN[32497] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Dread Wastes.", completion = "Honor the Dread Wastes flame." }
WordHunterWoW_QuestEN[32498] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Jade Forest.", completion = "Honor the Jade Forest flame." }
WordHunterWoW_QuestEN[32499] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Krasarang Wilds.", completion = "Honor the Krasarang Wilds flame." }
WordHunterWoW_QuestEN[32500] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Kun-Lai Summit.", completion = "Honor the Kun-Lai Summit flame." }
WordHunterWoW_QuestEN[32501] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Townlong Steppes.", completion = "Honor the Townlong Steppes flame." }
WordHunterWoW_QuestEN[32502] = { title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", objectives = "Honor the Midsummer Bonfire in Valley of the Four Winds.", completion = "Honor the Valley of the Four Winds flame." }
WordHunterWoW_QuestEN[32503] = { title = "Desecrate this Fire!", description = "", objectives = "Desecrate the Alliance's Vale of Eternal Blossoms bonfire!" }
WordHunterWoW_QuestEN[32504] = { title = "Mission: The Secrets of Stormwind", description = "Send undercover forces into the heart of enemy territory in an effort to learn of their plans.", objectives = "Send undercover forces into the heart of enemy territory in an effort to learn of their plans." }
WordHunterWoW_QuestEN[32505] = { title = "The Crumbled Chamberlain", description = "You there! Assist me.\n\nIn life I was the Royal Chamberlain for his majesty, the Thunder King. For my dedication, I was condemned to this stone form, forever forced to watch over a portion of his wealth.\n\nSomeone has desecrated my glorious body and sent pieces of it across the island. The thought of spending an eternity as nothing more than a head depresses me.\n\nSearch the island, recover these pieces and I shall grant you one of his majesty's treasures.", objectives = "Recover the Shoulder, Head, Staff, Hair and Torso of the Chamberlain.", progress = "I require ALL of my pieces. If so much as a pebble is missing, I shall consider forfeiting our agreement.", completion = "Ah! To feel whole again! You have my gratitude, servant. Take this stone and use it wisely. Should you encounter his majesty the Thunder King in your travels, do not tell him where you received it, or you will be standing in a statue next to me for the remainder of eternity." }
WordHunterWoW_QuestEN[32506] = { title = "A Wing to Fly On", description = "I've just received a report that another young pterrorwing has been spotted in the Diremoor.\n\nWe need to recover as many of these as we can find. They may be the key to flying on this island.", objectives = "Recover a Wild Ptrerrorwing Hatchling.", progress = "A great gloom looms over this island...", completion = "Wonderful! I'll pass him off to our caretaker. Thank you." }
WordHunterWoW_QuestEN[32507] = { title = "Skin of the Saurok", description = "Ihgaluk Crag is a dangerous place. Luckily, you have the magic of the Sunreavers behind you.\n\nI can transform you into a saurok.\n\nI will perform the first half of the illusion on you now. Afterwards, you should go directly to Ihgaluk Crag and slay one of the Skumblade saurok. Once you have done this, I will contact you and complete the second half of the illusion.", objectives = "Go to Ihgaluk Crag and slay a Skumblade saurok." }
WordHunterWoW_QuestEN[32508] = { title = "Welcome to the Island", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32509] = { title = "Honor the Flame", description = "", objectives = "Honor the Vale of Eternal Blossoms flame." }
WordHunterWoW_QuestEN[32510] = { title = "Honor the Flame", description = "", objectives = "Honor the Vale of Eternal Blossoms flame." }
WordHunterWoW_QuestEN[32516] = { title = "The Bloodletter", description = "I have heard a disturbing report, <class>.\n\nTo the south, in the Court of Bones, the mogu bring captives to a general named Kaida the Bloodletter.\n\nI will spare you the details, but he thrives on torturing his victims.\n\nThis monster must be stopped. If you fall to his blade, I wish you a swift death.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Kaida the Bloodletter." }
WordHunterWoW_QuestEN[32517] = { title = "The Conquest of Stone", description = "In the Court of Bones, the Thunder King's sorcerers perform dark rituals.\n\nTo bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living.\n\nAfter these stone conquerors are brought to life, they will be formidable opponents on the battlefield.\n\nWe must stop their ritual before these statues can be revived.", objectives = "Stop the Ancient Stone Conqueror ritual in the main temple at the Court of Bones.", progress = "It is a mystery how the mogu can imbue life into inanimate stone, but with enough study, we, too, may one day be able to understand that power.", completion = "A good defense is just as effective as a strong offense. One less enemy to worry about.\n\nWell done." }
WordHunterWoW_QuestEN[32518] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[32519] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[32520] = { title = "Competing Magic", description = "My scouts have spotted a dangerous Zandalari just this side of Za'Tual. I need someone capable to see him dispatched. Are you up to the task?", objectives = "Kill Arcweaver Jor'guva.", completion = "Your skills are impressive indeed. Thank you for doing this for me, <name>." }
WordHunterWoW_QuestEN[32521] = { title = "Encroaching Force", description = "My scouts have spotted a Zandalari war party on the northern beach. I need someone capable to see him dispatched. Are you up to the task?", objectives = "Kill Nurkala, the Zandalari War Leader.", completion = "You have our gratitude, <name>." }
WordHunterWoW_QuestEN[32522] = { title = "Imposing Threat", description = "My scouts have spotted a mogu leader under the central tower. He needs to be killed before he can mount an offensive on our position.\n\nCan you take care of this for me?", objectives = "Kill Horgak the Enslaver.", completion = "One less threat at our doorstep. Thank you, <name>." }
WordHunterWoW_QuestEN[32523] = { title = "The Beast Pens", description = "We need to counter the beasts the Zandalari are using to strike at our camp. I have dispatched Scout Captain Elsia to the Beast Pens along with some war mages to provide cover.\n\nGo and find her east of here near the breaches in the wall and help her trim down the cavalry and siege beasts being levied against us.\n\nThey are masked, so look for the shimmers of their magical cloaking spells.", objectives = "Find Scout Captain Elsia at the Beast Pens.", completion = "I'm glad you were the one Lor'themar sent. These beasts are more than we can handle on our own. Time to spook the livestock." }
WordHunterWoW_QuestEN[32524] = { title = "The Beating of Troll Drums", description = "Do you hear that, {class}? The beating of war drums in the distance. The Zandalari are preparing for us.\n\nLet's not give them the luxury of time to organize their defenses. We need to push the attack now!\n\nReport to Scout Captain Elsia within Conqueror's Terrace. She will have further orders for you.", objectives = "Locate Scout Captain Elsia within Conqueror's Terrace.", completion = "These Zandalari are even more dangerous than we anticipated.\n\nDo not make the mistake of underestimating them, for that may be the last mistake you make." }
WordHunterWoW_QuestEN[32525] = { title = "Ashes of the Enemy", description = "The mogu at the Court of Bones are bolstering their army by resurrecting the spirits of their dead.\n\nWe cannot allow them to revive their fallen warriors.\n\nTake this torch and burn any mummified corpses that you can find.\n\nWe will destroy our enemies before they have a chance to rise.", objectives = "Burn 8 Mummified Remains.", completion = "Their dead shall rise no more, thanks to you, <name>. Excellent work." }
WordHunterWoW_QuestEN[32526] = { title = "Soul Surrender", description = "We assault the mogu at the Court of Bones, but I fear we merely send them fodder for their abominable rituals.\n\nThe mogu do not merely kill their prisoners - they steal their souls and imbue them in machinations of stone, or reforge the fallen into ghostly tools of war.\n\nAlliance or Horde, it matters not. We cannot allow the mogu to bolster their numbers.\n\nGo into the crypts. Free any prisoners that are still living.", objectives = "Save 6 Silver Covenant Scouts or Sunreaver Scouts.", completion = "Thank you, <name>. You have lightened my heart of a heavy burden through your heroic actions.\n\nI will remember your efforts on this day." }
WordHunterWoW_QuestEN[32527] = { title = "Grave Circumstances", description = "The Court of Bones crawls with mogu forces. Endlessly do they perform their rituals of lightning and thunder.\n\nIf our mission to take this island is to succeed, then we cannot allow them to hold such a strategic position.\n\nThey must be eliminated.", objectives = "Kill 10 Shan'ze Gravekeepers, Shan'ze Soulrippers, or Shan'ze Thundercallers.", completion = "Excellent. You have dealt the mogu a blow that they shall not easily forget." }
WordHunterWoW_QuestEN[32528] = { title = "Into the Crypts", description = "Every day, we uncover additional relics from the Court of Bones.\n\nRecently, we discovered this scroll amongst the gravestones in one of the deepest crypts.\n\nI believe that this incantation can be used to call beyond the grave. And if my Mogu is up to date, I'd say you should use it in the last room in the Hall of the Exalted.\n\nWould you be willing to test out my theory?", objectives = "Use the Incantation of Gura in the Hall of the Exalted, then defeat Gura the Reclaimed.", progress = "How did it go?", completion = "Ah yes, you've just confirmed my theory! Thank you, <class>." }
WordHunterWoW_QuestEN[32529] = { title = "The Call of Thunder", description = "Within the graveyard, in the deepest ruins of their western crypt, the Thunder King's most powerful sorcerers are charging a lightning rod with crackling electricity.\n\nWe suspect that this weapon is meant to rain destruction on our stronghold at Violet Rise.\n\nThere is no time to delay. You must stop their ritual at once.", objectives = "Stop the Shan'ze Thundercallers' ritual.", progress = "Do not allow them to unleash the force of their weapon.", completion = "You continue to exceed my expectations, <class>. Well done." }
WordHunterWoW_QuestEN[32530] = { title = "The Bloodletter", description = "I have heard a disturbing report, {class}.\n\nJust beyond our position, in the Court of Bones, the mogu bring captives to a general named Kaida the Bloodletter.\n\nHe thrives on torturing his victims.\n\nThis monster must be stopped. If you fall to his blade, I wish you a swift death.", objectives = "Kill Kaida the Bloodletter.", progress = "The mogu are capable of unimaginable cruelty.", completion = "I am glad to hear that this piece of filth is slain. You have done us all a great favor, <name>." }
WordHunterWoW_QuestEN[32531] = { title = "The Conquest of Stone", description = "In the Court of Bones, the Thunder King's sorcerers perform dark rituals.\n\nTo bolster their numbers, the Shan'ze soulrippers are imbuing ancient stone statues with stolen spirits from the living.\n\nAfter these stone conquerors are brought to life, they will be formidable opponents on the battlefield.\n\nWe must stop their ritual before these statues can be revived.", objectives = "Disrupt the Ancient Stone Conqueror ritual in the main temple at the Court of Bones.", progress = "It is a mystery how the mogu can imbue life into inanimate stone, but with enough study, we, too, may one day be able to understand that power.", completion = "A good defense is just as effective as a strong offense. One less enemy to worry about.\n\nWell done." }
WordHunterWoW_QuestEN[32532] = { title = "Rise No More!", description = "Have you seen the ghosts wandering the graveyard?\n\nThey are risen ancestors, the spirits of slain mogu who have been called back to this world.\n\nWhen angered, they attack swiftly and silently, and their numbers increase by the day.\n\nThey do not belong here. Destroy them, and send them back beyond the grave.", objectives = "Kill 15 Risen Ancestors.", completion = "Wonderful work, <class>. This will help our offensive a great deal." }
WordHunterWoW_QuestEN[32533] = { title = "Stone Cold", description = "Our assault on the Court of Bones continues. Our progress remains slow, but measurable.\n\nUnfortunately, we've received several reports of stone quilen statues coming to life without warning. These quilen are too dangerous to ignore.\n\nVenture into the Court of Bones and destroy any quilen statues that you can find.", objectives = "Destroy 8 Grave Guardians.", completion = "I am glad to hear that you left the quilen in a thousand tiny pieces. They are little more than a nuisance to my work here on the island." }
WordHunterWoW_QuestEN[32534] = { title = "The Skumblade Threat", description = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations.\n\nThin their numbers, <name>. Once the Horde takes full control of this island, we can look for more permanent solutions.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 10 Skumblade saurok." }
WordHunterWoW_QuestEN[32535] = { title = "The Skumblade Threat", description = "Ihgaluk Crag has no end of saurok. Those beasts attack my men and spread their disease into nearby water and wildlife, interfering with our operations.\n\nThin their numbers, {name}. Once the Alliance takes full control of this island, we can look for more permanent solutions.", objectives = "Slay 10 Skumblade saurok.", completion = "One day, this island will belong to the Alliance. I can only hope that it will be free of saurok before then.\n\n<Modera sneers.>\n\nAt least they attack the Horde, too." }
WordHunterWoW_QuestEN[32536] = { title = "Manipulating the Saurok", description = "I have three magisters entrenched in Ihgaluk Crag, monitoring the saurok and - where they can - turning them against the mogu. I need you to find them and see if they need any supplies or assistance.\n\nThey will be concealed from view. Look for shimmering columns of light within the saurok village.", objectives = "Check in with Magister Yalis, Magister Lyanis, and Magistrix Sanal.", progress = "Good luck, <name>.", completion = "<The archmage listens carefully to your report.>\n\nI understand. Thank you for your aid, <class>." }
WordHunterWoW_QuestEN[32537] = { title = "De-Constructed", description = "Saurok consistently test our borders, and our constructs usually fend them off. Some constructs, however, have been defeated and dragged back to Ihgaluk Crag.\n\nI want those constructs back. No slithering lizard will steal Silver Covenant property under my watch.", objectives = "Recover the four stolen Silver Covenant Constructs.", progress = "Hmph... saurok.\n\n<Modera spits.>", completion = "That's more like it.\n\nThank you, <class>." }
WordHunterWoW_QuestEN[32538] = { title = "Heinous Sacrifice", description = "Some of the strongest of the spiritbinders perform heinous rites to their wretched gods.\n\nWe've devised a method to destroy their altars, so the difficult task will be getting to each altar alive.\n\nVenture into the depths of Za'Tual and destroy their altars.", objectives = "Destroy the Zandalari's sacrificial altars.", progress = "I realize what I ask you to do is dangerous, but it is necessary.", completion = "<class>, the destruction of those altars will force the trolls to halt their most heinous of sacrifices. You have the thanks of everyone here." }
WordHunterWoW_QuestEN[32539] = { title = "Dark Offerings", description = "The Zandalari's spiritbinders perform dark sacrifices to appease their gods, killing our people in the process.\n\nDestroy any Zandalari offerings you can find in Za'Tual to help slow the pace of their dark sacrifices.", objectives = "Destroy 6 Zandalari Offerings.", completion = "Without the offerings, they will need to collect more before their sacrifices can proceed. Thank you, <class>." }
WordHunterWoW_QuestEN[32540] = { title = "Harbingers of the Loa", description = "If you spend some time in Za'Tual, you will likely see one of their large tents emanating a pure form of evil.\n\nPlease, venture into the troll camp and put a stop to these unspeakable rituals.", objectives = "Slay 2 Harbingers of the Loa.", completion = "Most who witness such rituals never return, and those that do tend to be shaken. You, <name>, seem little moved by your incredible deeds. I am impressed." }
WordHunterWoW_QuestEN[32541] = { title = "Preventing a Future Threat", description = "It pains me to think of the torture the poor skyscreamers  must endure as the trolls train them to become implements of war.\n\nThe hatchlings are quite fearful, and will fly away if you even get close them. Please, frighten some away before the Zandalari corrupt them.", objectives = "Frighten 12 Hatchling Skyscreamers by running near them.", completion = "Welcome back, <race>. The hatchlings you frightened will live a better life without their captors." }
WordHunterWoW_QuestEN[32542] = { title = "Surgical Strike", description = "Zandalari spiritbinders perform sacrifices to their gods, the beastcallers bend innocent skyscreamers to their will, and the jaguar warriors venture closer to us by the day.\n\nDispose of these threats in Za'Tual, {race}, and watch the might of the trolls weaken.", objectives = "Slay 3 Zandalari Spiritbinders, 3 Zandalari Beastcallers, and 3 Zandalari Jaguar Warriors.", completion = "With a few of their more threatening kin slain, perhaps the Zandalari will show reluctance next time they decide to trifle with us." }
WordHunterWoW_QuestEN[32543] = { title = "Dangers of Za'Tual", description = "The Zandalari are a formidable foe - more so than many foes we've encountered in the past. But you are a formidable foe as well, {name}.\n\nEnter Za'Tual to and show them the risks associated with opposing the likes of you.", objectives = "Slay 12 Trolls in Za'Tual.", completion = "<name>, your help against the Zandalari is appreciated. I realize it seems we cannot stem the tide, but your efforts make a difference." }
WordHunterWoW_QuestEN[32544] = { title = "Pterrible Ptorment", description = "One of the trolls' skyscreamers in Za'Tual is undergoing a ritual of torture, its will being bent forever to serve its masters.\n\nKill those that inflict such torment on the creature and we can only hope that it will return to the skies.", objectives = "Free the Tormented Skyscreamer.", progress = "Have you freed the creature?", completion = "I hope that creature has the intelligence necessary to know who saved it. It seems to me that it would be a dangerous foe if provoked." }
WordHunterWoW_QuestEN[32545] = { title = "The Residents of Ihgaluk", description = "The Skumblade threaten our people, but responding with all-out slaughter would be an overreaction.\n\nA more reasonable response to their threat would be to slay some of their tribal leaders. There will be less bloodshed, and they will still respect our perimeter.", objectives = "Slay a Skumblade Brute, a Skumblade Saur-Priest, and a Skumblade Seadragon.", progress = "The saurok value strength above all else. They only respond to strength.\n\nPeace with the saurok will require some amount of bloodshed. The question is, how much?", completion = "I know the true price of bloodshed. I know the cost of war.\n\nIt would be simpler to blindly massacre our attackers until they yield. But is it right?" }
WordHunterWoW_QuestEN[32546] = { title = "Just Some Light Clean-Up Work", description = "This is not a glamorous job. Let me put it to you bluntly.\n\nThe Skumblade saurok pile all of their filth into a pool in the middle of their village. This filth is so concentrated and so rancid that it has congealed into moving, animate matter.\n\nThe saurok can keep their filth-pool, but once it starts spreading outside of the village, I'd say it's time to intervene.", objectives = "Disperse 75 pieces of filth by killing Quivering Filth in Ihgaluk Crag.", progress = "Sorry in advance about the smell.", completion = "Well done, <name>. Looking at you, I'm suddenly quite proud of Dalaran's state-of-the-art plumbing system." }
WordHunterWoW_QuestEN[32547] = { title = "The Creeping Carpet of Ihgaluk", description = "Ah, roaches! I once bought a pet roach in Booty Bay.\n\nRoaches will soak up disease like a sponge, and then spread it as far as they can run. Which is pretty far.\n\nIhgaluk Crag is crawling with the things, and they carry Skumblade filth all over of this island. Crush as many of them as you can while you're there.", objectives = "Crush 75 Ihgaluk Roaches.", completion = "Every little bit helps." }
WordHunterWoW_QuestEN[32548] = { title = "Left To Rot", description = "The Skumblade saurok do not eat all of the meat they hunt. They reserve large portions of it to rot in piles near their homes, attracting pests and spreading disease.\n\nWe can't have the saurok spreading their disease beyond the borders of Ihgaluk Crag. Dispose of any excess meat that you find.", objectives = "Destroy 3 Fetid Meat Piles.", progress = "I know of many ways to spread disease, but this one is novel.", completion = "Left standing, those piles of discarded food are the perfect breeding ground for disease.\n\nWere I still in the disease-spreading business, I'd consider using them myself." }
WordHunterWoW_QuestEN[32549] = { title = "Skin of the Saurok", description = "Ihgaluk Crag is a dangerous place. Luckily, you have the magic of the Kirin Tor behind you.\n\nI can transform you into a saurok.\n\nI will perform the first half of the illusion on you now. Afterwards, you should go directly to Ihgaluk Crag and slay one of the Skumblade saurok. Once you have done this, I will contact you and complete the second half of the illusion.", objectives = "Go to Ihgaluk Crag and slay a Skumblade saurok." }
WordHunterWoW_QuestEN[32550] = { title = "Saur Loser", description = "Inside the Beast Pens you will encounter some of the most skilled beast tamers in the Zandalari military. They are trained to kill with axe, beast, and claw. This is where they build their cavalry.\n\nWe need you to kill any Zandalari you find in the Beast Pens before they can get their mounted monstrosities out into the open battlefield.", objectives = "Defeat 10 Zandalari trolls in the Beast Pens.", completion = "These trolls have been using dark magics to achieve their goals. No patience, no honor. You have done the world a good service in reducing their numbers today." }
WordHunterWoW_QuestEN[32551] = { title = "Compy Stomp", description = "The raptors and saurid of the Zandalari represent a substantial threat to our forces here. They are superb hunting beasts that can track prey over great distances and are often lethal to encounter when caught unawares.\n\nI need you to head into the Beast Pens and cull their numbers. We need to make sure to slay them before they are fully trained.", objectives = "Kill 5 Raptors and 10 Trained Saurid in the Beast Pens.", completion = "We lost three good soldiers when we first arrived on this island. Killed in their sleep by compies that had snuck into their tent. Some nights I still hear the screams." }
WordHunterWoW_QuestEN[32552] = { title = "Loa-saur", description = "The Zandalari have found a way to bind loa to their beasts giving them impressive and lethal powers.\n\nWe need to put a stop to this.\n\nSearch the Beast Pens for a loa speaker and slay him. You should be able to find them by keeping a look out for their glowing beasts.\n\nWe must not allow these atrocities to continue.", objectives = "Defeat a Loa Speaker.", progress = "I always believed the loa to be a simple troll superstition. These Zandalari are full of surprises.", completion = "Well done, champion. These beasts are strong enough. We don't need them infused with an angry spirit now do we?" }
WordHunterWoW_QuestEN[32553] = { title = "Direhorn vs Devilsaur", description = "We have an opportunity to disrupt the Zandalari war machine as well as have a little fun in the process.\n\nWithin these beast pens, a devilsaur and a direhorn are being outfitted with armor, their minds being enslaved to the Zandalari charms.\n\nGo into the camp and disrupt one of these binding rituals. It doesn't matter which one. Just kill those who are trying to bind the creature. This should let the fully armored beast run mad through the Zandalari camp. Then sit back and watch the hilarity ensue.", objectives = "Disrupt a binding ritual by killing all ritual NPCs around either a Defiant Direhorn or a Defiant Devilsaur.", progress = "So... did you decide the devilsaur or the direhorn?", completion = "Few things in this world and beyond are more entertaining than watching a rampaging ancient beast tearing through an enemy's settlement.\n\nIf times were not so dire I would consider selling tickets to such an event." }
WordHunterWoW_QuestEN[32554] = { title = "Dino Might", description = "The Zandalari use a series of fetishes and charms to maintain their control over their menagerie of beasts.\n\nTwo can play at that game.\n\nI want you to find some of these fetishes and try them out on the various beasts in the Beast Pens.\n\nTake careful note of how each beast responds to each fetish. Then report your results to me.\n\nMaybe this will give us the edge we need against the Zandalari.", objectives = "Find and use Saur Fetishes on 5 raptors, compies, skyscreamers or direhorns in the Beast Pens.", completion = "Very interesting results. I am sure there is a mage somewhere that cares about the specifics. I, on the other hand, am just glad to hear the sound of trolls being assaulted by their own beasts." }
WordHunterWoW_QuestEN[32555] = { title = "Centuries in Sentries", description = "Sacrifices are common place in Zandalari society. There is however one oddity among these barbaric rituals; volunteers. They treat it as a great honor!\n\nThe weak still seek to contribute, even if that means giving their lives to be bound to the sentries you see walking around. Locked away in service to their people.\n\nTake this resonating crystal. Once destroyed, drain the sentry of its Zandalari inhabitant. Return the crystal to me when your task is complete.", objectives = "Kill 5 Spirit-Bound Sentries and then use the Resonance Crystal to capture the Zandalari spirits trapped within.", progress = "How many spirits have you captured?", completion = "This is very interesting, <class>. The crystal hums with the rage of its captive inhabitants. Even after the passage of time their devotion has not decreased.\n\nI will need to study this further." }
WordHunterWoW_QuestEN[32556] = { title = "The More You Know", description = "This whole area is littered with Zandalari artifacts. I would be lying if I said studying them didn't interest me. I am fascinated by the significance of these objects to their rituals.\n\nThe more we understand our enemies, the better prepared we are to defeat them.\n\nIf I am to study them, I will need to see them up close. Bring me as many artifacts as you can find. ", objectives = "Retrieve 6 Ritual Artifacts from around Conqueror's Terrace.", progress = "What have you brought me, <class>?", completion = "These are excellent finds! Studying them will take time, but there is much to be gained in understanding the Zandalari." }
WordHunterWoW_QuestEN[32557] = { title = "Out of Enemy Hands", description = "Magic is a frightening opponent when wielded by an experienced caster. A blade however, is terrifying in even the most inexperienced hands.\n\nThe Zandalari have some impressive weapons, made even more deadly by the magic they are enhanced with. We should relieve them of this advantage.\n\nSteal as many of the weapons as you can find.", objectives = "Steal 7 Loa-Infused Blades from Conqueror's Terrace.", progress = "What did you find out there? Anything that can be of use?", completion = "Excellent work, <class>! These weapons are impressive. Now we have a few less things to worry about in the field of battle." }
WordHunterWoW_QuestEN[32558] = { title = "All In the Family", description = "Conqueror's Terrace is watched over by two brothers; Spiritbinder Tu'chek and Arcanital Rak'ul. They are powerful magic users and should not be underestimated.\n\nTheir power seems to stem from the ornate masks they wear; relics passed down from one generation to the next. Each owner imbuing it with their own magic before passing it on.\n\nWe must deal with the brothers and destroy their masks before they fall into the wrong hands.", objectives = "Retrieve the Mask of the Dark Mystic and the Mask of the Spirit-Caller from Spiritbinder Tu'chek and Arcanital Ra'kul within Conqueror's Terrace.", progress = "Where are the masks?", completion = "It's a shame really that these masks must be destroyed. I would have liked to study this ancient magic, but it is better that they be destroyed than become the tools of the Horde.\n\nGood work, <class>." }
WordHunterWoW_QuestEN[32559] = { title = "Even Giants Fall", description = "The Zandalari worship the loa; animal spirits they often call to their aid. They may be trying to bind these spirits into a huge golem. The outcome would be disastrous.\n\nI've sent ahead a scout to gather more information, but I think this task may require your expertise.\n\nStop that ritual at all costs!", objectives = "Destroy Guardian Tak'u within Conqueror's Terrace.", completion = "It's fortunate that you were able to intervene, <class>. Who knows what damage that golem would have caused had he not been stopped." }
WordHunterWoW_QuestEN[32560] = { title = "Keep It Secret", description = "The Zandalari here are a threat to our campaign, {class}.\n\nTheir use of magic is an abomination. They mix the power of arcane with the darkness of shadow with little care to consequence.\n\nWe cannot afford for them to find their full strength here or for the Horde to learn of their twisted magic.\n\nTheir numbers must be thinned. I will leave this task to you.", objectives = "Kill any 8 Zandalari trolls within Conqueror's Terrace.", completion = "Well done, <class>. The more Zandalari we destroy, the less chance their magic will fall into Horde hands." }
WordHunterWoW_QuestEN[32561] = { title = "Competing Magic", description = "One of my scryers has identified a Zandalari leader near the central tower. He needs to be removed.\n\nWould you be willing to do this for me, {class}?", objectives = "Kill Arcweaver Jor'guva.", completion = "You're dependable, <name>. I like that." }
WordHunterWoW_QuestEN[32562] = { title = "Imposing Threat", description = "One of my scouts has returned with word of a mogu leader under the central tower. He needs to be removed.\n\nWould you be willing to do this for me, {class}?", objectives = "Kill Horgak the Enslaver.", completion = "I appreciate what you've done for us this day, <name>." }
WordHunterWoW_QuestEN[32563] = { title = "Encroaching Force", description = "We've spotted a Zandalari war party down on the beach just outside these walls. We need to eliminate them before returning to camp.\n\nAre you up for the task?", objectives = "Kill Nurkala, the Zandalari War Leader.", completion = "Thank you, <name>. That's a worry off my mind." }
WordHunterWoW_QuestEN[32564] = { title = "Zandalari on the Rise", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nCan you handle this one?", objectives = "Kill Arcweaver Jor'guva.", completion = "Yet again you prove yourself. We would be fortunate if all amongst us could aspire to your talents." }
WordHunterWoW_QuestEN[32565] = { title = "Encroaching Force", description = "We've spotted a Zandalari war party up the beach. We need to eliminate him before returning to camp.\n\nWould you be willing to handle this one?", objectives = "Kill Nurkala, the Zandalari War Leader.", completion = "Your skills are impressive. You have our gratitude." }
WordHunterWoW_QuestEN[32566] = { title = "DEBUG: Eligible for All Quests", description = "", objectives = "" }
WordHunterWoW_QuestEN[32567] = { title = "The Beast Pens", description = "I do not want to see another Zandalari beast rider breach our defenses!\n\nI have dispatched Scout Captain Daelin and some war mages to the Beast Pens northwest of here. Their mission is to infiltrate and harass the Zandalari siege and cavalry units. I want you to join them and lend your expertise.\n\nKeep an eye out for the tell tale shimmer of their magical cloaking spell.", objectives = "Find Scout Captain Daelin at the Beast Pens.", completion = "Today, we hunt the hunters!" }
WordHunterWoW_QuestEN[32568] = { title = "No Time To Rest", description = "We have accomplished much since arriving here, but now is not the time to rest. Your efforts have helped us breach the upper level of the Thunder King's stronghold.\n\nNow, I call on you to continue our campaign. Report to Scout Captain Daelin within Conqueror's Terrace. He will have further orders for you.", objectives = "Locate Scout Captain Daelin within Conqueror's Terrace.", completion = "The Zandalari here are not to be under-estimated, <class>. Powerful magic overwhelms this space.\n\nWe must be diligent in our efforts." }
WordHunterWoW_QuestEN[32569] = { title = "Trailing Light in the Dark", description = "There is some dark magic in the Diremoor that extinguishes even our magical illuminations, and so our scouts struggle to find their way.\n\nAs you pass through the swamp, relight any torches you find that our men might find their way. Perhaps they will help you find your way back as well.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Relight 8 torches in the Diremoor." }
WordHunterWoW_QuestEN[32570] = { title = "Gather Scout Reports", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[32571] = { title = "A Wing to Fly On", description = "I've just received a report that another young pterrorwing has been spotted in the Diremoor.\n\nWe need to recover as many of these as we can find. They may be the key to flying on this island.", objectives = "Recover a Wild Ptrerrorwing Hatchling.", progress = "A great gloom looms over this island...", completion = "Wonderful! I'll pass him off to our caretaker. Thank you." }
WordHunterWoW_QuestEN[32572] = { title = "The Sleepless Legion", description = "The Shan'ze are animating an army from the statues in the center of the isle, an army that batters our defenses day and night. Destroy any of the walking statues you see. Our defenders will greatly appreciate it.", objectives = "Kill 6 Animated Warriors.", progress = "You are not done just yet, <class>.", completion = "Your efforts are appreciated, <class>." }
WordHunterWoW_QuestEN[32573] = { title = "Enemies Beneath the Tower", description = "There are mogu in the Diremoor animating the army of statues near the tower. Vereesa wants them dead. I think you're the one to do it.", objectives = "Kill 7 Shan'ze mogu in the Diremoor.", completion = "Well done, <class>. Thank you for the help." }
WordHunterWoW_QuestEN[32574] = { title = "The Shuddering Moor", description = "There is an immense beast in the swamp. It has not yet marched upon us, but I place no stock that we will continue to be so fortunate.\n\nStrike it down before it grows hungry enough to brave our defenses.", objectives = "Kill the Mighty Devilsaur.", completion = "You are not one to be trifled with. I am sure to have further use of your services.\n\nCome back to me in a day's time, <class>." }
WordHunterWoW_QuestEN[32575] = { title = "The Zandalari Colossus", description = "The trolls have dispatched one of their immense constructs on the southern road, blocking our passage around the island. See to it that the road is cleared, {class}.", objectives = "Destroy the Zandalari Colossus.", completion = "When I give you a task, it gets handled.\n\nWell done, <class>." }
WordHunterWoW_QuestEN[32576] = { title = "Competing Magic", description = "One of the scryers has identified a Zandalari leader near the central tower. He needs to be removed.\n\nWould you be willing to handle this?", objectives = "Kill Arcweaver Jor'guva.", completion = "You're dependable, <name>. I like that." }
WordHunterWoW_QuestEN[32577] = { title = "Imposing Threat", description = "One of Vereesa's scouts has returned with word of a mogu leader under the central tower. He needs to be removed.\n\nWould you be willing to handle this?", objectives = "Kill Horgak the Enslaver.", completion = "I appreciate what you've done for us this day, <name>." }
WordHunterWoW_QuestEN[32578] = { title = "Among the Bones", description = "The scouts have spotted a dangerous Zandalari among the bones west of Ihgaluk Crag. We need someone capable to see him dispatched. Are you up to the task?", objectives = "Kill Zur'chaka the Bonecrafter.", progress = "Is it done?", completion = "It's good to have a man I can trust close at hand." }
WordHunterWoW_QuestEN[32579] = { title = "Competing Magic", description = "The scouts have spotted a dangerous Zandalari just this side of Za'Tual. We need someone capable to see him dispatched. Are you up to the task?", objectives = "Kill Arcweaver Jor'guva.", completion = "Your skills are impressive indeed. Thank you for doing this for me, <name>." }
WordHunterWoW_QuestEN[32580] = { title = "Encroaching Force", description = "We've received word of a Zandalari war party up the beach, north of our foothold. We need them hunted down and killed.\n\nAre you willing to do this thing for us, {class}?", objectives = "Kill Nurkala, the Zandalari War Leader.", progress = "Is it done?", completion = "You have our gratitude, <name>." }
WordHunterWoW_QuestEN[32581] = { title = "Imposing Threat", description = "The scryers have spotted a mogu leader at the central tower. He needs to be killed before he can mount an offensive on our position.\n\nCan you take care of this for us?", objectives = "Kill Horgak the Enslaver.", progress = "Is it done?", completion = "One less threat at our doorstep. Thank you, <name>." }
WordHunterWoW_QuestEN[32582] = { title = "Raining Bones", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nWould you be willing to do the deed?", objectives = "Kill Zur'chaka the Bonecrafter.", completion = "You're a good <class> to have around, that's for certain. Thank you." }
WordHunterWoW_QuestEN[32583] = { title = "Zandalari on the Rise", description = "We've spotted a Zandalari leader up the central stairs. We need to eliminate him before returning to camp.\n\nCan you handle this one?", objectives = "Kill Arcweaver Jor'guva.", completion = "Yet again you prove yourself. We would be fortunate if all amongst us could aspire to your talents." }
WordHunterWoW_QuestEN[32584] = { title = "Encroaching Force", description = "We've spotted a Zandalari war party down on the beach just outside these walls. We need to eliminate them before returning to camp.\n\nAre you up for the task?", objectives = "Kill Nurkala, the Zandalari War Leader.", completion = "Thank you, <name>. That's a worry off my mind." }
WordHunterWoW_QuestEN[32585] = { title = "Encroaching Force", description = "We've spotted a Zandalari war party up the beach. We need to eliminate him before returning to camp.\n\nWould you be willing to handle this one?", objectives = "Kill Nurkala, the Zandalari War Leader.", completion = "Your skills are impressive. You have our gratitude." }
WordHunterWoW_QuestEN[32586] = { title = "Maximum Capacitor", description = "The mines north of here are critical to the mogu supply line. They are using giant lightning enchanted drills to extract the ore.\n\nIf you can disrupt the drills, they'll be destroyed, greatly slowing their ability to make weapons.\n\nOh, also, kill whoever is in charge, will you?", objectives = "Destroy the 3 lightning drills in the Ghost Iron Mines, and kill Metal Lord Mono-Han." }
WordHunterWoW_QuestEN[32587] = { title = "Forge Ahead!", description = "The forge lies ahead of you, and with it the heart of the mogu's weaponsmithing ability.\n\nAnd beyond that, the mogu gatekeeper, who holds the key to unlocking the gate to the next part of the city.\n\nIt's time to move out!", objectives = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder.", progress = "Well?", completion = "Good work. What you did today brings us one step closer to our ultimate goal." }
WordHunterWoW_QuestEN[32588] = { title = "On Her Magic-ey Secret Service", description = "Under orders from Jaina herself, some of our agents attempted to sneak past mogu lines to find out what was going on in the mines.\n\nThey were captured, and are being subjected to who-knows-what kind of awful tortures.\n\nYou must free them and kill whoever captured them. We don't leave anyone behind!", objectives = "Rescue the three captured Kirin Tor agents within the Ghost Iron Mines, and kill Metal Lord Mono-Han." }
WordHunterWoW_QuestEN[32589] = { title = "Life Blood", description = "Scouts unearthed this strange construct hidden within the Lightning Vein Mine. A secret weapon of the Thunder King no doubt.\n\nPerhaps, there is a chance we can use this discovery to our benefit. If we can re-animate it, we can study it. More importantly, we can discover its weakness.\n\nGo to the Throne of Thunder and use this crystal to capture whatever essence animates these constructs.\n\nReturn to me when the task is complete.", objectives = "Use the Attuned Crystal to retrieve the Remnants of the Animus from the Dark Animus within the Throne of Thunder.", progress = "Were you successful in our endeavor?", completion = "Excellent work, <class>. This is a dark magic indeed. We have much to learn here if we are to succeed.\n\nNow, we have only to hope that we can reanimate this creature." }
WordHunterWoW_QuestEN[32590] = { title = "Meet Me Upstairs", description = "There's someone I'd like you to meet. Stormwind's own crown prince recently paid a visit to this humble inn. I've instructed my guards to defend him from any Horde aggression - I don't want to draw any undue attention to myself.\n\nHe and I have been discussing world events, such as the battle along the southern shores, his encounter with Garrosh, and the upcoming assault on the Thunder King.\n\nCome! Let's talk upstairs...", objectives = "Meet Wrathion upstairs on the second floor of the Tavern in the Mists in the Veiled Stair.", completion = "<Wrathion introduces you both.>\n\nPrince Anduin, this is <name>, possibly the most powerful <class> in Pandaria.\n\nOh - do you already know of each other? Interesting." }
WordHunterWoW_QuestEN[32591] = { title = "Secrets of the First Empire", description = "For two thousand years the mogu ruled this entire land. So brutal was their regime that its name is never uttered aloud: Pandaren call it either the \"Old Kingdom\" or \"First Dynasty.\"\n\nThe Thunder King was its founder and first emperor. He amassed enormous power on what is now the Isle of Thunder.\n\nHis time has passed, {name}. We should claim some of his power for ourselves. Gather mogu relics for me from the Throne of Thunder, and amass some trillium - I have a plan!", objectives = "Collect 20 Secrets of the Empire and 40 Trillium Bars.", progress = "What have you uncovered from the Throne of Thunder? Is the Thunder King's ferocious reputation warranted?", completion = "<Wrathion inspects the treasures you brought him.>\n\nWell done. The trillium will need additional refinement, of course, but these samples are pure.\n\nI will need to study these artifacts for a time but I believe I can use the knowledge contained here to craft something of great value to us both." }
WordHunterWoW_QuestEN[32592] = { title = "I Need a Champion", description = "You are a superb representative of your people, {race}. But I need someone special. I have big plans. And to enact them I will need a champion to carry my flame to the four corners of the world.\n\nAre you the one?\n\nProve it to me on the Isle of Thunder! Lay waste to any mogu, Zandalari, or saurok that you find. Impress me!", objectives = "Earn Exalted Reputation with the Black Prince by defeating mogu, Zandalari, and saurok enemies on the Isle of Thunder.", completion = "My Shado-Pan associates have spoken highly of your deeds. You have earned quite the name for yourself here in Pandaria!\n\nIt is settled. When the materials are ready, you will be my champion. You will be my instrument, my standard-bearer, my voice of change across this world.\n\nWe will do marvelous things together." }
WordHunterWoW_QuestEN[32593] = { title = "The Thunder Forge", description = "Everything is prepared, {name}, and I have selected you to be my champion.\n\nNext, we must infiltrate the legendary Thunder Forge of Lei Shen himself! You and your faction will need to advance forward until the Thunder Forge is exposed, if it isn't already.\n\nOnce you have infiltrated the forge, meet me there. Be ready for a fight!", objectives = "Progress through the Isle of Thunder until you unlock the Thunder Forge. Meet Wrathion outside the Thunder Forge and complete his task.", completion = "Behold! The Lightning Lance! A conduit that can channel and control the very same power that the Thunder King used to found an empire.\n\nIt is dormant... but you're about to change that. If you're worthy." }
WordHunterWoW_QuestEN[32594] = { title = "Spirit of the Storm Lord", description = "Our next objective is to temper this weapon with the blood of a demigod, one imbued with the Thunder King's powers.\n\nMy agents tell me that the mogu named Shan Bu is creating just such a creature, intended to guard the Thunder King's citadel.\n\nOnce your faction has fought your way to the front gates, attack Storm Lord Nalak and thrust this lance into his side. The creature will do everything in his power to stop you - stay alive long enough to siphon out the power of the Storm Lord!", objectives = "Progress through the Isle of Thunder until you unlock the final courtyard. Obtain a Tempered Lightning Lance by thrusting the lance into Storm Lord Nalak and surviving long enough to siphon his power.", progress = "What of Storm Lord Nalak? And the lance? Details!", completion = "You've done it! The lance seethes with power and potential!\n\nOh my friend, you have earned a great reward..." }
WordHunterWoW_QuestEN[32595] = { title = "The Crown of Heaven", description = "Do you recall Mason's Folly, the hilltop east of here where you and I met before?\n\nI'm going to use the Lightning Lance to create something special, and I certainly can't do it in here.\n\nMeet me atop Mason's Folly so that we may celebrate our victories together!", objectives = "Meet Wrathion atop Mason's Folly in the Veiled Stair and collect your reward.", completion = "The Crown of Heaven! Use this to augment any piece of headgear.\n\nIt will also act as a third eye - I will be able to follow your progress as we embark on the next stage of our journey." }
WordHunterWoW_QuestEN[32596] = { title = "Echoes of the Titans", description = "I'm beginning to see the bigger picture, now, and how the mogu relate to the Titans. But every answer brings with it more questions!\n\nThe only way to put this puzzle together is to find every scrap of Titan information we can scavenge from the Thunder King's palace. Destroy the Thunder King and his minions and collect as many Titan runestones as you can find!", objectives = "Collect 12 Titan Runestones from raid bosses in the Halls of Flesh-Shaping and the Pinnacle of Storms.", progress = "What have you discovered so far?\n\nWe need to gather all the information we can!", completion = "Thanks to your work, <name>, we've reconstructed an ancient narrative. The mogu were once creatures of stone, enacting the will of the Titans. But then their master fell silent, and they succumbed to the curse of the flesh. Eventually Lei Shen came along, imprisoned the keeper Ra, and took his power. Ah, what an empire he built!\n\nArmed with this knowledge, it's time to act..." }
WordHunterWoW_QuestEN[32597] = { title = "Heart of the Thunder King", description = "The Thunder King. Dead for twelve thousand years, only to be brought back by Zandalari voice. No doubt Titan power preserved his vile corpse.\n\nTitan power that's mine by right.\n\n{name}! Bring me the heart of the Thunder King. I will have it, and once it is mine, none will ever be able to resurrect him again.\n\nBring it to me, {class}. Bring me his cold, dead heart! ", objectives = "Slay the Thunder King in the Halls of Thunder and collect the Heart of the Thunder King.", progress = "The Thunder King! What has become of him?", completion = "<Wrathion squeezes the black heart in his hand, his eyes burning brightly.>\n\nYou did it... you did it! The black heart of the Thunder King!" }
WordHunterWoW_QuestEN[32598] = { title = "A Reckoning", description = "The Thunder King is dead, and his instruments of oppression are being picked over by the Alliance and Horde for their own ends.\n\nWe come now to the climax of the pandaren campaign. Hellscream's machinations have brought the Alliance down on his head - but even more importantly, he's fractured the unity of the Horde. As the Pandaren say: \"The Wok is Hot.\" Something is about to give, and all of our work comes down to this.\n\nI need time to plan. See me as soon as your faction is ready to make its move!", objectives = "Speak with Wrathion upstairs at the Tavern in the Mists in the Veiled Stair.The Thunder King is dead, and his instruments of oppression are being picked over by the Alliance and Horde for their own ends.\n\nWe come now to the climax of the pandaren campaign. Hellscream's machinations have brought the Alliance down on his head - but even more importantly, he's fractured the unity of the Horde. As the Pandaren say: \"The Wok is Hot.\" Something is about to give, and all of our work comes down to this.\n\nI need time to plan. See me as soon as your faction is ready to make its move!You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32599] = { title = "Securing A Future", description = "It is rumored that the Thunder King's power comes directly from a hidden source within his palace.\n\nEven when he is defeated a new tyrant, Garrosh perhaps, could still use this magic to a terrible end.\n\nThat is unless we make the first move!\n\nTake my staff into the Pinnacle of Storms. Once Lei Shen has been defeated place my staff in the center of his dais.\n\nWe will drain the rest of his power and make sure it stays in our hands.", objectives = "Defeat the Thunder King within the Pinnacle of Storms and use the Staff of Antonidas to drain the remaining power from his dais.", progress = "We will be unstoppable once Lei Shen's power has been fused with my staff.", completion = "You have just secured our advantage, <name>. Your work here will be remembered.\n\nGarrosh will be made to pay for his actions!" }
WordHunterWoW_QuestEN[32600] = { title = "The Zandalari Prophecy", description = "Dear {name},\n\nI have read your reports on the Zandalari and believe I have some clues as to their most recent aggression.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring The Zandalari Prophecy to Lorewalker Cho.\n\nProvided item:", completion = "No wonder the Zandalari have come. They are in need of a new home, and I am sure their mogu allies have promised them much.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[32601] = { title = "Rumbles of Thunder", description = "Dear {name},\n\nThe foreboding sound of thunder has haunted my people for generations. And as you have discovered in your own research, Lei Shen is at the heart of that fear.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring the Rumbles of Thunder to Lorewalker Cho.\n\nProvided item:", completion = "What we know of Lei Shen are dark legends that have been remembered over the vast span of time. I often wondered if these legends had exaggerated the power of Lei Shen. But your research would suggest they may have greatly underestimated the Thunder King. These are dark days indeed.\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[32602] = { title = "Gods and Monsters", description = "Dear {name},\n\nIs it true that the mogu are really connected to the titans? I find this very hard to believe. But looking over your research, some of the truth about the mogu begins to take shape.\n\nIf you visit us at the Seat of Knowledge in Vale of Eternal Blossoms we can add this contribution to your personal collection.\n\nThank you for your diligence!\n\nSincerely,\n\nLorewalker Cho", objectives = "Bring the Gods and Monsters to Lorewalker Cho.\n\nProvided item:", completion = "Your research is most distressing. But it sheds light on a truth we have long sought: \"Where did the mogu come from? And why were they such tyrants?\"\n\nWe will add this knowledge to your collection. If you wish me to narrate this for you, simply point at the correct volume in your Private Collection." }
WordHunterWoW_QuestEN[32603] = { title = "Beasts of Fable", description = "Have you ever read the great Pandaren book of fables?  Pandaren pass these stories on to their cubs - stories of the cricket and the hawk, or the slow-moving turtle - to teach them lessons that they will find useful in life. What few cubs know is that these creatures exist, here, in Pandaria! Though the stories of their travels are made up, they are powerful denizens of this world. Should you happen upon them in your travels, you may test the might of your pets against their storied statures.", objectives = "Defeat the Elite Battle Pets of the Pandaren fables.", completion = "You found them all? Amazing! So the stories ARE true! Perhaps you will write the next great Pandaren fable based on your own incredible journey!" }
WordHunterWoW_QuestEN[32604] = { title = "Beasts of Fable Book I", description = "The stories of Ka'wi the Gorger, Nitun, Kafi, and Dos-Ryga will exist in this land, always. Do you wish to meet them in battle once more?", objectives = "Defeat Ka'wi the Gorger, Nitun, Kafi, and Dos-Ryga.", progress = "Do you return victorious?", completion = "I bow to you who continues to walk in the footfalls of the great Pandaren fables." }
WordHunterWoW_QuestEN[32605] = { title = "Subtle Encouragement", description = "The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men.\n\nWe've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Horde lives.", objectives = "Plant Mogu Weapons into the corpses of 9 Skumblade saurok.", progress = "As much as it pains me to say it: try not to kill them all. We need some alive if we want to turn them against the mogu.", completion = "Masterfully done, <class>." }
WordHunterWoW_QuestEN[32606] = { title = "Subtle Encouragement", description = "The saurok are vile, but we share an enemy: the mogu. And I'd rather send saurok to kill mogu than send my own men.\n\nWe've been collecting mogu weaponry. Bury these polearms into the skulls of the saurok. Feed our enemies' rivalry, and you may save Alliance lives.", objectives = "Plant Mogu Weapons into the corpses of 9 Skumblade saurok.", completion = "Masterfully done, <class>." }
WordHunterWoW_QuestEN[32607] = { title = "Extended Shore Leave", description = "The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort.\n\nSimply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault.\n\nNo captain. No repairs. No warship.", objectives = "Steal the Workshop Orders and slay the new captain of the Zandalari warship.", progress = "Each passing hour brings us closer to breaking the Thunder King.", completion = "Casualties are down significantly with that warship out of commission, and we continue to press the siege on Lei Shen.\n\nFantastic work out there today, hero.\n\nPlease, take this - you have earned it." }
WordHunterWoW_QuestEN[32608] = { title = "Raiding the Vault", description = "The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same.\n\nOne artifact in particular, an amulet known as the Choker of Storms, could help us to understand his apparent mastery over lightning.\n\nBreak into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.", objectives = "Steal the Choker of Storms from The Swollen Vault.", progress = "The Thunder King's strength is legendary. We need every advantage we can get if we want to defeat him.", completion = "What's this? A necklace? What are you trying to- ahh, I see... A relic from the Thunder King's vault! Fascinating... Powerful, too.\n\nThe Kirin Tor will keep it safe. In return, please accept this." }
WordHunterWoW_QuestEN[32609] = { title = "Rare Chest Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[32610] = { title = "Rare Boss Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[32611] = { title = "Rare Drop Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[32613] = { title = "Giant Dinosaur Bone", description = "What do you bring Ku'ma?", objectives = "What do you bring Ku'ma?", progress = "What do you bring Ku'ma?", completion = "<Ku'ma shrugs.>" }
WordHunterWoW_QuestEN[32614] = { title = "More Giant Dinosaur Bones", description = "Give them! Give them to me!", objectives = "Give them! Give them to me!", progress = "Give them! Give them to me!", completion = "Bones bones bones bones bones..." }
WordHunterWoW_QuestEN[32615] = { title = "Many More Giant Dinosaur Bones", description = "Who are you? Why have you returned? Hehehe...", objectives = "Who are you? Why have you returned? Hehehe...", progress = "Who are you? Why have you returned? Hehehe...", completion = "Too many, not enough, no no...give them to Ku'ma..." }
WordHunterWoW_QuestEN[32616] = { title = "A Large Pile of Giant Dinosaur Bones", description = "", objectives = "<Ku'ma cackles madly and gestures at you.>", progress = "<Ku'ma cackles madly and gestures at you.>", completion = "Do you fear death? Hehe..." }
WordHunterWoW_QuestEN[32617] = { title = "A Mountain of Giant Dinosaur Bones", description = "", objectives = "<Ku'ma begins to dance around his hovel.>", progress = "<Ku'ma begins to dance around his hovel.>", completion = "<Ku'ma's jaw falls off at the sight of so many bones.>" }
WordHunterWoW_QuestEN[32618] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Randal Hunter at the Eastvale Logging Camp in Elwynn Forest.  Don't forget to buy your mount while you are there!", objectives = "Find Randal Hunter.", completion = "Don't forget to buy your mount while you are here!  Katie Hunter can be found here in camp." }
WordHunterWoW_QuestEN[32621] = { title = "Lightning Steel", description = "Your trained eyes can see that this metal ingot has some very strange properties. Perhaps there are clues to its nature somewhere around here?", objectives = "Investigate the Thunder Forge to find the Secrets of Lightning Steel.\n\nProvided item:", completion = "While the language is incomprehensible, the diagrams in this book yield their knowledge to your skilled blacksmith's eye. It is clear that, by manipulating the properties of ghost iron, you can create a material of great power, perhaps powerful enough to recreate and increase the power of weapons long lost to the mists of time." }
WordHunterWoW_QuestEN[32622] = { title = "Intro Flight", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32626] = { title = "Loot Room Key Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[32627] = { title = "Charged Moganite", description = "We have been dispatching spies into the Sunreaver base of operations on a daily basis. Some had orders to recover charged moganite from the enemy and bring it here.\n\nThey have not returned, and I can confirm they have left the Sunreaver base.\n\nSearch the jungle between here and there and find any of the charged moganite that might have been lost in transit. Bring it to me and we will put it to good use.", objectives = "Recover a Charged Moganite and bring it to Warmage Yurias.", completion = "Well done, champion. This artifact will be put to better use in our hands than in the hands of the Sunreavers." }
WordHunterWoW_QuestEN[32628] = { title = "Tactical Mana Bombs", description = "Ah, {name}, just the {race} I was looking for. I have received another batch of tactical mana bombs that I need planted in key positions across Dawnseeker Promontory to the northwest.\n\nHere, take these. It is time to give the Sunreavers a taste of their own medicine.\n\nPlant one on the Sunreaver ships, another one on their scrying crystals, and the last on the bridge that connects to their forward base. ", objectives = "Plant a Tactical Mana Bomb on a Sunreaver ship, the Scrying Crystals, and on the most inland bridge of Dawnseeker Promontory.", completion = "It pains me to resort to such weaponry, but the Sunreavers must be taught the price of their actions." }
WordHunterWoW_QuestEN[32629] = { title = "Thunderwing Captured Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[32630] = { title = "Chief Engineer Jard's Journal", description = "What an unusual power source. Wonder how it works? And what it can be used to create?", objectives = "Investigate the Thunder Forges to find the Secrets of Stabilized Lightning.What an unusual power source. Wonder how it works? And what it can be used to create?You will receive:" }
WordHunterWoW_QuestEN[32631] = { title = "High Recognition", description = "", objectives = "Your presence on the battlefield cannot be ignored. I would like to give you something extra for your efforts, <class>." }
WordHunterWoW_QuestEN[32632] = { title = "Made for War", description = "Some things are built with multiple purposes in mind. Some things are built with the sole purpose of destruction.\n\nA massive construct called the Pyrestar Demolisher sits guarding Dawnseeker Promontory. Its purpose is solely to destroy. It must be dismantled.", objectives = "Kill the Pyrestar Demolisher.", completion = "Excellent work, <race>. The problem with constructs is they can always be rebuilt.\n\nI imagine it will not take the Sunreavers long to build a new death machine." }
WordHunterWoW_QuestEN[32633] = { title = "Spellbound", description = "Grand Magister Rommath has something in his possession that I want.\n\nHe brought a very powerful tome with him. It would be better for our cause if it were no longer in Sunreaver hands.\n\nLocate Rommath's book of incantations and bring it to me.", objectives = "Retrieve Rommath's Book of Incantations from Dawnseeker Promontory.", progress = "Did you find the tome?", completion = "Ah yes! This is it. You've done well, <race>." }
WordHunterWoW_QuestEN[32634] = { title = "Breaking Down the Defenses", description = "Even the strongest defense can still have a weakness, {class}. We just need to find the weakness in the Sunreaver's defense and then exploit it as much as possible.\n\nScouts have reported the use of perimeter wards around Dawnseeker Promontory. They're powerful, but not deadly.\n\nDisabling them would allow us to keep closer watch on their activities.", objectives = "Destroy 6 Sunreaver Perimeter Wards around Dawnseeker Promontory.", completion = "Excellent work, <race>! I was able to get a few of my scouts behind their lines before the perimeter wards were repaired." }
WordHunterWoW_QuestEN[32635] = { title = "Enough with the Bombs!", description = "The Sunreavers have planted tactical mana bombs around our camp. These must be dismantled before they are detonated.\n\nLook for them in areas of high importance such as our supplies. Make sure you find and disable them all. We cannot afford to lose any ground here.", objectives = "Disarm the Tactical Mana Bombs at the Alliance Ships, the Construct Ritual, and the Supplies within Violet Rise.", completion = "I'm grateful for your efforts here, <name>. We would have lost so much had you not disarmed those bombs in time." }
WordHunterWoW_QuestEN[32636] = { title = "Captive Audience", description = "The Sunreavers will stoop to even the lowest levels to get what they want, {name}.\n\nI received reports earlier that several Kirin Tor have gone missing. I suspect the Sunreavers may have something to do with this.\n\nHopefully they have not been harmed, or my wrath will be swift and terrible. I trust you to bring them back in one piece, but please hurry.", objectives = "Free 5 Kirin Tor Captives near Dawnseeker Promontory.", completion = "You have saved many today, <name>. I cannot imagine the horror of being frozen and helpless among so many enemies." }
WordHunterWoW_QuestEN[32637] = { title = "Overpowered", description = "The Sunreaver forces have grown more powerful recently. I suspect magic to be at play here, but I can't be certain.\n\nI think it would be wise to investigate their camp to see if you can find the source of this extra power.\n\nOnce you find it, use this crystal to overload and destroy it.", objectives = "Destroy 7 Sunreaver Mana Collectors around Dawnseeker Promontory.", completion = "So they've constructed objects that infuse their forces with additional power? This will have to be watched closely.\n\nThank you for your efforts today." }
WordHunterWoW_QuestEN[32638] = { title = "Mana Scavengers", description = "Sometimes, even the smallest creatures can be the biggest threat.\n\nThe Sunreavers brought mana wyrms with them. Though small in size they have the ability to cripple our casters in combat. Many have learned the hard way not to underestimate them.\n\nThey must be dealt with and quickly.", objectives = "Kill 9 Sunreaver Mana Wyrms.", completion = "You've made excellent progress today, <class>. Rest assured however, our work here is nowhere close to done." }
WordHunterWoW_QuestEN[32639] = { title = "Deconstruction", description = "Scouts are reporting a large number of constructs patrolling outside of Dawnseeker Promontory.\n\nIf left unchecked they will pose a considerable threat should the Sunreavers mount an attack.\n\nThe only answer is a preemptive strike. We'll destroy them before they can attack us!", objectives = "Destroy 3 Sunreaver Constructs outside of Dawnseeker Promontory.", completion = "Good work, <class>. As long as we keep the construct numbers in check, we will ensure our success here." }
WordHunterWoW_QuestEN[32640] = { title = "Champions of the Thunder King", description = "This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities.\n\nIf you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them.\n\nFind and destroy members of each group to keep them destabilized, and I will make it worth your time.", objectives = "Use Shan'ze Ritual Stones to perform the Lightning Ritual, the Spirit Ritual, and the Primal Ritual at various locations across the Isle of Thunder, and then defeat the powerful opponents that are summoned forth.", progress = "Against these ancient enemies, there is no rescourse.  We strike first, and they do not strike at all.", completion = "Yours skills as a <class> are unquestionable. You've aided the cause greatly this day. You have my thanks.\n\nAnd now for that reward I promised you..." }
WordHunterWoW_QuestEN[32641] = { title = "Champions of the Thunder King", description = "This island is riddled with lurking threats from three powerful groups, waiting for the chance to pounce on us. Masters of lightning, ancient and powerful spirits, and primal Zandalari monstrosities.\n\nIf you can get your hands on some of the Shan'ze Ritual Stones scattered across the isle, you should be able to beckon these powerful opponents out of hiding and strike out at them.\n\nFind and destroy members of each group to keep them destabilized, and I will make it worth your time.", objectives = "Use Shan'ze Ritual Stones to perform the Lightning Ritual, the Spirit Ritual, and the Primal Ritual at various locations across the Isle of Thunder, and then defeat the powerful opponents that are summoned forth.", progress = "Against these ancient enemies, there is no rescourse.  We strike first, and they do not strike at all.", completion = "Yours skills as a <class> are unquestionable. You've aided the cause greatly this day. You have my thanks.\n\nAnd now for that reward I promised you..." }
WordHunterWoW_QuestEN[32642] = { title = "Work Order: Dominance Offensive I", description = "<Yoon's writing decorates the page though his feelings seem conflicted.>\n\nI normally try to stay out of conflict, but an order is an order. Since you are of the Horde I decided to pass this order your way.\n\nThe Dominance Offensive has requested an order of red blossom leeks.\n\nThe troops down there just can't seem to get enough of them!", objectives = "Plant 8 Red Blossom Leek Seeds on Sunsong Ranch." }
WordHunterWoW_QuestEN[32643] = { title = "Work Order: Dominance Offensive II", description = "Once your red blossom leeks are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your red blossom leeks will be a part of your faction's efforts in Pandaria!", objectives = "Harvest 8 Ripe Red Blossom Leek plants and provide 40 Red Blossom Leeks for the Dominance Offensive.", progress = "The crate sits empty awaiting your crops.", completion = "Throw the Red Blossom Leeks into the crate! A Dominance Offensive representative will be along shortly for pick-up." }
WordHunterWoW_QuestEN[32644] = { title = "The Assault on Shaol'mara", description = "Our scouting efforts along the coast have given us valuable intelligence about the island, {class}.\n\nHowever, we will accomplish nothing if we do not advance forward onto the mainland.\n\nI have assembled a team of our most elite aerial units to begin the attack.\n\nI would like you to join the assault. A champion such as yourself could turn the battle in our favor at the critical moment.\n\nWhen you are ready to begin the attack, speak to me.", objectives = "Complete the Assault on Shaol'mara. Speak to Jaina Proudmoore to begin the attack.", progress = "We must claim a better strategic position on the island itself.", completion = "Yes! You have done it, champion!\n\nNow, the Thunder King will taste the full force of the Kirin Tor!" }
WordHunterWoW_QuestEN[32645] = { title = "Work Order: Operation: Shieldwall I", description = "<Yoon's writing decorates the page though his feelings seem conflicted.>\n\nI normally try to stay out of conflict, but an order is an order. Since you are of the Alliance I decided to pass this order your way.\n\nOperation: Shieldwall has requested a whole heap of witchberries.\n\nI can't be sure, but I think they have an idea to use them in some sort of weapon.", objectives = "Plant 8 Witchberry Seeds on Sunsong Ranch." }
WordHunterWoW_QuestEN[32646] = { title = "Work Order: Operation: Shieldwall II", description = "Once your witchberries are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your witchberries will be a part of your faction's efforts in Pandaria!", objectives = "Harvest 8 Ripe Witchberry plants and provide 40 Witchberries for Operation: Shieldwall.", progress = "The crate sits empty awaiting your crops.", completion = "Throw the Witchberries into the crate! An Operation: Shieldwall representative will be along shortly for pick-up." }
WordHunterWoW_QuestEN[32647] = { title = "Work Order: Golden Lotus I", description = "<Yoon kept this order request short.>\n\nThe Golden Lotus have requested a large number of white turnips.\n\nTheir request mentioned something about trouble-making sprites wreaking havoc on Mistfall Village. Apparently the sprites don't like turnips!", objectives = "Plant 8 White Turnip Seeds on Sunsong Ranch." }
WordHunterWoW_QuestEN[32648] = { title = "Work Order: Golden Lotus II", description = "Well, hopefully these crops will be suitable!\n\nOnce your white turnips are ready to be picked, you'll need only to package them for pick-up.", objectives = "Harvest 8 Ripe White Turnip plants and provide 40 White Turnips for the Golden Lotus.", progress = "The crate sits empty awaiting your crops.", completion = "Throw the White Turnips into the crate! A Golden Lotus representative will be along shortly for pick-up." }
WordHunterWoW_QuestEN[32649] = { title = "Work Order: Shado-Pan I", description = "<Yoon's writing seems rushed. He must have been excited.>\n\nThe Shado-Pan want crops from you! What an honor indeed!\n\nA request came in this morning for green cabbages. Apparently, they make a rather tasty cabbage soup with them.\n\nOnly the finest will do for the Shado-Pan!", objectives = "Plant 8 Green Cabbage Seeds on Sunsong Ranch." }
WordHunterWoW_QuestEN[32650] = { title = "Work Order: Shado-Pan II", description = "Well, your work is done for the day! Now to wait for the harvest tomorrow.\n\nOnce your green cabbages are ready to be picked, you'll need only to package them for pick-up.\n\nOnly the finest cabbage will do for the Shado-Pan!", objectives = "Harvest 8 Ripe Green Cabbage plants and provide 40 Green Cabbages for the Shado-Pan.", progress = "The crate sits empty awaiting your crops.", completion = "Gently place the Green Cabbages into the crate! A Shado-Pan representative will be along shortly for pick-up." }
WordHunterWoW_QuestEN[32651] = { title = "Intro Flight", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[32652] = { title = "To the Skies!", description = "We have a plan to halt the mogu's weaponmaking capabilities, and it involves the creature you recovered from the Zandalari.\n\nSpeak to me when you're ready to learn more.", objectives = "Gain access to the Lightning Vein Mine.", progress = "It's time to begin your mission!", completion = "Incredible work. This presents us with a monumental opportunity." }
WordHunterWoW_QuestEN[32653] = { title = "Work Order: The August Celestials I", description = "<Yoon's familiar writing scrolls across the tattered paper.>\n\nThe trainees out at the Cradle of Chi-Ji are in need of striped melons. Apparently, they use them in their training exercises.\n\nA representative will be by tomorrow to collect whatever striped melons you can spare.", objectives = "Plant 8 Striped Melon Seeds on Sunsong Ranch." }
WordHunterWoW_QuestEN[32654] = { title = "Tear Down This Wall!", description = "The time has come. Our forces are well-enough entrenched here that we can risk pressing forward, into the Thunder King's lair. Unfortunately, it doesn't look like he'll be opening that gate anytime soon.\n\nI suppose we'll have to make a gate of our own then. Let me know when you're ready, {name}.", objectives = "Speak with Lady Jaina Proudmoore, then break into the lower city and secure it for the Alliance.", progress = "Let's tear down this wall.", completion = "With your help, we're one giant step closer to our goal." }
WordHunterWoW_QuestEN[32655] = { title = "A Bold Idea", description = "Zandalari warships plunder the seas around this island. They ferry in soldiers and war beasts from Zandalar to bolster Lei Shen's army.\n\nIf we can capture the palace shipyard, the Thunder King's supply line will be cut off, and your foothold here will be secure.\n\nI have a plan to do just that, and it won't take an entire army.", objectives = "Infiltrate Stormsea Landing and open the courtyard gate from within. Speak with Taoshi to begin the mission.", completion = "Well done. That warship won't be raining fire on us again any time soon.\n\nTaran Zhu has informed me that the Shado-Pan will keep vigil over Stormsea Landing, freeing up Kirin Tor resources to press the siege elsewhere. Taoshi will be there. I am sure she will be glad to work with you again.\n\nWe are all grateful for your contributions, <name>. Thank you." }
WordHunterWoW_QuestEN[32656] = { title = "The Fall of Shan Bu", description = "Lei Shen found a clutch of rare storm dragon eggs early in his campaign. One - known as Nalak - was particularly brutal and killed all of its handlers, so he took it for his own.\n\nNow, Shan Bu, one of Lei Shen's most loyal servants, works to resurrect the dragon.\n\nIt is time for us to strike against Shan Bu!\n\nSpeak to me when you are ready to launch the assault!", objectives = "Defeat Shan Bu.", progress = "The time to defeat Shan Bu is now!", completion = "You've done it, <class>! Shan Bu is dead once and for all, and we've learned that Lor'themar may not be all that he seems." }
WordHunterWoW_QuestEN[32657] = { title = "Work Order: The August Celestials II", description = "Once your striped melons are ready to be picked, you'll need only to package them for pick-up.\n\nA trainee from the Cradle of Chi-Ji will be along shortly to collect their order.", objectives = "Harvest 8 Ripe Striped Melon plants and provide 40 Striped Melons for the August Celestials.", progress = "The crate sits empty awaiting your crops.", completion = "Throw the Striped Melons into the crate! Now the August Celestials' order is ready to go!" }
WordHunterWoW_QuestEN[32658] = { title = "Work Order: The Klaxxi I", description = "<Though Yoon's writing leaves something to be desired, it's nice to still have a little piece of him on the farm.>\n\nAn order came in this morning from the Klaxxi. Strangely enough they are requesting mogu pumpkins for some kind of research.\n\nI find it's best not to ask them too many questions...\n\nBest get started on their order. I'd hate to see what a bug of that size could do to your crops if you don't!", objectives = "Plant 8 Mogu Pumpkin Seeds on Sunsong Ranch." }
WordHunterWoW_QuestEN[32659] = { title = "Work Order: The Klaxxi II", description = "Once your mogu pumpkins are ready to be picked, you'll need only to package them for pick-up.\n\nI wouldn't dilly-dally if I were you. The Klaxxi aren't known for their patience!", objectives = "Harvest 8 Ripe Mogu Pumpkin plants and provide 40 Mogu Pumpkins for the Klaxxi.", progress = "The crate sits empty awaiting your crops.", completion = "Throw the Mogu Pumpkins into the crate! A Klaxxi representative will be along shortly for pick-up." }
WordHunterWoW_QuestEN[32661] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Aalun at the entrance to the Exodar on Azuremyst Isle.  Don't forget to buy your mount while you are there!", objectives = "Find Aalun.", completion = "Don't forget to buy your mount while you are here! Torallius is right over there." }
WordHunterWoW_QuestEN[32662] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Ultham at the Amberstill Ranch in Dun Morogh, along the road east out of Ironforge.  Don't forget to buy your mount while you are there!", objectives = "Find Ultham Ironhorn.", completion = "Don't forget to buy your mount while you are here! Veron Amberstill is standing just outside the gates to the Ranch." }
WordHunterWoW_QuestEN[32663] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Binjy Featherwhistle at the Steelgrill's Depot in Dun Morogh.  Don't forget to buy your mount while you are there!", objectives = "Find Binjy Featherwhistle.", completion = "Don't forget to buy your mount while you are here! Milli's right over there!" }
WordHunterWoW_QuestEN[32664] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Jartsam at the Cenarion Enclave in Darnassus.  Don't forget to buy your mount while you are there!", objectives = "Find Jartsam.", completion = "Don't forget to buy your mount while you are here! You can buy one from Lelanai right here." }
WordHunterWoW_QuestEN[32665] = { title = "Learn To Ride", description = "It's time for you to learn how to ride!  Seek out Mei Lin north of the Dwarven District in Stormwind.  Don't forget to buy your mount while you are there!", objectives = "Find Mei Lin.", completion = "Don't forget to buy your mount while you are here! You can buy one from Old Whitenose here." }
WordHunterWoW_QuestEN[32666] = { title = "FLAG - Warlock - Green Fire", description = "", objectives = "" }
WordHunterWoW_QuestEN[32667] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Softpaws in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!", objectives = "Find Softpaws.", completion = "Don't forget to buy your mount while you are here! You can buy one from Turtlemaster Odai here." }
WordHunterWoW_QuestEN[32668] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Perascamin at Thuron's Livery, southeast of the Shepherd's Gate leaving Silvermoon City. Don't forget to buy your mount while you are there!", objectives = "Find Perascamin.", completion = "Don't forget to buy your mount while you are here! You can buy one from Winaestra just outside." }
WordHunterWoW_QuestEN[32669] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Kildar in Orgrimmar's Valley of Honor. Don't forget to buy your mount while you are there!", objectives = "Find Kildar.", completion = "Don't forget to buy your mount while you are here! You can buy one from Ogunaro over there." }
WordHunterWoW_QuestEN[32670] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Kar Stormsinger in Mulgore's Bloodhoof Village. Don't forget to buy your mount while you are there!", objectives = "Find Kar Stormsinger.", completion = "Don't forget to buy your mount while you are here! You can buy one from Harb Clawhoof over there." }
WordHunterWoW_QuestEN[32671] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Xar'Ti at Sen'jin Village in southern Durotar. Don't forget to buy your mount while you are there!", objectives = "Find Xar'Ti.", completion = "Don't forget to buy your mount while you are here! You can buy one from Zjolnir over there." }
WordHunterWoW_QuestEN[32672] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Velma Warnam at Brill in Tirisfal Glades. Don't forget to buy your mount while you are there!", objectives = "Find Velma Warnam.", completion = "Don't forget to buy your mount while you are here! You can buy one from Zachariah Post here." }
WordHunterWoW_QuestEN[32673] = { title = "Learn To Ride", description = "It's time for you to learn how to ride! Seek out Revi Ramrod in Orgrimmar's Valley of Spirits. Don't forget to buy your mount while you are there!", objectives = "Find Revi Ramrod.", completion = "Don't forget to buy your mount while you are here! You can buy one from Kall Worthaton over there." }
WordHunterWoW_QuestEN[32674] = { title = "I Believe You Can Fly", description = "The skies call out to you! It's time to learn to fly!\n\nVisit the flying trainer, Maztha, at the Skyway in Orgrimmar.\n\nAnd don't forget to buy a flying mount!", objectives = "Find Maztha.", completion = "Ah, good to see you. You look like you are ready to take to the skies!\n\nRemember, you can buy a flying mount from Drakma, just behind me." }
WordHunterWoW_QuestEN[32675] = { title = "I Believe You Can Fly", description = "The skies call out to you! It's time to learn to fly!\n\nVisit the flying trainer, Bralla Cloudwing, at the Gryphon Roost in Stormwind.\n\nAnd don't forget to buy a flying mount!", objectives = "Find Bralla Cloudwing.", completion = "Ah, good to see you. You look like you are ready to take to the skies!\n\nRemember, you can buy a flying mount from Tannec Stonebeak over there." }
WordHunterWoW_QuestEN[32676] = { title = "Extended Shore Leave", description = "The Zandalari have already begun repairing that warship, but we can keep it crippled with minimal effort.\n\nSimply relieve the new captain of his post, and steal the ship's damage report from that workshop just outside the vault.\n\nNo captain. No repairs. No warship.", objectives = "Steal the Workshop Orders and slay the new captain of the Zandalari warship.", progress = "Lei Shen will fall to our onslaught, and my people will find glory in his ruin.", completion = "This so-called \"Thunder King\" is surrounded and cut off from his allies. No tyrant is strong enough to stand alone.\n\nYour efforts have not gone unnoticed. Take this, with my thanks." }
WordHunterWoW_QuestEN[32677] = { title = "Raiding the Vault", description = "The Swollen Vault is a repository for some of Lei Shen's nastiest weaponry and most prized trinkets - not surprisingly, these are often one and the same.\n\nOne artifact in particular, an amulet known as the Choker of Storms, could help us to understand his apparent mastery over lightning.\n\nBreak into the vault and slay the hoard-keeper. Take his key and use it to recover the amulet from a cache at the back of the vault.", objectives = "Steal the Choker of Storms from The Swollen Vault.", progress = "You have good news, I hope.", completion = "Ah, I know a powerful artifact when I see one. You were wise to bring this here. I will see that Aethas examines it right away - perhaps we can put it to work in our favor.\n\nIn the meantime, take this in trade." }
WordHunterWoW_QuestEN[32678] = { title = "Thunder Calls", description = "The time to attack the Thunder King has come!\n\nA small group of Sunreavers awaits you near the Shado-Pan Garrison in Townlong Steppes.\n\nReport to Scout Captain Elsia for further instructions.", objectives = "Report to Scout Captain Elsia at the Shado-Pan Garrison in Townlong Steppes.", completion = "We must move quickly, <name>! The others have gone ahead of us, but I will brief you in the flight over." }
WordHunterWoW_QuestEN[32679] = { title = "Thunder Calls", description = "The time to attack the Thunder King has come!\n\nA small group of Kirin Tor awaits you near the Shado-Pan Garrison in Townlong Steppes.\n\nReport to Vereesa Windrunner for further instructions.", objectives = "Report to Vereesa Windrunner at the Shado-Pan Garrison in Townlong Steppes.", completion = "We must move quickly, <name>! The others have gone ahead of us, but I will brief you in the flight over." }
WordHunterWoW_QuestEN[32680] = { title = "The Storm Gathers", description = "There is no time to waste, {name}. Every moment we delay here gives Jaina and the Kirin Tor more of a hold on the Isle.\n\nLor'themar awaits us. Speak to me when you are ready to depart. I will escort you there myself.", objectives = "Travel with Scout Captain Elsia to the Isle of Thunder.", progress = "This isle holds many secrets my friend.", completion = "You have arrived just in time, <race>. It is crucial we gain control of these shores before the Kirin Tor.\n\nThere is much to explain." }
WordHunterWoW_QuestEN[32681] = { title = "The Storm Gathers", description = "There is no time to waste, {name}. Every moment we delay here gives the Sunreavers more of a hold on the Isle.\n\nLady Jaina Proudmoore awaits us. We should not make her wait any longer.\n\nSpeak to me when you are ready to depart. I will escort you there myself.", objectives = "Travel with Vereesa Windrunner to the Isle of Thunder.", progress = "The key to our safety lies here, <name>. I feel it to my core that we are meant to be here.", completion = "You have arrived just in time, <name>. This land needs to be controlled by the Kirin Tor for everyone's safety. This will not be an easy task." }
WordHunterWoW_QuestEN[32682] = { title = "Inherit the Earth", description = "As you know, {name}, I'm getting along in my years. One can't stay a spry young pandaren forever, you know.\n\nI'm looking for someone to take over my duties here at the Tillers Union, and I can't think of a better person than Farmer Yoon.\n\nHe's got a good deal to learn, but he's got a good head on his shoulders and most importantly, a generous heart.\n\nDo you think he'd be interested?", objectives = "Speak to Farmer Yoon.", completion = "Why I just knew you could convince him, <name>. You've set my heart at ease, knowing the Tillers will be in good hands." }
WordHunterWoW_QuestEN[32683] = { title = "So You Want to Be a Blacksmith...", description = "While it is best to learn the properties of simpler metals and work your way up, it is possible to learn how to become a good blacksmith through mastering the various applications of ghost iron for common household objects. If you wish to take this path towards becoming a zen master blacksmith, I can teach you. Whichever way you choose, you will have my respect if you can show me that you can make a ghostly skeleton key.", objectives = "Create a Ghostly Skeleton Key by attaining at least 500 skill in blacksmithing. If you wish to train through pandaren materials, a training project appropriate to your skill level can be learned from Cullen Hammerbrow.", progress = "How are your studies coming along?", completion = "Well done. You are ready to become a zen master blacksmith." }
WordHunterWoW_QuestEN[32684] = { title = "You Want Fish?", description = "Are you looking for golden carp? or some other Pandaren fish? I'm no fisherman myself, but there is a fellow by the river who has been teaching the folks traveling through here. If you go speak with him, he will likely give you some fish, as well as teach you how to fish.", objectives = "Speak with Ben of the Booming Voice.", completion = "Ah!  Have you come to learn how to fish? You're talking to the right person. First, here - have some fish!" }
WordHunterWoW_QuestEN[32685] = { title = "No Fishing Pole Necessary!", description = "You don't even need to equip a fishing pole in Pandaria!\n\nThe waters are TEEMING with fish. You'll catch one pretty much every time, as long as you are paying attention. Give it a go!", objectives = "Catch 5 Golden Carp. Try it without a fishing pole!\n\nTo fish, simply click the Fishing icon on the Profession pane. Pay attention to the bobber, click on it when it bobs and you will have your fish!", progress = "Catch 5 Golden Carp. Try it without a fishing pole!", completion = "Let me see...  Yes, these are nice. Good job! Here, have some more." }
WordHunterWoW_QuestEN[32686] = { title = "Pristine Banner of the Mantid Empire", description = "This artifact has been restored to a remarkably excellent condition.  Perhaps you will put it on display at the Seat of Knowledge, so that lorewalkers and archaeologists can study it.", objectives = "Put the artifact on display.", progress = "Remove the clutter and put the artifact on display.", completion = "This will aid lorewalkers and archaeologists in understanding the history of Pandaria." }
