WordHunterWoW_QuestEN[32706] = { title = "Allies in the Shadows", description = "The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces.\n\nI want you to meet with Taran Zhu, the leader of the Shado-Pan, and offer your services on behalf of the Kirin Tor. I doubt he is truly in need of the aid, but the gesture holds importance in itself.", objectives = "Speak to Taran Zhu in Bleak Hollow.", completion = "Welcome, <name>." }
WordHunterWoW_QuestEN[32707] = { title = "Secrets in the Isle of Thunder", description = "I do have one thing I would ask of you, {class}.\n\nWe've gotten our hands on a powerful ritual stone that the Shan'ze mogu use to beckon their allies into battle, but we need more than one to perform their rituals.\n\nIf you come upon three of these stones, bring them back to me. We can gather our forces and use these stones to beckon some of Lei Shen's most powerful servants directly into our traps.", objectives = "Recover 3 Shan'ze Ritual Stones. These stones are very rare, and may take some time to gather.", progress = "Have you found the stones I spoke of?", completion = "Perfect. I will show you how to use these stones, and then you can spring the ambush." }
WordHunterWoW_QuestEN[32708] = { title = "Setting the Trap", description = "Take these 3 ritual stones to the location I have marked on your map. There, you will find a Shan'ze ritual object that you can use to beckon one of their powerful allies.\n\nYou will need capable friends at your side for this trap to work. Do not go alone, for these will be some of the Thunder King's most powerful servants.\n\nWhen your enemy shows itself, show no mercy. ", objectives = "Use 3 Shan'ze Ritual Stones to beckon a Champion of the Thunder King, and then kill him.", progress = "Did the ambush succeed?", completion = "Very impressive.\n\nShould you find more stones, you should continue this ruse. It is sure to be quite some time before they catch on to our ploy." }
WordHunterWoW_QuestEN[32709] = { title = "Allies in the Shadows", description = "The Shado-Pan arrived here before we did, and they are already at work undermining the Thunder King's forces.\n\nI want you to meet with Taran Zhu, the leader of the Shado-Pan, and offer your services on behalf of the Sunreavers. I doubt he is truly in need of the aid, but the gesture holds importance in itself.", objectives = "Speak to Taran Zhu in Bleak Hollow.", completion = "Welcome, <name>." }
WordHunterWoW_QuestEN[32710] = { title = "Something Foul is Afoot", description = "You notice a stronger-than-usual smell permeating from ahead. Your stomach lurches as the thick smell fills your nostrils.\n \nYou recognize this smell, it's saurok. Rotting, discarded saurok flesh infused with the foul waste of the sewer.", objectives = "Seek and destroy Flesh'rok the Diseased." }
WordHunterWoW_QuestEN[32711] = { title = "Agony and Anima", description = "You notice the initials A.K. skillfully and with calligraphic precision engraved onto the side of the Animus.\n\nBefore you stands Archritualist Kelada, the shaper of the Animus. By command of the Thunder King, Kelada worked tirelessly to craft the perfect vessel to harness the great power of the anima. Something functional, magnificent, sentient, but most importantly... something deadly.\n\nHe must be stopped before his next imagination is brought to life by the Thunder King.", objectives = "Slay Archritualist Kelada." }
WordHunterWoW_QuestEN[32712] = { title = "Zao'cho the Wicked", description = "Electricity hums in the distance, tickling your ears and sending impulses down your spine. Your fingers go numb, and  your heart races as you approach the door ahead.\n\nZao'cho stands arrogantly atop the steps ahead, weaving lightning between his fingers and smirking at you with demented glee.", objectives = "Slay Zao'cho." }
WordHunterWoW_QuestEN[32713] = { title = "Rocks Fall, People Die", description = "Words fail to describe the massive horror of rock, bone, and blood that rumbles mindlessly and aimlessly ahead of you.\n \nMassive earthquakes crack the seemingly hollow shell of ground beneath the figure, leaving destruction in its wake. It appears that the creature is unaware of your presence.", objectives = "Slay the Rocky Horror." }
WordHunterWoW_QuestEN[32714] = { title = "Taming the Tempest", description = "You hear a fierce and militant voice roaring in the distance. A crackling storm swells and swirls around a clouded, shadowy figure. Lightning flashes and No'ku Stormsayer appears, his scornful gaze aimed directly at you.", objectives = "Slay No'ku Stormsayer." }
WordHunterWoW_QuestEN[32715] = { title = "Requiem for a Queen", description = "A chilling breeze sweeps across your body, bringing with it a haunting drape of sadness. Your soul sinks as you hear the faint, melodic cries of Monara, the last Queen of the Mogu.\n\nHer sweet requiem creeps through the air, bending and shaping itself into a spectral hand, reaching for your heart. As it grabs hold, you see a brief flash of Monara's last moments... her brutal murder by the hand of Lei Shen.\n\nSong turns to sadness and Monara weeps, wailing louder and louder into the darkness.", objectives = "Put Monara to rest." }
WordHunterWoW_QuestEN[32716] = { title = "Eyes of the Thunder King", description = "As the fog dissipates from the fallen sentries, you feel a sudden rumbling.\n\nThe rocks blocking the sewer tunnels tumble forward and crash into the outflow tanks below, as four putrid eyes lunge from the darkness.", objectives = "Defeat the ambush!" }
WordHunterWoW_QuestEN[32717] = { title = "REUSE ME", description = "", objectives = "" }
WordHunterWoW_QuestEN[32718] = { title = "Mogu Runes of Fate", description = "Greetings, <name>. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Mogu Rune of Fate, valuable artifacts will find their way into your hands more frequently inside the palace of the Thunder King.", objectives = "Collect 50 Lesser Charms of Good Fortune.", progress = "May these charms bring you great luck, <name>.", completion = "May the stars smile upon you, <name>." }
WordHunterWoW_QuestEN[32719] = { title = "Mogu Runes of Fate", description = "Greetings, <name>. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Mogu Rune of Fate, valuable artifacts will find their way into your hands more frequently inside the palace of the Thunder King.", objectives = "Collect 50 Lesser Charms of Good Fortune.", progress = "May these charms bring you great luck, <name>.", completion = "May the stars smile upon you, <name>." }
