WordHunterWoW_QuestEN[32722] = { title = "Forge Ahead!", description = "There's more you must do. \n\nKill Itoka, master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.", objectives = "Kill the Master of the Forge and collect a Codex Fragment from Fleshcrafter Hoku in the Isle of Thunder.", progress = "Well?", completion = "Good work. What you did today brings us one step closer to our ultimate goal." }
WordHunterWoW_QuestEN[32723] = { title = "reuse me", description = "There's more you must do. \n\nKill Itoka, master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.You will receive:", objectives = "Kill the Master of the Forge and Collect a Codex Fragment from the Mogu Gatekeeper in the Isle of Thunder." }
