WordHunterWoW_QuestEN[32726] = { title = "So You Want to Be a Blacksmith...", description = "While it is best to learn the properties of simpler metals and work your way up, it is possible to learn how to become a good blacksmith through mastering the various applications of ghost iron for common household objects. If you wish to take this path towards becoming a zen master blacksmith, I can teach you. Whichever way you choose, you will have my respect if you can show me that you can make a ghostly skeleton key.", objectives = "Create a Ghostly Skeleton Key by attaining at least 500 skill in blacksmithing. If you wish to train through pandaren materials, a training project appropriate to your skill level can be learned from Jorunga Stonehoof.", progress = "How are your studies coming along?", completion = "Well done. You are ready to become a zen master blacksmith." }
WordHunterWoW_QuestEN[32727] = { title = "Contributed to Server Percentage Daily Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[32728] = { title = "The Court of Bones", description = "The mogu within the nearby Court of Bones pose a constant threat to our foothold on this island. Grand Magister Rommath has been entrusted with halting their efforts, but I am certain he could use a capable {class} to see this task through.\n\nGo to him. Aid in whatever ways that you are able.", objectives = "Find Grand Magister Rommath outside the Court of Bones.", completion = "Yes, good, come... there is work to be done." }
WordHunterWoW_QuestEN[32729] = { title = "Za'Tual", description = "The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Halduron Brightwing to take charge of dismantling their presence at Za'Tual, in the south.\n\nReport to Halduron when you are best able. He will have work for you.", objectives = "Find Halduron Brightwing outside of Za'Tual.", completion = "One more to join the Zandalari hunt?  Good.  Very good." }
WordHunterWoW_QuestEN[32730] = { title = "Ihgaluk Crag", description = "Aethas has taken over at Ihgaluk Crag, to the southeast, continuing his effort to turn the Saurok against the Zandalari and mogu.\n\nGo to him, and help in any way that you can.", objectives = "Find Archmage Aethas Sunreaver outside of Ihgaluk Crag.", completion = "You have good timing. I am quite in need of your assistance." }
WordHunterWoW_QuestEN[32731] = { title = "The Court of Bones", description = "The mogu within the nearby Court of Bones comprise one of the greatest threats to our presence on this island. Narasi Snowdawn has been entrusted with halting their efforts, but I am certain she could use a capable {class} to see this task through.\n\nGo to her. Aid in whatever ways that you are able.", objectives = "Find Narasi Snowdawn outside the Court of Bones.", completion = "Yes, good, come... there is work to be done." }
WordHunterWoW_QuestEN[32732] = { title = "Ihgaluk Crag", description = "Archmage Modera has taken over at Ihgaluk Crag, to the southeast, continuing her efforts to turn the Saurok against the Zandalari and mogu.\n\nGo to her, and help in any way that you can.", objectives = "Find Archmage Modera outside of Ihgaluk Crag.", completion = "You have good timing. I am quite in need of your assistance." }
WordHunterWoW_QuestEN[32733] = { title = "Za'Tual", description = "The Zandalari have been a constant nuisance since we arrived on this island. I've assigned Archmage Lan'dalock to take charge of dismantling their presence at Za'Tual, in the south.\n\nReport to him when you are best able. He will have work for you.", objectives = "Find Archmage Lan'dalock outside of Za'Tual.", completion = "One more to join the Zandalari hunt?  Good.  Very good." }
