WordHunterWoW_QuestEN[32892] = { title = "War is Coming", description = "As you enter the vale, you see a rotund pandaren trying to flag you down from the balcony above Mogu'shan Palace. It looks like Lorewalker Cho is trying to get your attention. You should investigate!", objectives = "Speak with Lorewalker Cho.", completion = "Ah! Welcome my friend. I am very glad that I was able to get your attention. Great deeds are at work that require a hero such as yourself." }
