WordHunterWoW_QuestEN[32894] = { title = "LFGDungeons - Mists - Scenario - Heroic Random - Nth Bonus", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[32895] = { title = "The Road to War", description = "Hey! I just received word from our agents in Durotar.\n\nThe Darkspear Rebellion needs your help.\n\nI hear you've already got an in with the trolls. Why don't you zip over to Durotar and see what's happening?", objectives = "Speak to Ki'ta Arrowtusk at Razor Hill in Durotar.", completion = "It be good to see dat some Alliance have a sense of loyalty." }
WordHunterWoW_QuestEN[32896] = { title = "The Road to War", description = "I have received word from Baine. The Darkspear Rebellion needs your help.\n\nGo to Razor Hill and seek out Ki'ta Arrowtusk.\n\nBreathe word of this to no one!", objectives = "Speak to Ki'ta Arrowtusk at Razor Hill in Durotar.", completion = "Ah, it be good to see your face again, <name>." }
