WordHunterWoW_QuestEN[32900] = { title = "Heroic Deeds", description = "My mind is spinning with boredom - I never get to leave this place!\n\nYou look like you've seen some adventures.  If you can bring me a truly heroic story, I've got something special I'm sure you'll be interested in.", objectives = "Complete any scenario on Heroic difficulty.", progress = "Anything to tell me, <name>?", completion = "Congratulations, <name>, you did it!  Before I forget, here's the special surprise I promised -- I hope you like it.\n\nNow tell me all about the adventure.  Did you face certain death?  Meet any friends?  I wish I had more friends like you." }
WordHunterWoW_QuestEN[32901] = { title = "Heroic Deeds", description = "My mind is spinning with boredom - I never get to leave this place!\n\nYou look like you've seen some adventures.  If you can bring me a truly heroic story, I've got something special I'm sure you'll be interested in.", objectives = "Complete any scenario on Heroic difficulty.", progress = "Anything to tell me, <name>?", completion = "Congratulations, <name>, you did it!  Before I forget, here's the special surprise I promised -- I hope you like it.\n\nNow tell me all about the adventure.  Did you face certain death?  Meet any friends?  I wish I had more friends like you." }
WordHunterWoW_QuestEN[32910] = { title = "reuse me", description = "There's more you must do. \n\nKill Itoka, master of the forge, and find a codex fragment from Fleshcrafter Hoku, gatekeeper of the Thunder King.You will receive:", objectives = "Kill the Master of the Forge and Collect a Codex Fragment from the Mogu Gatekeeper in the Isle of Thunder." }
