WordHunterWoW_QuestEN[32929] = { title = "They Rely on Numbers", description = "Thunderlord spend their days training to hunt as a team, but as individuals they are weak. Their only strength is in numbers.\n\nSo... to win, we must cull their numbers.\n\nAs we move up through the Daggermaw Ravine, slay any Thunderlord who stand in your way, and their clan will be made the weaker for it.", objectives = "Slay 15 Thunderlord at Daggermaw Ravine in Frostfire Ridge.", progress = "My axe bears the blood of a dozen Thunderlord. How many have you slain this day?", completion = "A fine headcount, commander." }
