WordHunterWoW_QuestEN[32942] = { title = "Work Order: Sunreaver Onslaught I", description = "<Yoon keeps the details of this order short, but detailed.>\n\nAnother request has come through for the Horde. The Sunreaver Onslaught, located out on the Isle of Thunder, has requested a bushel of scallions.\n\nThough this Horde and Alliance conflict still gets my fur in a bristle, I won't turn away a hungry stomach.", objectives = "Plant 8 Scallion Seeds on Sunsong Ranch." }
WordHunterWoW_QuestEN[32943] = { title = "Work Order: Sunreaver Onslaught II", description = "Once your scallions are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your scallions will feed so many hungry soldiers on the front lines!", objectives = "Harvest 8 Ripe Scallion plants and provide 40 Scallions for the Sunreaver Onslaught.", progress = "The crate sits empty awaiting your crops.", completion = "Throw the scallions into the crate! A Sunreaver Onslaught representative will be along shortly for pick-up." }
WordHunterWoW_QuestEN[32944] = { title = "Work Order: Kirin Tor Offensive I", description = "<Yoon keeps the details of this order short, but detailed.>\n\nAnother request has come through for the Alliance. The Kirin Tor Offensive, located out on the Isle of Thunder, has requested a bushel of juicycrunch carrots.\n\nThough this Horde and Alliance conflict still gets my fur in a bristle, I won't turn away a hungry stomach.", objectives = "Plant 8 Juicycrunch Carrot Seeds on Sunsong Ranch." }
WordHunterWoW_QuestEN[32945] = { title = "Work Order: Kirin Tor Offensive II", description = "Once your juicycrunch carrots are ready to be picked, you'll need only to package them for pick-up.\n\nJust think; your juicycrunch carrots will feed so many hungry soldiers on the front lines!", objectives = "Harvest 8 Ripe Juicycrunch Carrot plants and provide 40 Juicycrunch Carrots for the Kirin Tor Offensive.", progress = "The crate sits empty awaiting your crops.", completion = "Throw the juicycrunch carrots into the crate! A Kirin Tor Offensive representative will be along shortly for pick-up." }
