WordHunterWoW_QuestEN[32974] = { title = "Rolo's Riddle", description = "<The leather vellum is very old. Stained by age, it bears the following letters:>\n\nOn the isle of time are tall men four\nRound and strong and nothing more\nOf these brothers the shortest be\nWhere the trail leads to me.", objectives = "Solve the riddle.", completion = "<The dirt here looks overturned. Perhaps something is buried beneath.>" }
WordHunterWoW_QuestEN[32975] = { title = "Rolo's Riddle", description = "<Another dirty scrap of parchment is buried beneath the soil.>\n\nSomewhere hope stands, wings held forth\nFrom its feet turn to the north\nPass beyond an ancient gate\nBehind a stone pair, I await.", objectives = "Solve the riddle.", completion = "<Another pile of dirt! Could there be something buried here?>" }
WordHunterWoW_QuestEN[32976] = { title = "Rolo's Riddle", description = "The final step, my treasure calls\nAbove the place where water falls\nBeneath the shade on vantage high\nNo path to walk but air and sky.", objectives = "Solve the riddle.", completion = "<The ancient chest has not been disturbed for a long time.>" }
WordHunterWoW_QuestEN[32979] = { title = "Garrison Campaign: Farseer's Rock", description = "Draka and Drek'Thar are travelling to Farseer's Rock. It is a sacred place, not a safe one. But Draka insists that Drek'Thar must rebuild his connection to the elements.\n\nI can feel the spirits of this land are becoming restless. Something is about to happen, and I suspect these two will need all the help they can get.\n\nPlease, {name}, go to them and lend what aid you can. I care for these two a great deal.", objectives = "Find Draka and Drek'Thar at Farseer's Rock in Frostfire Ridge.", completion = "You again? Not eaten by ogres or killed by Thunderlords yet? Ha!" }
WordHunterWoW_QuestEN[32980] = { title = "Eaters of the Elements", description = "Drek'Thar has already begun his ritual, and it is powerful enough to draw the attention of the local goren. Those beasts are drawn to elemental magic like flies to a corpse.\n\nI will have my hands full soon enough. Help us if you like but Drek'Thar must be allowed to finish his ritual.", objectives = "Defend Drek'Thar as he performs his ritual.", completion = "I came seeking aid from the elements. I see now that we are the ones who must aid them.\n\nCome, <name>, witness what I have witnessed." }
WordHunterWoW_QuestEN[32981] = { title = "Only the Winner", description = "I am Gronnstalker Rokash, and I only serve the winning side.\n\nI have heard of some of your deeds, commander, and seen the corpses left in the wake of you and your forces.\n\nI have grown tired of my current clan. They are soft, weak, and losing.\n\nI offer you this challenge: enter Colossal's Fall to the north and slay Sky-Singer Strag. Claim her totem as a trophy and I will hail you as my new chieftain.", objectives = "Collect Sky-Singer Strag's Totem.", progress = "Strag always was a coward. She would hide behind her magic and position as a speaker for the dead.", completion = "Strag was the puppet of the Iron Wolf. She would do nothing unless ordered to by him.\n\nThis made us weak, changing us from a force to be feared to a target.\n\nIf this is what the Thunderlord have become then I will have no part of them." }
WordHunterWoW_QuestEN[32982] = { title = "Scavengers of Flame", description = "I sense another child of the fury being consumed by the vile goren in a nearby nest.\n\nSearch the caves east of here for any signs of a goren nest. I suspect there will be quite alot of steam given the cold.\n\nI will try to locate the next child of the fury in your absence.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Rescue the Child of Fury at the Forge Gates." }
WordHunterWoW_QuestEN[32983] = { title = "In the Shadow of Giants", description = "The goren and the magnaron are ravaging the element spirits and smelting their essence as one would smelt steel.\n\nCommander, take my totem, travel east to Magnarok. Please, find them, and free them.\n\nDraka and I will make our way to the Ascent of Frostfire. Meet us there if you are successful.", objectives = "Rescue Flamrog and Kindler.", progress = "The ritual was more draining than I could have anticipated.", completion = "You have done well, <class>.\n\nWe will need the aid of these children when the time comes to rescue Exurotus." }
WordHunterWoW_QuestEN[32984] = { title = "The Ascent", description = "I can feel the voice of the Fury at the top of the ascent. Come, let us climb these stairs together.\n\nBe on your guard. The goren of this area are likely to be drawn by the smell of a shaman.\n\nIf we get separated, fall back to the base of the stairs and regroup.", objectives = "Bring Drek'Thar to Exurotus, the Spirit of Frostfire.", completion = "This is ancient magic, from a time before the orcs. It will not be easy to undo." }
WordHunterWoW_QuestEN[32985] = { title = "Fury of Frostfire", description = "The moment I begin the ritual to free Exurotus you can expect Kron to be drawn to us. \n\nIt would normally take an army of seasoned warriors to defeat a magnaron. We have only the three of us.\n\nLook for my fire totem upon the battlefield. I will try to gain what boons I can from Exurotus. Step near the totems and become one with the Fury.\n\nWith these boons, slay Kron! Lok'tar ogar!", objectives = "Defeat Kron.", progress = "The... Fury... is nearly free!", completion = "With Kron defeated I can finish breaching the magic that holds Exurotus, but I may be too late. So much of the fury has already been expended and drained by the magnaron and goren.\n\nI fear we may have only bought this spirit a peaceful death." }
WordHunterWoW_QuestEN[32989] = { title = "Securing the South", description = "We have an outpost to the southeast that was boxed in by Thunderlord forces as they marched through the canyons to Wor'gol.\n\nI have sent reinforcements to secure the outpost and press east to Grom'gar. We will push the Thunderlords out of our lands completely, and pursue them all the way back to that reeking corpse they call home.\n\nDraka's sister, Lokra, was among the orcs who volunteered to clean up Stonefang Outpost.", objectives = "Speak with Lokra at Stonefang Outpost.", completion = "<name>! They told me you'd be heading this way. You are late to the party! We are just cleaning up now." }
WordHunterWoW_QuestEN[32990] = { title = "They Who Held Fast", description = "The siege has been broken - they underestimated the resilience of Stonefang, and our reinforcement wave from Bladespire caught them completely off-guard.\n\nOnce we finish cleaning up here, we rally anyone who can still fight and prepare to march for Grom'gar.\n\nThe outpost captain, Karg Bloodfury, should have come out to meet us by now. Can you get him out here?\n\nTell him Lokra is waiting. He knows how much I hate to be kept waiting.", objectives = "Speak with Karg Bloodfury in Stonefang Outpost.", progress = "You go ahead - Asha and I will hold here for now.", completion = "You're back! But where is Karg?" }
WordHunterWoW_QuestEN[32991] = { title = "Into the Boneslag", description = "The Thunderlords took prisoners into the Boneslag?\n\nWell what are we waiting for?! We have to go after them!\n\nYou look for the missing villagers - Asha and I will track Karg.", objectives = "Search the Boneslag for the missing Frostwolf orcs.", completion = "Thank you for finding the others. Karg and his captor are one step ahead of us, but they're limping." }
WordHunterWoW_QuestEN[32992] = { title = "Moving Target", description = "Karg's captors are moving east - probably retreating to Grom'gar with their tails between their legs!\n\nThey think they outrun me, but Asha here is the fastest thing on four legs. We'll run them down in the Icewind Drifts.", objectives = "Catch up with Lokra in the Icewind Drifts.", completion = "<Lokra's gaze remains fixed on her dying frost wolf.>\n\nWe had them... We had them, Asha. You were so fast. So beautiful.\n\nI failed you, Asha. I am sorry." }
WordHunterWoW_QuestEN[32993] = { title = "The Strength of Our Bonds", description = "Asha has passed, but we share a bond that cannot be severed by death. Even now, her spirit urges me onward to Grom'gar.\n\nThe Iron Wolf claims our attachments make us weak... that love makes us vulnerable.\n\nHe is wrong.\n\nKarg is my strength, and I his. I will free him from his chains, and together we will show the Thunderlord clan the strength of our bonds.", objectives = "Find Karg Bloodfury in Grom'gar.", completion = "Help me out of these chains. We have work to do." }
WordHunterWoW_QuestEN[32994] = { title = "Enfilade", description = "If we leave now, my clan's final assault on Grom'gar will be a disaster.\n\nThough our warriors are unmatched in melee, the Thunderlords have new ranged weapons - our forces would be decimated as they cross the Icewind Drifts.\n\nBut WE are already here. We can overtake those weapons before they ever fire.\n\nBlackrock orcs help our enemies forge these \"cannons\" in the workshops on the south side. If we use their own tools to sabotage the weapons, we leave Grom'gar wide open to a Frostwolf raid.", objectives = "Use Blackrock Blasting Powder to destroy 5 Iron Horde Cannons in Grom'gar.", progress = "If we leave those cannons intact, my brothers and sisters will die. What more is there to say?", completion = "See how their machines fail them! There is no better weapon than pure orc muscle!" }
WordHunterWoW_QuestEN[32995] = { title = "A Blood-Caked Scroll", description = "[TEMP TEXT] This scroll looks very old. Beneath dust and darkened smudges of blood, you can make out a few passages discussing \"mastery of weapons\".\n\nThis could be valuable in your training.\n\nPerhaps there is an expert warrior somewhere who could tell you more about this scroll.You will receive:", objectives = "[TEMP TEXT] Bring the Armsmaster's Scroll to Gauros Earthshatter in Orgrimmars's Brawl'gar Arena." }
WordHunterWoW_QuestEN[32996] = { title = "Battle-Hardened Relics", description = "[TEMP TEXT] I've heard your name, <name>. Many times. You are, and long have been, one of the Horde's more accomplished warriors.\n\nStill, you and I are strangers, and I need to know how capable you are before I can help you with your scroll.\n\nThe xxx have recently uncovered xxx. Prove yourself by bringing back spoils from these dungeons.You will receive:", objectives = "[TEMP TEXT] Obtain 100 Battle-Hardened Relics from the bosses of xxx." }
WordHunterWoW_QuestEN[32997] = { title = "Tracking Quest - First - Zesqua", description = "", objectives = "" }
WordHunterWoW_QuestEN[33000] = { title = "Saurfang, Warrior", description = "[TEMP TEXT] Any warrior worth mentioning is equal parts strength and leadership: strength to defeat one's foes, and leadership to rally one's allies. The warrior who you are about to meet has no shortage of either of these qualities.\n\nHigh Overlord Saurfang awaits in Razor Hill. A long time ago, he taught me much of what I know. He can assist you with this scroll.\n\nI have already sent word. Saurfang awaits your arrival, <name>.You will receive:", objectives = "Report to High Overlord Saurfang at Razor Hill in Durotar.[TEMP TEXT] Any warrior worth mentioning is equal parts strength and leadership: strength to defeat one's foes, and leadership to rally one's allies. The warrior who you are about to meet has no shortage of either of these qualities.\n\nHigh Overlord Saurfang awaits in Razor Hill. A long time ago, he taught me much of what I know. He can assist you with this scroll.\n\nI have already sent word. Saurfang awaits your arrival, <name>.You will receive:" }
WordHunterWoW_QuestEN[33001] = { title = "The Armsmasters", description = "[TEMP TEXT] This scroll outlines the Technique of the Armsmaster - a technique which I haven't seen used in years. I can fill in the blanks in the scroll for you, but without experience, this scroll is nothing but words on paper.\n\nI have met many enemies in my day, but a few stood out as true masters of their weapons. These armsmasters died long ago, but with the assistance of the xxx, you can fight them too.You will receive:", objectives = "[TEMP TEXT]" }
WordHunterWoW_QuestEN[33002] = { title = "Scribe Wei Wu", description = "[TEMP TEXT] I've taken what I know and filled in the blank and illegible pieces of your scroll, <name>. But I'm no scribe, and a document like this needs to be recorded and archived.\n\nThe scribes of Pandaria make a point to archive ancient texts like yours. Bring it to the scribe in the Seat of Knowledge.\n\nFarewell, warrior.You will receive:", objectives = "[TEMP TEXT] Speak with Scribe Wei Wu at the Seat of Knowledge in the Vale of Eternal Blossoms.[TEMP TEXT] I've taken what I know and filled in the blank and illegible pieces of your scroll, <name>. But I'm no scribe, and a document like this needs to be recorded and archived.\n\nThe scribes of Pandaria make a point to archive ancient texts like yours. Bring it to the scribe in the Seat of Knowledge.\n\nFarewell, warrior.You will receive:" }
WordHunterWoW_QuestEN[33003] = { title = "Glyph of the Armsmaster", description = "[TEMP TEXT] I understand - you need this scroll properly inscribed. I have the vellum, but a text like this deserves bold colors: colors which come at a cost. Standard inks will not do.\n\nThere are beasts here in the Vale... beasts of legend which carry the colors I need. I can show you where to find them.You will receive:", objectives = "[TEMP TEXT] Obtain the Crimson Blood of Oban Oju, the Jet-Black Ichor of Kak'charrik, and the Azure Blood of Sparky." }
WordHunterWoW_QuestEN[33007] = { title = "Proving Grounds", description = "[TEMP TEXT] Gauros may have tested you, but I think you're capable of more, <name>. I know what warriors like you have been through, and a few missions out in the field are really all in a day's work.\n\nYour true trial will take place in [PROVING GROUNDS TOWN]. Speak with [PROVING GROUNDS JIM] at [PROVING GROUNDS TOWN], and defeat one of his trials.You will receive:", objectives = "[TEMP TEXT] Complete a [PROVING GROUNDS TRIAL]." }
WordHunterWoW_QuestEN[33008] = { title = "Into the Vale", description = "Ah, I have been waiting for your arrival, traveler.\n\nI wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire.\n\nBut let us not speak of that now. Go visit Madam Vee Luo at the Shrine of Two Moons.\n\nShe should be able to settle you in.", objectives = "Speak to Madam Vee Luo at the Shrine of Two Moons in the Vale of Eternal Blossoms.Ah, I have been waiting for your arrival, traveler.\n\nI wish we could meet in better times, but alas, I fear the situation in the Vale is quite dire.\n\nBut let us not speak of that now. Go visit Madam Vee Luo at the Shrine of Two Moons.\n\nShe should be able to settle you in.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33010] = { title = "The Iron Wolf", description = "My brother Ga'nar stands beside me.\n\nWor'gol, Stonefang, and your garrison hold strong.\n\nOur clan is united, and the Thunderlord are already on the run. We are ready. The time has come to face this \"Iron Wolf.\"", objectives = "Enter the Hunter's Hall in Grom'gar and defeat the Iron Wolf.", completion = "Thank you for protecting my family, <name>." }
WordHunterWoW_QuestEN[33011] = { title = "Vignette: Frostwolf Veteran's Keepsake", description = "", objectives = "" }
WordHunterWoW_QuestEN[33012] = { title = "Task: Stonefang Outpost Fires", description = "", objectives = "Pick up snowballs from Snow Mounds and throw them at burning structures in Stonefang Outpost." }
WordHunterWoW_QuestEN[33013] = { title = "Of Fire and Thunder", description = "The Iron Wolf... brought weapons...\n\n<cough>\n\n...weapons of fire and thunder.\n\nOur warriors have never seen such weapons. We were not ready.\n\n<wheeze> We must learn... to overcome...", objectives = "Examine the Siege Munitions and Heavy Plating in The Boneslag." }
WordHunterWoW_QuestEN[33014] = { title = "Vignette: Cindermaw", description = "", objectives = "" }
WordHunterWoW_QuestEN[33015] = { title = "Thunderlord War-Gronn", description = "", objectives = "Slay 6 Thunderlord Giantslayers or Thunderlord Gronnstalkers around Kron'mar." }
WordHunterWoW_QuestEN[33016] = { title = "Treasure: Frostwolf Supply Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[33017] = { title = "Treasure: Iron Horde Supply Wagon", description = "", objectives = "" }
WordHunterWoW_QuestEN[33018] = { title = "Noodle Secrets Long Forgotten", description = "Searching amidst the rubble, you find the fragment of an old sign. Wiping away the dust, you can make out the well-weathered pandaren characters for \"Noodles\" and \"Lin.\"\n\nLooking above, you suspect that the establishment this sign belonged to was situated on the bridge, which now lies in rubble about you. An eatery placed on a bridge sounds very temporary, so its owner would likely live nearby.\n\nPerhaps there is a clue to be found in the village here on the island?", objectives = "Search the village, Old Pi'jiu, on the Timeless Isle, for the owner of the old sign fragment.", completion = "Well, hello there. I am Lin Chao-Wei.\n\nHave you come here to try my family's famous noodle soup?" }
WordHunterWoW_QuestEN[33019] = { title = "NC S1 Q2", description = "Well hello there. I am Lin, Chao-Wei. Have you come here to try my family's famous noodle soup? I'm afraid you're all out of luck. My father passed away before he could teach me the secret ingredient to his secret ingredient noodle soup. He did mention writing down the recipe for a friend of his that went to the Temple of the Jade Serpent. Perhaps you can find it there?", objectives = "Well hello there. I am Lin, Chao-Wei. Have you come here to try my family's famous noodle soup? I'm afraid you're all out of luck. My father passed away before he could teach me the secret ingredient to his secret ingredient noodle soup. He did mention writing down the recipe for a friend of his that went to the Temple of the Jade Serpent. Perhaps you can find it there?" }
WordHunterWoW_QuestEN[33020] = { title = "The Lost Secret of the Secret Ingredient", description = "If you've come here to try my family's famous noodle soup, I'm afraid you're out of luck.\n\nMy father passed away before he could teach me the secret ingredient. He did mention writing down the recipe for a friend of his that studied at the Temple of the Jade Serpent.\n\nPerhaps you can find it there?", objectives = "Defeat the Sha of Doubt.", completion = "You recognize the name, Lin, on the scroll. A few characters down you see the character for \"Recipe.\"\n\nThis must be it!\n\nYour only worry is that the sha energies that manifested themselves in the tales of the pandaren may have corrupted the scroll as well.\n\nThere is only one way to find out...." }
WordHunterWoW_QuestEN[33021] = { title = "Secrets Lost, Forever?", description = "<With the ancient Lin family noodle soup recipe in hand, you decide to set out for the Halfhill Market.>\n\n<If anyone in Pandaria knows how to decipher this scroll, it's Sungshin Ironpaw.>", objectives = "Speak with Sungshin Ironpaw at the Halfhill Market in the Valley of the Four Winds.", completion = "Hello, <name>. What is it you have there?" }
WordHunterWoW_QuestEN[33022] = { title = "Catch and Carry", description = "Oh my! Grandpa used to tell me stories of the famous Lin family noodle shop.\n\nIt is sad that the scroll has been warped, but I think we can work together to solve the riddle!\n\nTo start, we're going to need lots of grain to make noodles.\n\nHead down to the granary and catch some grain with this sack. After you've caught some, drop it off at the wagon I've placed at the granary.", objectives = "Use the Grain Catching Sack to catch 20 Sacks of Grain being thrown down by the Granary Vandals at the Imperial Granary.\n\nYou will drop all your carried grain if you mount or get hurt.", completion = "Excellent work, <name>! With all this grain I think we're ready to start.\n\nFor now I think you should try making noodle soup. Try using this recipe I've written down for you. It'll make for excellent practice." }
WordHunterWoW_QuestEN[33023] = { title = "NC S1 Q6", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33024] = { title = "Is That A Real Measurement?", description = "Well done, {name}. I can see you're ready to continue exploring the mysteries of Lin's secret ingredient soup.\n\nFrom what I can tell, Lin used Stormstout brew for his soup broth.\n\nI think the next steps for you are to create a Noodle Cart of your own and to head to the Stormstout Brewery to collect some sloshes of brew.", objectives = "Create a Noodle Cart Kit and collect 20 Sloshes of Brew from slain alementals in the Stormstout Brewery.", progress = "I'm glad it's you and not me. I'm not much of a drinker, myself.", completion = "Well done, <name>. With this we can make a truly unique soup broth.\n\nI've managed to get some updated schematics for your noodle cart. With this broth, you're definitely going to want to upgrade your operation.\n\nNext up: finding the secret ingredient of the Lin secret ingredient noodle soup!" }
WordHunterWoW_QuestEN[33025] = { title = "NC S2 Q2", description = "", objectives = "" }
WordHunterWoW_QuestEN[33026] = { title = "These Aren't Your Fatty Goatsteaks", description = "I'm so excited, {name}. We've nearly mastered all the ingredients for noodle soup!\n\nWe have plenty of vegetables and spices here, but the Lin family had access to exotic meats not seen in Pandaria for some time. We need some nice, fatty meats.\n\nGrandpa used to tell me of ancient turtles living off the shores of the Timeless Isle. Something that lives that long has to have some nice fatty meat on its bones.\n\nCreate a deluxe noodle cart and gather some fatty turtle steaks and we'll continue.", objectives = "Create a Deluxe Noodle Cart Kit and collect 50 Fatty Turtle Steaks.", progress = "I can just taste the soup now!", completion = "Ooh, these will do nicely, <name>.\n\nNow for the final step: the Lin secret ingredient soup's secret ingredient.\n\nThat's a mouthful!" }
WordHunterWoW_QuestEN[33027] = { title = "The Secret Ingredient Is...", description = "The best way to go about doing this is through hands-on experience.\n\nI've arranged for merchants, scholars, and farmers from all over Pandaria to come for a taste test of your soups. We'll get the best results if you can match them to the soups they prefer.\n\nIt's time to find the secret ingredient!", objectives = "Queue for and complete the Finding the Secret Ingredient scenario.", progress = "<name>, we need to find the secret ingredient if we're to ever master the Lin family's noodle soup!", completion = "Well done, <name>. All those people came by to taste your noodle soup and YOU made them so happy!\n\nDon't you see? The secret ingredient is in you!\n\nNow go out there and make the world happy with this latest noodle cart!" }
WordHunterWoW_QuestEN[33028] = { title = "To Karabor!", description = "Draenor will not be a friendly place for someone like you. There are far too many orcs here, and I know your kind has a history with the orcs.\n\nNo, if you're looking for a friendly face here on Draenor, you'll need to find the draenei.\n\nHop on my back. I will take you to the draenei temple of Karabor.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Chronalis, then fly into Karabor." }
