WordHunterWoW_QuestEN[33045] = { title = "Vignette: Foreling Circle Ritual", description = "", objectives = "" }
WordHunterWoW_QuestEN[33046] = { title = "Treasure: Beloved's Offering", description = "", objectives = "" }
WordHunterWoW_QuestEN[33047] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[33051] = { title = "Vignette: Prophecy of Jerrikar", description = "", objectives = "" }
WordHunterWoW_QuestEN[33052] = { title = "Vignette: Prophecy of Kraator", description = "", objectives = "" }
WordHunterWoW_QuestEN[33053] = { title = "Vignette: Prophecy of the Warp-Watcher", description = "", objectives = "" }
WordHunterWoW_QuestEN[33055] = { title = "Vignette: Foreling Worship Circle", description = "", objectives = "" }
WordHunterWoW_QuestEN[33056] = { title = "Vignette: Hygrocybe", description = "", objectives = "" }
WordHunterWoW_QuestEN[33057] = { title = "Vignette: Rotbelcher", description = "", objectives = "" }
WordHunterWoW_QuestEN[33058] = { title = "Collect Karabor Axes", description = "Some of our bravest champions have fallen today.\n\nTo make matters worse the Iron Horde has started using our own weapons against us. \n\nThe idea of my people being slain with the weapons forged by our ancestors makes me sick.\n\n<name>, could you please retrieve these weapons and bring them back to me?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 5 Karabor Weapons." }
WordHunterWoW_QuestEN[33059] = { title = "The Fate of Karabor", description = "Threads of the future weave together, winding and unwinding, creating tapestries that change in form and color from one moment to the next.\n\nI must have clarity. I must focus on the ONE strand that will become reality.\n\nWhen you are ready to share in my vision, drink the elixir.\n\nWhen the vision begins, be on your guard. The events of the vision are as deadly as anything we experience in this reality.", objectives = "Drink the Clarity Elixir and witness the fate of Karabor.", progress = "<The Prophet is deep in thought. He looks troubled.>", completion = "I have seen enough. Ner'zhul must be stopped." }
WordHunterWoW_QuestEN[33060] = { title = "Put down Poisonfiend.", description = "Zugunk Poisonfiend is to blame for this madness.\n\nHe has contaminated this temple and it is time for his reign of terror to end.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Zugunk Poisonfiend" }
WordHunterWoW_QuestEN[33061] = { title = "Vignette: Amaukwa", description = "", objectives = "" }
WordHunterWoW_QuestEN[33062] = { title = "Catching His Eye", description = "For what must be done, I need someone I can trust. You're one of those few.\n\nThe woods and the orc village, Gul'var, are protected from my scrying magic. We need to pierce that veil. I think I know a way.\n\nThere's a fel presence within the woods. A demonic watcher is there, hidden in a cave from which it casts its all-seeing gaze.\n\nI would like for you and the warden to capture it.", objectives = "Capture the All-Seeing Eye.", completion = "As soon as we have enough blessed water from the priestess's moonwell, we'll break the demon's will and use it as a proxy to see into Gul'var.\n\nThat way, they won't know it's us scrying upon them.\n\nBut first, we need to weaken their shrouding magic." }
WordHunterWoW_QuestEN[33064] = { title = "Vignette: Shadowmoon Cultist Ritual", description = "", objectives = "" }
WordHunterWoW_QuestEN[33065] = { title = "Vignette: Mooncrush", description = "", objectives = "" }
WordHunterWoW_QuestEN[33066] = { title = "Soul Shards of Summoning", description = "It's good to know what Teron'gor and Cho'gall are up to. It's more important that we stop Gul'dan.\n\nSome of his disciples can summon minor demons. To do this, these lesser warlocks must use a soul shard. The foul crystal creates a connection to the Twisting Nether, pulling a demon through against its will.\n\nGul'dan's as much demon as he is orc. If we can gather some of the more potent shards, we can combine them into something that just might capture him.", objectives = "Collect Kurgoth's Shard, Grogal's Shard, and Hagra's Shard.", progress = "Do you have the shards, <name>?", completion = "Now all that's left to do is to fashion them together into something strong enough to ensnare Gul'dan.\n\nLuckily, we can do that right here." }
WordHunterWoW_QuestEN[33067] = { title = "Task: Warsong Riot", description = "The Warsong Ragemongers are attacking the temple!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Warsong Ragemongers near the Temple of Katabor in Shadowmoon Valley." }
WordHunterWoW_QuestEN[33068] = { title = "Task: Retrieve Thunderlord Armbands", description = "", objectives = "" }
WordHunterWoW_QuestEN[33069] = { title = "REUSEME", description = "", objectives = "" }
WordHunterWoW_QuestEN[33070] = { title = "Think of the Children!", description = "When the Shadowmoon attacked Arbor Glen, everything was thrown into chaos.\n\nMany of us escaped, but there are still three children missing.\n\nI believe they are still back in the village.\n\nPlease save them!", objectives = "Save Rastaak, Ariaana, and Hakaam.", completion = "I am glad to hear that the children are safe. They will remember your heroic deeds for their entire lives." }
WordHunterWoW_QuestEN[33071] = { title = "The Call of War", description = "If you are reading this letter, it likely means that I am dead. Please deliver this to my son, Faran, at Teluuna Observatory.\n\n\nDearest Faran and Elsa,\n\nI have fallen in the line of duty while defending the Temple of Karabor.\n\nPlease know that I love you both with all of my heart. My spirit will watch over you for the rest of your days. Be strong, love one another, and live this life to the best of your ability.\n\nI am so proud of you both.\n\nLove,\n\nYour MotherYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Deliver Kaati's Letter to Faran at Teluuna Observatory." }
WordHunterWoW_QuestEN[33072] = { title = "Into Twilight", description = "The safety of my people is of the utmost priority.\n\nIt is likely that Ner'zhul has taken the prisoners to Shaz'gul, his stronghold to the southwest.\n\nI do not wish to use aggression against him, but he may force my hand.\n\nMeet me at Twilight Glade, {name}. Then, we shall try our best to recover the prisoners.", objectives = "Speak to Prophet Velen at Twilight Glade.", completion = "Thank you for coming, <name>. There is much to be done." }
WordHunterWoW_QuestEN[33074] = { title = "The Memory of Fire", description = "<The obsidian chip is hot to the touch, but strangely, can be held with no fear of being burned.>\n\nOn its surface is etched a picture - a rectangular stone with a hole cut through the middle, surrounded by a ring of flames.\n\nThere is just such a stone in the fields to the north.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Use the Dancing Ember at the ring of fire." }
WordHunterWoW_QuestEN[33075] = { title = "A Hero's Welcome", description = "Prophet Velen has asked me to show you around Shadowmoon Valley.\n\nWe will go first to Embaari Village, where my sister Samaara is waiting for us. I have not seen her since the Iron Horde took me to Tanaan.\n\nThe village is just one of many trading villages between the Temple of Karabor and Shattrath.\n\nFollow the road east and make your way to Embaari Village. I will accompany you, my friend.", objectives = "Speak to Samaara at Embaari Village.", completion = "Thank you, stranger! The Prophet spoke of new allies arriving on our shores.\n\nI hear it is thanks to you that my sister is safe.\n\nI owe you a great debt, friend." }
WordHunterWoW_QuestEN[33076] = { title = "The Clarity Elixir", description = "I see a thousand glimpses of the future, swimming in a chaotic blur.\n\nIt is possible to focus my energies to see the true eventuality - the future most likely to come to pass.\n\nI will need an oracle stone to focus my power, and a special elixir to still my mind.\n\nTo make the elixir, I will need the following ingredients: wing dust from Swamplighters along the river, fresh hearts from a monstrously-sized hydra, and a rare star lily.\n\nMeet me at Moonwillow Peak when this task is done.", objectives = "Collect 6 Swamplighter Dust, 3 Engorged Hearts, and 1 Starflower.", progress = "Yes?", completion = "My trust in you is well placed, young <class>.\n\nThis task would have been troublesome for many of my students, and yet you finished it with ease." }
WordHunterWoW_QuestEN[33077] = { title = "A Grandmother's Remedy", description = "Oh my, such a vigorous young lad! Such a spring in your step, and such a sparkle in your eye!\n\nWhen you get to my age, it's all aches and pains.\n\nLuckily, I have a recipe for an unguent that would soothe my joints. I just need the ooze from the skin of belly toads in the swamp.\n\nWould you be a dear and help an old woman out?", objectives = "Collect 6 Vials of Toad Juice.", progress = "It's all downhill from here, dearie.", completion = "Oh thank you child, thank you, thank you.\n\nThe nights in the swamp are cold. It means a lot to this old woman to have some comfort from her aching bones." }
WordHunterWoW_QuestEN[33078] = { title = "The Dark that Blinds Us", description = "After years of research, there is still so much I do not understand about the Shadowmoon.\n\nTo the southwest are stone monuments detailing the orcs' history.\n\nI'm not able to get close enough to examine the stones, but perhaps you can.\n\nIf you could take a chalk rubbing of the words written on those stones, and I will reward you handsomely.", objectives = "Take chalk rubbings of the northern, eastern, western, and southern Tribal Stones in the Whispering Fields.", progress = "What did you find?", completion = "Oh my, I see, I see! These writings will give me much insight into the Shadowmoon clan's culture.\n\nThank you, <name>." }
WordHunterWoW_QuestEN[33079] = { title = "The Demons Among Us - Alliance", description = "Now that we have the cloth and leather, we can craft a fitting disguise for our infiltration mission.\n\nGo speak to Ginni Gingerlips. She has proven herself quite capable in the realm of... errr... garment design.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak to Ginni Gingerlips to craft a Shadowmoon orc disguise." }
WordHunterWoW_QuestEN[33080] = { title = "Going Undercover", description = "Yrel leads my rangers on a search for the prisoners at the Shadowmoon village.\n\nTheir work is extremely dangerous, so I need you to carry out a contingency mission.\n\nSylene has mastered an illusion spell which will allow you to infiltrate Shaz'gul safely. Speak to her to disguise yourself.\n\nThen, plant explosives at the quartermaster's depot, the main lodge, and the ritual altar.\n\nIn case anything goes wrong, set them off to create a distraction.", objectives = "Speak to Sylene at Twilight Glade to gain an orc illusion, then plant explosives at key locations in Shaz'gul.\n\nIf you lose your disguise, use Sylene's Amulet of Illusion to regain an orc appearance.", completion = "You made it, <name>! Boy, am I glad to see you." }
WordHunterWoW_QuestEN[33081] = { title = "Escape From Shaz'gul", description = "I've failed, {name}...\n\nMy squadron was caught by a wandering patrol. We fought fiercely, but the alarm had been raised. The rangari forced me into hiding before surrendering themselves to the enemy.\n\nThey were under MY command, and they gave their lives... for what? I... I'm not sure what to do, {name}.\n\nWe need to get out of here, but how?", objectives = "Help Yrel escape from Shaz'gul.", completion = "I could never have done it without you, <name>. Your words unlocked something within me which I have not felt before.\n\nCall it what you wish - resolve, conviction, faith. I will not soon forget this, <class>." }
WordHunterWoW_QuestEN[33082] = { title = "Ancestor's Memory", description = "I believe that you should know the price of the lives you take.\n\nSo before I will help you find Ner'zhul, you must understand why he joined the Iron Horde.\n\nIn a cave beneath this village is an artifact that we call the Ancestral Totem. On it is carved the names of every Shadowmoon clan member since its founding.\n\nThe opening of the cave lies directly south. I will meet you there.", objectives = "Find the Ancestor's Totem in the cave beneath Exile's Rise.", progress = "You must understand a man's life before taking it.", completion = "We will find new traditions. My people will become something... new." }
WordHunterWoW_QuestEN[33083] = { title = "On the Offensive", description = "We cannot enter these gates, but you can, {class}.\n\nYour mission is critical, and the Shadowmoon will kill you on sight. Do not hesitate to return the favor.", objectives = "Kill 15 Shadowmoon Darkcasters or Shadowmoon Voidclaws.", completion = "The Shadowmoon are not simple opponents. Your fighting skill is truly comparable to none." }
WordHunterWoW_QuestEN[33084] = { title = "The Big Haul", description = "Ey commander, fancy runnin' inta ya out here!\n\nTha garrison's got plenty a hungry mouths ta feed, with more folks comin' by every day.\n\nWe're really gonna need a big haul o' meat ta keep everyone happy.\n\nWouldya care ta lend us a hand? It'll be faster work with an extra pair a hands.", objectives = "Collect 1000 Raw Elekk Steaks.", progress = "Have ya seen tha size a these beasts?", completion = "Brilliant, just brilliant! Ay've never seen such a haul in my entire life!\n\nGet tha wagons ready. We're eatin' well tonight!" }
WordHunterWoW_QuestEN[33085] = { title = "Fallen From the Stars", description = "The final ingredient is a rare flower that grows only in the heart of the Nightmarsh.\n\nThis flower feeds only on starlight, and dies when it falls under shadow.\n\nIf you can find such a flower, bring it to me. Only its essence will help me gain the clarity I need.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 1 Pristine Starflower." }
WordHunterWoW_QuestEN[33086] = { title = "Tracking Quest: The Root of Darkness - Stone 1", description = "", objectives = "You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33087] = { title = "Meet Me Back at the Inn", description = "I'm certain you're eager to test out your new cloak. Let's put it to use.\n\nMeet me back inside the inn! A new development has come to my attention that we'll want to take advantage of.", objectives = "Meet Wrathion upstairs at the Tavern in the Mists in the Veiled Stair.", completion = "Are you ready for your next adventure?" }
WordHunterWoW_QuestEN[33088] = { title = "A Timeless Discovery", description = "Pandaria. Just when I think I've gotten its mysteries figured out, I discover something new.\n\nIt's called \"The Timeless Isle.\" Once hidden in the mists, it appears and disappears seemingly of its own will. I've heard that time has no meaning there, that the sun neither rises nor sets.\n\nWe can take advantage of this anomaly, {name}! If I could time-lock your cloak, the power it could contain would be... immense.\n\nOur path is clear. Fly southeast of the Jade Forest and meet me at the Timeless Isle!", objectives = "Travel to the Timeless Isle southeast of the Jade Forest and speak with Wrathion.", completion = "You're here! How long have I been waiting for you?\n\n<Wrathion appears momentarily confused.>\n\nI feel like I just arrived... but maybe I've been here for weeks... This island plays with one's head.\n\nKairoz has been trying to explain it to me, but sometimes I think bronze dragons speak in riddles." }
WordHunterWoW_QuestEN[33089] = { title = "FLAG - Proving Grounds - Damage Bronze", description = "", objectives = "" }
WordHunterWoW_QuestEN[33090] = { title = "FLAG - Proving Grounds - Damage Silver", description = "", objectives = "" }
WordHunterWoW_QuestEN[33091] = { title = "FLAG - Proving Grounds - Damage Gold", description = "", objectives = "" }
WordHunterWoW_QuestEN[33092] = { title = "FLAG - Proving Grounds - Tank Bronze", description = "", objectives = "" }
WordHunterWoW_QuestEN[33093] = { title = "FLAG - Proving Grounds - Tank Silver", description = "", objectives = "" }
WordHunterWoW_QuestEN[33094] = { title = "FLAG - Proving Grounds - Tank Gold", description = "", objectives = "" }
WordHunterWoW_QuestEN[33095] = { title = "FLAG - Proving Grounds - Healer Bronze", description = "", objectives = "" }
WordHunterWoW_QuestEN[33096] = { title = "FLAG - Proving Grounds - Healer Silver", description = "", objectives = "" }
WordHunterWoW_QuestEN[33097] = { title = "FLAG - Proving Grounds - Healer Gold", description = "", objectives = "" }
WordHunterWoW_QuestEN[33098] = { title = "Secrets of the Timeless Isle", description = "There is a currency minted only on this island - \"timeless coins.\" They are immune to the island's temporal distortions... I would like to figure out why.\n\nGather some for me! Venture into the jungles of this forgotten paradise. Destroy the mysterious foes who lurk in this timeless place, discover hidden caches of treasure, and explore forgotten treasure hoards - whatever it takes. I will be waiting!", objectives = "Collect 5000 Timeless Coins from creatures and events on the Timeless Isle.", progress = "<Wrathion tents his fingers together.>\n\nMy coins...?", completion = "Wonderful, these are exactly what I need.\n\n<Wrathion holds one of the coins up, admiring it in the glow of the unmoving sun.>\n\nI will deconstruct their mysterious power, and use their timelessness to enhance your cloak. You will be most pleased with the result." }
WordHunterWoW_QuestEN[33100] = { title = "The Emperor's Way", description = "Recently, the August Celestials of Pandaria presented you with a challenge - and you triumphed.\n\nBut can you defeat them in combat? They are testing the mettle of all of Pandaria's heroes.\n\nThis challenge is not impossible, but you'll need to follow the advice of the last Pandaren Emperor and tackle it with unwavering inner strength. You'll also need a small army, so find a group of people you trust.\n\nDefeat the four celestials here in the Celestial Court, and our journey is almost complete...", objectives = "Defeat Yu'lon, Chi-Ji, Xuen and Niuzao, the four August Celestials of Pandaria.", completion = "An impressive display of martial skill, <class>! You have truly walked the path of the emperor, and demonstrated the very traits pandaren value most." }
WordHunterWoW_QuestEN[33104] = { title = "A Pandaren Legend", description = "I have learned so much in this timeless place, friend. Between the wisdom of the celestials and the curious power of these timeless artifacts, I know now how to safely augment your cloak with my own considerable power.\n\nI need a sacred place to complete my final incantations. Quickly! Meet me in the Vale of Eternal Blossoms, within the Seat of Knowledge above the Mogu'shan Palace.\n\nToday, your legend begins!", objectives = "Meet Wrathion within the Seat of Knowledge in the Vale of Eternal Blossoms.", completion = "Step forward, my champion.\n\nThis is your hour." }
WordHunterWoW_QuestEN[33105] = { title = "Judgment of the Black Prince", description = "Now. To the final stage of my plan. Time to fulfil your grand purpose.\n\nUsing your newfound powers, it is time to bring this war to its conclusion. Destroy Garrosh Hellscream. Your people demand it, and future generations will sing your praises as the harbinger for the glorious new world we shall build together.\n\nI have no reward to offer you. I have already done everything in my power to ensure that you succeed. You are on your own.\n\nEnd Hellscream's reign.", objectives = "Complete the Siege of Orgrimmar and defeat Garrosh Hellscream.", completion = "<Wrathion is FURIOUS. News of Hellscream's defeat and King Wrynn's gesture of peace must've already reached the black dragon's ears.>" }
WordHunterWoW_QuestEN[33107] = { title = "Bad Feeling, Worse Result", description = "<As you open the scroll, you realize your worst fears have come true: the sha energies have corrupted the Lin recipe.>\n\n<Your only choice is to defeat the released energies in the hope that the scroll can be saved.>", objectives = "Defeat the Ghost of Lin Da-Gu." }
WordHunterWoW_QuestEN[33108] = { title = "Task: Poisionous bunnies", description = "A large number the bunnies in the area have been infected with a toxic poison.\n\nIt might seem cruel but burning the bodies of the bunnies is the only way to ensure the infection will not spread.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Burn 5 poisonous bunnies" }
WordHunterWoW_QuestEN[33109] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[33110] = { title = "The Usurper", description = "This fragment of the heart of Y'shaarj lies completely inert. You should bring it to the remnants of the Golden Lotus as proof that Garrosh has been defeated.You will receive:", objectives = "Claim your reward for deposing Garrosh Hellscream as Warchief of the Horde." }
WordHunterWoW_QuestEN[33111] = { title = "Bounty: Twisted Ancient", description = "The ancients of the Cursed Woods have been corrupted by demonic magic. Since they need to be destroyed, we might as well make use of their resources. Waste not, want not.\n\nBeware: these woodland behemoths are no easy targets. Gather trusted friends before you engage these twisted ancients.\n\n-- Baros Alexston", objectives = "Collect Corrupted Lumber from a Twisted Ancient.", progress = "Have you read the bounty I posted concerning the twisted ancients in the Cursed Woods?", completion = "Unfortunate that the ancient guardians of the woods fell to such corruption.\n\nAt least now, its long nightmare has ended. Not to mention its sacrifice is our gain." }
WordHunterWoW_QuestEN[33112] = { title = "Ominous Portents", description = "Now that Priestess Moonfang has created the blessed water, it is time to deal with the demon.\n\nTake the water and the scripture of Elune.\n\nThrough the power of each, you will compel the demon to show us what the orcs are up to at Gul'var.", objectives = "Compel the All-Seeing Eye.", progress = "The demon must be put to the test if we're to find out what's happening at Gul'var.", completion = "Gul'dan is there! We must move quickly to capture him." }
WordHunterWoW_QuestEN[33113] = { title = "Shadowmoonwell", description = "The archmage has asked me to prepare this moonwell. Once it is completed, I'll be able to sanctify its water for use against the demon.\n\nOnly one thing remains.\n\nA piece of one of Draenor's moons has fallen into a nearby pool on the far side of the woods. Such a thing is perfect for use in the dedication of the moonwell to Elune.\n\nWill you bring it back for me, {name}?", objectives = "Collect a Chunk of Lunar Rock.", progress = "With that chunk of fallen rock, I'll be able to complete the dedication of the moonwell.", completion = "Thank you, <name>. The White Lady will be pleased.\n\nNow, I shall go about the business of preparing the moonwell water for use in the archmage's plan.\n\nBut first, I wonder if you'd be willing to help me again. The warden brought back very disturbing stories about the creatures in the woods." }
WordHunterWoW_QuestEN[33114] = { title = "Forging the Soul Trap", description = "The fiery heart of Krosnis is in the forge. We have the soul shards.\n\nNow all that is left to do is to stoke the fires and combine all of these foul components into a trap for Gul'dan.", objectives = "Forge Gul'dan's Soul Trap.", progress = "With the soul shards combined, we will trap Gul'dan and put an end to the Shadow Council on Draenor.", completion = "You've forged the soul trap. There's no time to waste, <name>.\n\nWe must capture Gul'dan." }
WordHunterWoW_QuestEN[33115] = { title = "Shrouding Stones", description = "Long ago, the shaman of the Shadowmoon clan erected three stones in the woods. There, they performed their sacred rituals, blessing the beasts and the trees.\n\nNow, someone has placed a fel magic upon those stones. This corruption is what shrouds the village of Gul'var.\n\nBefore we can use the captured demon to safely peer into the Shadow Council's village, we must bring down those stones.", objectives = "Destroy the Central, Northern, and Southern Shrouding Stones.", completion = "Now that the veil has been lifted from the woods, we can make use of the demon.\n\nWe will convince it to turn its eye upon Gul'var and show us what the Shadow Council is planning." }
WordHunterWoW_QuestEN[33116] = { title = "To Catch a Shadow", description = "Gul'dan is on the Shadow Rise just up the hill to the west. But, you must hurry, {name}. We know that he's about to leave for Talador and Frostfire Ridge.\n\nThe use of the soul trap is straightforward. Simply point and shoot to ensnare Gul'dan. The crystal will take care of the rest.\n\nI'll see you back at Starfall Outpost when you have him.\n\nGood luck.", objectives = "Use Gul'dan's Soul Trap on Gul'dan.", completion = "Unfortunate, but not surprising. At least we were able to defeat one of the inner council members.\n\nAll is not lost, <name>. We know what the Shadow Council is up to and where they're heading.\n\nWe'll regroup in Talador. Together, we'll put an end to Teron'gor and his plans for Auchindoun.\n\nDid you hear that?" }
WordHunterWoW_QuestEN[33117] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[33118] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[33119] = { title = "Slavery and Strife", description = "We have their citadel, but they still have some of my people enslaved at the Sootstained Mines.\n\nWe have no one to spare, but you seem more than capable of handling a few ogres on your own.\n\nI ask that you release any enslaved Frostwolves you find there, and keep an eye out for Mulverick.", objectives = "Free 5 Frostwolf Slaves from the Sootstained Mining Camp.", progress = "Free my people and then we can talk!", completion = "Who are you, outsider? I saw you freeing some of my kin..." }
WordHunterWoW_QuestEN[33120] = { title = "A Curse Upon the Woods", description = "Cordana tells me that the creatures of the woods are cursed by the same fel energies keeping Khadgar from scrying into the orc village.\n\nThis will not do.\n\nIf we were on Azeroth, I could find a cure in a reasonable timeframe. However, we are not, nor do we have the luxury of time.\n\nBetter to put a swift end to their suffering rather than allow these poor creatures to linger with demonic energy.", objectives = "Kill 10 fel-cursed creatures in the Cursed Woods.", completion = "Grim business. I wish that it could have gone differently.\n\nThank you for your dedication, <name>. Be comforted in the fact that Elune understands." }
WordHunterWoW_QuestEN[33121] = { title = "DEPRECATED The Celestial Tournament", description = "Description.You will receive:", objectives = "Log description.Description.You will receive:" }
WordHunterWoW_QuestEN[33122] = { title = "DEPRECATED Great Job, You Won", description = "Description.You will receive:", objectives = "Log description.Description.You will receive:" }
WordHunterWoW_QuestEN[33123] = { title = "The Celestial Tournament", description = "The Timeless Isle is home to a special tournament created to test the leadership of its participants.  Those who prove their worth are granted an opportunity to befriend an embodiment of virtue - the progeny of the Celestials themselves.\n\nEach time you win the tournament, I will honor you with a single ceremonial coin.  When you have enough coins, speak with me again to further discuss your reward.You will receive:", objectives = "Win the Celestial Tournament. Master Li can enter you into the tournament." }
WordHunterWoW_QuestEN[33124] = { title = "Fishing with Fin - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[33125] = { title = "A Proper Parting", description = "The ogres outnumbered us, *cough* but we made them pay for their deeds in blood.\n\nEven so, I was forced to abandon my fallen brothers and sisters on the battlefield. They deserve better than to have their corpses despoiled by the ogre filth.\n\nHere, take this torch *cough* and do what I could not: burn the corpses of my fallen brothers and sisters to the west.", objectives = "Burn the corpses of dead Frostwolf Outriders.", progress = "Did you give the others a proper burial?", completion = "You bring honor to the clan by giving my family a proper burial, <name>." }
WordHunterWoW_QuestEN[33126] = { title = "Task: Clear Out Grimfrost Hill.", description = "Kill Grimfrost OgresYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill ogres on Grimfrost Hill" }
WordHunterWoW_QuestEN[33129] = { title = "Task: Poisionous bunnies", description = "A large number the bunnies in the area have been infected with a toxic poison.\n\nIt might seem cruel but burning the bodies of the bunnies is the only way to ensure the infection will not spread.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Burn 5 poisonous bunnies" }
WordHunterWoW_QuestEN[33130] = { title = "Task: Poisionous bunnies", description = "A large number the bunnies in the area have been infected with a toxic poison.\n\nIt might seem cruel but burning the bodies of the bunnies is the only way to ensure the infection will not spread.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Burn 5 poisonous bunnies" }
WordHunterWoW_QuestEN[33131] = { title = "Put down Poisonfiend.", description = "Zugunk Poisonfiend is to blame for this madness.\n\nHe has contaminated this temple and it is time for his reign of terror to end.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Zugunk Poisonfiend" }
WordHunterWoW_QuestEN[33132] = { title = "Gut Guttra", description = "Snowpaw was able to help me to here so that I might strike against their leader, Guttra, but I have lost too much blood. My time is near.\n\nDo you have the strength to help me avenge my fallen brothers and sisters and kill Guttra Wolfchew?\n\nThe monster resides in the tallest tower of Grimfrost.", objectives = "Slay Guttra Wolfchew.", progress = "Did you kill Guttra Wolfchew?", completion = "Wolfchew is defeated? *cough* Glorious." }
WordHunterWoW_QuestEN[33133] = { title = "Warforged Seals", description = "Greetings, <name>. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Warforged Seal, valuable artifacts will find their way into your hands more frequently as you pursue Garrosh.", objectives = "Collect 50 Lesser Charms of Good Fortune.", progress = "May these charms bring you great luck, <name>.", completion = "May the stars smile upon you, <name>." }
WordHunterWoW_QuestEN[33134] = { title = "Warforged Seals", description = "Greetings, <name>. I am privileged to offer you an excellent opportunity. Through the centuries, we've honed a method by which the very laws of chance themselves can be bent. With a Warforged Seal, valuable artifacts will find their way into your hands more frequently as you pursue Garrosh and his forces.", objectives = "Collect 50 Lesser Charms of Good Fortune.", progress = "May these charms bring you great luck, <name>.", completion = "May the stars smile upon you, <name>." }
WordHunterWoW_QuestEN[33135] = { title = "Cleaning Up Gul'var", description = "Just because we need to focus on Gul'dan doesn't mean we're not going to take down the Shadow Council in the process.\n\nThis village is filthy with Shadow Council villains. Let's do something about them.", objectives = "Kill 20 Shadow Council orcs at Gul'var.", completion = "Every world is better off without those demon-loving scum." }
WordHunterWoW_QuestEN[33136] = { title = "The Rainy Day is Here", description = "", objectives = "<name>, I can see the look in your eyes.  I have heard of your deeds in the tournament.  You are ready to choose a companion!\n\nThis one time I will gift you these two additional coins.  Use them wisely, as you will only be able to earn one coin each week from this point forward." }
WordHunterWoW_QuestEN[33137] = { title = "The Celestial Tournament", description = "The Timeless Isle is home to a special tournament created to test the leadership of its participants.  Those who prove their worth are granted an opportunity to befriend an embodiment of virtue - the progeny of the celestials themselves.\n\nEach time you win the tournament, I will honor you with a single ceremonial coin.  When you have enough coins, speak with me again to further discuss your reward.", objectives = "Speak with Master Li to enter the Celestial Tournament and defeat all the challengers there.", progress = "You must win the Celestial Tournament to receive your coin.", completion = "A true leader stands before me.  It is my honor to grant you this coin, <name>." }
WordHunterWoW_QuestEN[33138] = { title = "Why Do We Fight?", description = "Oh my friend, today you and your companions have put an end to the sha that has plagued Pandaria since before time was recorded. You have accomplished that which even the titans and their mogu servants could not: destroying the last breaths of Y'Shaarj.\n\nCome, will you join me in the Vale of Eternal Blossoms? There is something I would like you to bear witness to.", objectives = "Lorewalker Cho wishes to speak with you in the Vale of Eternal Blossoms.", completion = "Our precious Vale of Eternal Blossoms. So much destruction and violence. But... I sense a glimmer of hope." }
WordHunterWoW_QuestEN[33139] = { title = "Secrets Lost, Forever?", description = "<With the ancient Lin family noodle soup recipe in hand, you decide to set out for the Halfhill Market.>\n\n<If anyone in Pandaria knows how to decipher this scroll, it's Sungshin Ironpaw.>", objectives = "Speak with Sungshin Ironpaw at the Halfhill Market in the Valley of the Four Winds.<With the ancient Lin family noodle soup recipe in hand, you decide to set out for the Halfhill Market.>\n\n<If anyone in Pandaria knows how to decipher this scroll, it's Sungshin Ironpaw.>You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33145] = { title = "Grimfrost Hill", description = "Free the Frostwolves being held by the Grimfrost ogres.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "" }
WordHunterWoW_QuestEN[33146] = { title = "Noodle Time", description = "Hello, {name}. Care to work the noodle stand again?\n\nJust let me know when you're ready to work another shift and I'll get everything set up.", objectives = "Queue for and complete a shift at the Halfhill noodle stand.", completion = "Great work <name>! Everyone always loves it when they hear that you'll be making noodle soup. People come from all over Pandaria just to try a taste." }
WordHunterWoW_QuestEN[33147] = { title = "The Last Gasp of Y'Shaarj", description = "A dark, vaporous substance stains the floor of the room. This is all that remains of the Old God Y'Shaarj.", objectives = "Speak with Lorewalker Cho in the Siege of Orgrimmar.", completion = "Do you see? Even now it fades from being." }
WordHunterWoW_QuestEN[33148] = { title = "Missing Hunting Party", description = "xxxxxxxYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "xxxxxxx" }
WordHunterWoW_QuestEN[33149] = { title = "Blackrock Down", description = "Hey <name>, just the <race> I was hopin' to see. I just received a distress call from Thaelin.\n\nHe and Romuul left a while ago to do some reconnaissance on another one of those draenei crystals, but now it sounds like they're in wee a spot o' trouble.\n\nKnowing Thaelin, he's going to need some help.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Locate Thaelin Darkanvil outside of Gar'mak Quarry.Hey <name>, just the <race> I was hopin' to see. I just received a distress call from Thaelin.\n\nHe and Romuul left a while ago to do some reconnaissance on another one of those draenei crystals, but now it sounds like they're in wee a spot o' trouble.\n\nKnowing Thaelin, he's going to need some help.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33150] = { title = "Brute Beatdown", description = "This Iron Horde has no honor.\n\nTheir leaders spit on us and laugh as we do their bidding.\n\nMany of my brothers and sisters have died at their hands.\n\nIt is time to send these savages to an early grave.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Mokrik Blackfingers, Rukah the Machinist, and Gar Steelcrush." }
WordHunterWoW_QuestEN[33151] = { title = "Tracking Quest: Saw Scout Valdez Arrive", description = "", objectives = "" }
WordHunterWoW_QuestEN[33154] = { title = "Fight for Freedom", description = "The Iron Horde keeps us here against our will. They control us with fear and aggression.\n\nIt pains me to see my people subjugated like this.\n\nAll we need to stand up to these beasts is hope... and a large weapon.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Give weapons to Enslaved Draenei and kill Iron Horde orcs." }
WordHunterWoW_QuestEN[33155] = { title = "Task: Destroy Iron Horde Banners", description = "", objectives = "" }
WordHunterWoW_QuestEN[33156] = { title = "Time Keeper Kairoz", description = "You have found your way to the Timeless Isle, {class}. The bronze dragonflight is keen to investigate the mysteries of this place, but the island is dangerous, and we will need your help.\n\nMidway down this beach, you will find a paved path to the east.\n\nIt will lead you to the ancient Celestial Court. You will find Kairoz there, one of the Keepers of Time that we are working with.\n\nKairoz will answer any questions you might have. Be careful: The way may not be safe.", objectives = "Speak with Kairoz on the Timeless Isle.", completion = "Ah! Well met, <name>!\n\nI was told you would be coming, but had not expected you so soon.\n\n...or has it been a long while? It is difficult to tell, here.\n\nSo! Shall we begin?" }
WordHunterWoW_QuestEN[33157] = { title = "Shadowmoon Phased Terrain Swap 1", description = "", objectives = "" }
WordHunterWoW_QuestEN[33158] = { title = "Shadowmoon Phased Terrain Swap 2", description = "", objectives = "" }
