WordHunterWoW_QuestEN[33160] = { title = "Time Keeper Kairoz", description = "You have found your way to the Timeless Isle, {class}. The bronze dragonflight is keen to investigate the mysteries of this place, but the island is dangerous, and we will need your help.\n\nMidway up this beach, you will find a paved path to the east.\n\nIt will lead you to the ancient Celestial Court. You will find Kairoz there, one of the Keepers of Time that we are working with.\n\nKairoz will answer any questions you might have. Be careful: The way may not be safe.", objectives = "Speak with Kairoz on the Timeless Isle.", completion = "Ah! Well met, <name>!\n\nI was told you would be coming, but had not expected you so soon.\n\n...or has it been a long while? It is difficult to tell, here.\n\nSo! Shall we begin?" }
WordHunterWoW_QuestEN[33161] = { title = "A Timeless Tour", description = "You should first familiarize yourself with the island.\n\nExplore. Investigate anything that catches your interest. Return when you're done, and I'll reward you for whatever information you've gathered about this strange place.\n\nAnd do be careful! Monstrous beasts and supernatural creatures abound.", objectives = "Explore the Timeless Isle.", completion = "Bizarre place, is it not?\n\nI do hope you found some adventure along the way." }
