WordHunterWoW_QuestEN[33168] = { title = "Heart On Fire", description = "We have the shards, but now they must be combined. There's a forge here, but even its fires aren't hot enough for our purposes.\n\nHowever, there is a demon nearby that burns hot as the sun.\n\nGul'dan, or perhaps Razuun, has managed to summon an infernal. The thing calls itself Krosnis, which means \"furnace.\"\n\nThe demon's heart burns hotly enough. All you need do is collect it.", objectives = "Collect the Fiery Heart from Krosnis.", progress = "With the combined might of the shards, we should be able to trap Gul'dan.", completion = "Quickly, place the heart in the forge. We'll use its infernal heat to forge the trap." }
