WordHunterWoW_QuestEN[33228] = { title = "Time In Your Hands", description = "Inhabitants of this strange island barter with a special currency, immune from the fickle fluctuations of time.\n\nYou would do well to gather as many of these \"timeless coins\" as possible! They can be found hidden away in small caches, or gathered from creatures all around the island. Larger, rarer creatures are a better source of coins - you may find it profitable to venture forth as part of a group.\n\nIntroduce yourself to Mistweavers Ai and Ku across the Celestial Court, and gather some coins for me.", objectives = "Gather 1000 Timeless Coins and introduce yourself to Mistweaver Ai and Mistweaver Ku.", progress = "You're back already? It feels like we spoke only moments ago.", completion = "I believe you are getting the feel for this place! Yes, opportunities abound to gather up timeless treasures. Strange events happen all the time here - always keep your eyes open.\n\nSpeak to the mistweavers you met to spend your hard-earned currency. Meanwhile, I will continue my research.\n\nHere is a taste of some of the treasures you can find here. More powerful items are available. You'll find that hidden caches in the more dangerous parts of the island can be... extremely rewarding. Good luck." }
WordHunterWoW_QuestEN[33229] = { title = "A Flash of Bronze...", description = "As you survey the devastation of the vale, a flash of bronze catches your eye. Unless you're mistaken, a tiny gnome is trying to catch your attention from the balcony above Mogu'shan Palace, just outside of the Seat of Knowledge.\n\nYou should see what she wants.", objectives = "Speak with Chromie outside of the Seat of Knowledge in the Vale of Eternal Blossoms.", completion = "<The tiny gnome's eyes reflect the light with a copper sheen. She is not what she seems.>\n\n<name>! I have been waiting for you. The bronze dragonflight has need of your services." }
WordHunterWoW_QuestEN[33230] = { title = "A Flash of Bronze...", description = "As you survey the devastation of the vale, a flash of bronze catches your eye. Unless you're mistaken, a tiny gnome is trying to catch your attention from the balcony above Mogu'shan Palace, just outside of the Seat of Knowledge.\n\nYou should see what she wants.", objectives = "Speak with Chromie outside of the Seat of Knowledge in the Vale of Eternal Blossoms.", completion = "<The tiny gnome's eyes reflect the light with a copper sheen. She is not what she seems.>\n\n<name>! I have been waiting for you. The bronze dragonflight has need of your services." }
WordHunterWoW_QuestEN[33231] = { title = "Journey to the Timeless Isle", description = "The bronze dragonflight has discovered a most unusual pandaren phenomenon, {class}. Emerging from the mists, far off the coast of the Jade Forest - an island that was lost in time!\n\nIt is a dangerous place, perhaps the most perilous in all of Pandaria. But we are determined to unravel its mysteries.\n\nHere, take this timepiece. A single click will whisk you to the island. Get yourself established, and speak with Watcher Lara. She will guide you to our chief investigator.", objectives = "Speak with Watcher Lara on the Timeless Isle, off the coast of the Jade Forest.\n\nProvided item:", completion = "I see Chronormu has made good on her promise! You are right on time." }
WordHunterWoW_QuestEN[33232] = { title = "Journey to the Timeless Isle", description = "The bronze dragonflight has discovered a most unusual pandaren phenomenon, {class}. Emerging from the mists, far off the coast of the Jade Forest - an island that was lost in time!\n\nIt is a dangerous place, perhaps the most perilous in all of Pandaria. But we are determined to unravel its mysteries.\n\nHere, take this timepiece. A single click will whisk you to the island. Get yourself established, and speak with Watcher Alundra. She will guide you to our chief investigator.", objectives = "Speak with Watcher Alundra on the Timeless Isle, off the coast of the Jade Forest.\n\nProvided item:", completion = "I see Chronormu has made good on her promise! You are right on time." }
WordHunterWoW_QuestEN[33233] = { title = "Short-Supply Reward", description = "", objectives = "You will receive:" }
WordHunterWoW_QuestEN[33234] = { title = "Meaty Crane Leg", description = "", objectives = "What do you have there?", progress = "What do you have there?", completion = "Oh wow, that thing is really meaty! Think of the soup I could make with it! Here, I will give you some timeless coins for it." }
WordHunterWoW_QuestEN[33235] = { title = "Great Turtle Meat", description = "", objectives = "Well that smells... interesting...", progress = "Well that smells... interesting...", completion = "It is so... spongy! Hmm, yes, perhaps a little soy sauce and some oil... Here, take these coins as payment!" }
WordHunterWoW_QuestEN[33236] = { title = "Heavy Yak Flank", description = "", objectives = "What smells like bloody flank?", progress = "What smells like bloody flank?", completion = "Thanks for the flanks! Ha ha, just a little food humor for you. Here are some coins for not groaning!" }
WordHunterWoW_QuestEN[33238] = { title = "Thick Tiger Haunch", description = "", objectives = "I have a 'haunch' you have something for me!", progress = "I have a 'haunch' you have something for me!", completion = "The stripes on this haunch are so interesting, I wonder how they will cook? First I am going to have to tenderize it a bit, though. Time to beat some meat! Here is a little something for your troubles!" }
WordHunterWoW_QuestEN[33239] = { title = "Pristine Firestorm Egg", description = "", objectives = "What is that heavenly smell?", progress = "What is that heavenly smell?", completion = "I have never seen one of those before, where in the world did you get it? It is so beautiful, I am not sure I can bear to break it open. Just kidding, this is going to make the best omelet! Here is a bunch of coins!" }
WordHunterWoW_QuestEN[33248] = { title = "Proving Grounds", description = "You there! It's {name}, right? Greetings. I'm Taijing.\n\n<Taijing sizes you up.>\n\nYou look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem?\n\nIf you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.", objectives = "Speak with Trial Master Rotun at the Temple of the White Tiger, then enter the Proving Grounds.", completion = "Welcome to the Proving Grounds, <class>. I am Trial Master Rotun.\n\nHere, you may test your skill at performing several different combat roles: dealing damage, absorbing damage, and healing. I shall administer and judge these trials.\n\n\n\nAre you ready to begin?" }
WordHunterWoW_QuestEN[33249] = { title = "Proving Grounds", description = "You there! It's {name}, right? Greetings. I'm Jinho.\n\n<Jinho sizes you up.>\n\nYou look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem?\n\nIf you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.", objectives = "Speak with Trial Master Rotun at the Temple of the White Tiger, then enter the Proving Grounds.", completion = "Welcome to the Proving Grounds, <class>. I am Trial Master Rotun.\n\nHere, you may test your skill at performing several different combat roles: dealing damage, absorbing damage, and healing. I shall administer and judge these trials.\n\n\n\nAre you ready to begin?" }
WordHunterWoW_QuestEN[33250] = { title = "A Time-Lost Treasure", description = "", objectives = "Oh my, what is THAT?", progress = "Oh my, what is THAT?", completion = "This is astounding, an egg like this hasn't been seen on Pandaria for thousands of years. I believe some of our more ancient scrolls will detail how best to handle it, though many are written in Mogu. I had best get to translating, then!" }
WordHunterWoW_QuestEN[33252] = { title = "A Winter Veil Gift", description = "", objectives = "A small tag on this present reads:\n\nHappy holidays, <name>!" }
WordHunterWoW_QuestEN[33253] = { title = "To the Defense of Karabor", description = "Get your bad self to Karabor, you <class>y little <race>-muffin.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with [FLIGHT MASTER], then report to Akama at the rear entrance to Karabor.Get your bad self to Karabor, you <class>y little <race>-muffin.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33255] = { title = "The Righteous March", description = "The Iron Horde have overtaken Karabor. If we don't act now, we will lose the city.\n\nExarch Akama and the last of our forces are trapped within the city, but your garrison forces are still outside the temple, awaiting your orders.\n\nCome and fly with me. We will meet your forces on the field. With the naaru by our side, we will make one last charge to retake the city!", objectives = "Escort your garrison forces to the Temple of Karabor by slaying all the orcs in the Path of Light.", completion = "Now, to destroy these orcs once and for all." }
WordHunterWoW_QuestEN[33256] = { title = "The Defense of Karabor", description = "Defend Karabor from the Iron Horde.\n\nAt the end of the northern courtyard is Arnokk the Burner. He guards the entrance to the harbor behind Karabor, where the main Iron Horde army is waiting.\n\nOnce we've taken care of him, we'll need to deal with the Iron Horde leader, Commander Vorka.", objectives = "Destroy the Iron Horde in Karabor.", completion = "We did it, <name>. Without your heroic efforts, the Temple of Karabor would have been lost to the Iron Horde.\n\nProphet Velen would be proud of us." }
WordHunterWoW_QuestEN[33257] = { title = "Sprite Fright - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[33258] = { title = "Tracking Quest - First - Karkanos", description = "", objectives = "" }
WordHunterWoW_QuestEN[33259] = { title = "Tracking Quest - First - Spirit of Jadefire", description = "", objectives = "" }
WordHunterWoW_QuestEN[33260] = { title = "Tracking Quest - First - Gu'chi the Swarmbringer", description = "", objectives = "" }
WordHunterWoW_QuestEN[33261] = { title = "Tracking Quest - First - Emerald Gander", description = "", objectives = "" }
WordHunterWoW_QuestEN[33263] = { title = "Gloomshade Grove", description = "<This looks like one of the pack mules from your garrison. It's strange that it's wandering out here alone.\n\nYou probably should investigate.>", objectives = "Search Gloomshade Grove for clues.", progress = "<The mule looks frightened.>", completion = "Thank the Light. <Cough> I didn't think I would get out of here alive." }
WordHunterWoW_QuestEN[33264] = { title = "A Proper Burial", description = "<The orc is visibly winded. A large pool of blood is gathering at his feet.>\n\nWe were out hunting when we found the wolves under attack.\n\nMany ogres were slaughtered by our blades... but their numbers were too great.\n\nI'm going to catch my breath before I go out and kill the rest of them.\n\nHere, take this torch. Go give my brothers and sister a proper burial and return to me.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Burn the corpses of dead Frostwolf Outriders." }
WordHunterWoW_QuestEN[33265] = { title = "The Friendly Foreling", description = "You saved us! You my best friend.\n\n<The forling gives you a big hug.>\n\nYou so nice best friend. You smell so good. The other friends eat your friends. So sad. They are so not good friends.\n\nI know where more friends are! You need friends? My friends take my things. I need things back before I can be chief. Things make me strong.\n\n<The foreling looks at you longingly. Then it sniffs you>\n\nFollow me best friend, we find all the friends, and all the things.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Help the friendly foreling gather some things before meeting with the chief." }
WordHunterWoW_QuestEN[33266] = { title = "A Light in the Dark - Tracking Quest", description = "", objectives = "" }
WordHunterWoW_QuestEN[33268] = { title = "Collect Moonstones", description = "We need moonstones. Foreling friends LOVE moonstones. moonstones best gift since foods. Foods soooo good. Best friend loves foods? Of course best friend loves foods.\n\nIf we have all the moonstones, foreling friends love us, maybe give us ALL the foods. Maybe if we have so many moonstones foreling friends make me chief. Imagine...\n\n<The forling looks into the woods and smacks it's lips.>\n\nWe find all the moonstones.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 12 moonstones to help the friendly foreling gain more friends." }
WordHunterWoW_QuestEN[33269] = { title = "Cleaning Up Gul'var", description = "Khadgar wants you to concentrate on Gul'dan, but that doesn't mean we're not going to take down the Shadow Council in the process.\n\nGul'var's filthy with Shadow Council villains. Let's do something about them.", objectives = "Kill 20 Shadow Council orcs at Gul'var.", completion = "Every world is better off without those demon-loving scum." }
WordHunterWoW_QuestEN[33270] = { title = "Tracking Quest - First - Ironfur Steelhorn", description = "", objectives = "" }
WordHunterWoW_QuestEN[33271] = { title = "Game of Thorns", description = "<Jarrod is clearly injured. He winces in pain as he begins to talk.>\n\nMy lead forest operator, Shelly... she is being held not far from here...", objectives = "Kill King Deathbloom.", completion = "<Something is moving under all of these roots.>" }
