WordHunterWoW_QuestEN[33320] = { title = "Two Birds, One Power Core", description = "The power core is of the utmost importance, <name>. We need to locate it as quickly as possible. Those Iron Horde scum carted it away hours ago though. It could be anywhere!\n\nI think we should start with the leadership here and work our way down. I'm sure we're bound to find some clues and we'll be setting them back at the same time.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill Mokrik Blackfingers, Rukah the Machinist, and Gar Steelcrush in the Second Meridian [PH]." }
