WordHunterWoW_QuestEN[33349] = { title = "STARTER QUEST - RED->PURPLE 15", description = "BFor this challenge, run through the arch, then get to the RED marker, the PURPLE marker, then return here before the bell tolls 15 times. Good luck!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Run through the arch, hit the red marker, then the purple marker, then return to the Ironelf games camp." }
WordHunterWoW_QuestEN[33350] = { title = "Redridge Group Trial", description = "Redridge group trial. Get to the blue marker, then the green marker, then the red marker, then return to the Lakeshire Ironelf cmap.", objectives = "Log description text." }
WordHunterWoW_QuestEN[33351] = { title = "Become Chief", description = "xxxxxxxYou will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill the Foreling Chief." }
WordHunterWoW_QuestEN[33352] = { title = "Tracking Event: Chief killed", description = "Okay best friend. Let's talk to old smelly mud chief. We smell so good like moonstone and foods. We give friends moonstones. We tell friends I'm chief. We get ALL the foods.\n\nStupid bad smelling chief. Thinks I'm foods? Pshh. He's foods.\n\nTime for foods best friend.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill the Foreling Chief.Okay best friend. Let's talk to old smelly mud chief. We smell so good like moonstone and foods. We give friends moonstones. We tell friends I'm chief. We get ALL the foods.\n\nStupid bad smelling chief. Thinks I'm foods? Pshh. He's foods.\n\nTime for foods best friend.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33354] = { title = "Den Mother's Demise", description = "This is the pelt of Darkmoon Island's monstrous den mother.\n\nYebb Neblegear, beastmaster of the Darkmoon Faire, will be happy to know the ghostly wolf and her spawn will no longer be terrorizing his menagerie... at least for a little while. Bring it to him.", objectives = "Bring Moonfang's Pelt to Yebb Neblegear at the Darkmoon Faire on Darkmoon Island.", progress = "Is that what I think it is?", completion = "At last, that vicious beast has been slain! Thank you." }
WordHunterWoW_QuestEN[33358] = { title = "Noodle Time: Bonus", description = "Hello, {name}. Think you're a truly extraordinary noodle chef?\n\nLet's see what you've got!", objectives = "Queue for a shift at the Halfhill noodle stand, then complete the bonus objective.", completion = "Excellent work <name>! Everyone always loves it when they hear that you'll be making noodle soup. People come from all over Pandaria just to try a taste." }
WordHunterWoW_QuestEN[33359] = { title = "Meet Us at Starfall Outpost", description = "The archmage has uncovered a potential Shadow Council presence in the valley. He asked me to let you know.\n\nAs soon as you can, join us at Starfall Outpost. We're going to need your muscle to root them out, commander.", objectives = "Speak with Archmage Khadgar at Starfall Outpost.", completion = "Hello again, <name>. You're just in time.\n\nWe've tracked the Shadow Council to a nearby village. I suspect that Gul'dan is with them." }
