WordHunterWoW_QuestEN[33400] = { title = "General Problems", description = "My forces are spread thin. The Iron Horde batters our defenses endlessly.\n\nIf you really want to help, find my commanders on the front and help them hold the line.", objectives = "Speak to Commander Dorgosh.My forces are spread thin. The Iron Horde batters our defenses endlessly.\n\nIf you really want to help, find my commanders on the front and help them hold the line." }
WordHunterWoW_QuestEN[33401] = { title = "Torg's Trouble", description = "My forces are spread thin. The Iron Horde batters our defenses endlessly.\n\nIf you really want to help, find my commanders on the front and help them hold the line.", objectives = "Speak to Commander Torg.My forces are spread thin. The Iron Horde batters our defenses endlessly.\n\nIf you really want to help, find my commanders on the front and help them hold the line." }
