WordHunterWoW_QuestEN[33406] = { title = "Northshire Sprint Trial: 12", description = "For this challenge: Run through the arch, then get to the blue marker, the green marker, and return here before the bell tolls 12 times.", objectives = "" }
WordHunterWoW_QuestEN[33407] = { title = "REUSE", description = "My brother Ga'nar led an assault into the citadel a few hours ago with some of my best lieutenants. They have yet to return.\n\nI need you to move ahead of the pack and find them. We need every warrior we can if we are to stand atop the Bladespire Lord Gorr'thog's skull by the day's end.", objectives = "Find Ga'nar, Ligra, and Korga at the Ogre Fortress." }
WordHunterWoW_QuestEN[33408] = { title = "Great Balls of Fire!", description = "Ga'nar led Ligra and the others to the second level of the fortress. Your friend, Thrall, also went to lend his skills.\n\nFollow the ramp on the south end of the ramparts outside to join them.\n\nHelp them bring victory to the Frostwolf Clan!", objectives = "Speak to Thrall in Bladespire Citadel.", progress = "Yes, traveler?", completion = "Many were killed or wounded on their way here." }
WordHunterWoW_QuestEN[33409] = { title = "Elwynn Run", description = "Welcome to the Ironelf games! For this challenge: get to the blue marker, then the green marker, then return here.\n\nScore is based on your time, so get back as fast as you can!Upon completion of this quest you will gain:", objectives = "Hit the blue marker, then the green marker, then return to the Ironelf games camp." }
WordHunterWoW_QuestEN[33410] = { title = "The Butcher of Bladespire", description = "After Ga'nar advanced into the fortress, the Bladespire unleashed a giant creature on our forces.\n\nI am still weak after using my magic, but at least I can help this orc in her recovery.\n\nHelp take Dorogg down, {name}.", objectives = "Slay Dorogg the Ruthless.", progress = "Have Dorogg fallen?", completion = "This room shook when the monster fell. Your deeds shall not go unremembered." }
WordHunterWoW_QuestEN[33412] = { title = "Mopping Up", description = "We've won the day, but our work here is far from finished.\n\nFrostwolves will scour the citadel and root out any survivors. To you, I offer the glory of cleansing the gladiator pits to the north.\n\nAs we launched our attack, we dispatched one of our best to recon that area. If you still thirst for blood, join her there. There's surely some sport left.", objectives = "Speak with Igrimar the Resolute at the Circle of Blood.", completion = "<Igrimar winces as you show her Durotan's orders.>\n\nDon't look at me like that... ungh... I've survived worse." }
WordHunterWoW_QuestEN[33415] = { title = "Northshire Sprint Trial: 11", description = "For this challenge: run through the arch, then get to the blue marker, the green marker, and return here before the bell tolls 11 times.", objectives = "" }
WordHunterWoW_QuestEN[33416] = { title = "South Sprint 12", description = "For this challenge, run through the arch, then get to the red marker, the purple  marker, then return here before the bell tolls 12 times. Good luck!", objectives = "Run through the arch, hit the red marker, then the purple, then return to the Ironelf games camp." }
WordHunterWoW_QuestEN[33418] = { title = "Tracking Quest - Failed", description = "", objectives = "" }
WordHunterWoW_QuestEN[33419] = { title = "A Matter of Life and Death", description = "Stranger, please help me!\n\nMy companions and I ventured here to seek the bounty on a monstrous wasp queen.\n\nAfter we set up camp down the hill, we fell asleep. We were attacked in the middle of the night by these horrid, pale... things!\n\nI don't know where my friends have gone, but I heard screams from further down the cavern.\n\nPlease, find my companions. I can't leave here without them!", objectives = "Find Arekk, Diaani, and Zuulo in Bloodthorn Cave.", progress = "They told us not to come out here, but we didn't listen. Why didn't we listen!?", completion = "My prayers have been answered, hero. I will tell everyone back at the village of your deeds." }
WordHunterWoW_QuestEN[33422] = { title = "Elwynn Long Distance Practice", description = "For this challenge: run through the arch, then get to the blue marker, the green marker, and finally return here.\n\nYou have all the time you need.You will receive:", objectives = "Run through the arch, hit the blue marker, then the green marker, then return to the Irongnome games camp." }
WordHunterWoW_QuestEN[33423] = { title = "Northshire Dash Practice", description = "Welcome to the Irongnome games! For this challenge: run through the arch, then get to the blue marker and return here as fast as you can.\n\nYou have all the time you need.", objectives = "" }
WordHunterWoW_QuestEN[33424] = { title = "Northshire Dash 12", description = "For this challenge: run through the arch, then get to the blue marker and return here as fast as you can.\n\nGet back before you hear the bell toll 12 times.", objectives = "Run through the arch, hit the blue marker, then return to the Ironelf games camp." }
WordHunterWoW_QuestEN[33425] = { title = "Blue/Yellow Sprint 15 INTERNAL REPEATABLE", description = "Ready for a tougher challenge? This one has an extra leg:\n\nRun through the arch...\nGet to the blue marker...\nGet to the green marker...\nthen return here before the bell tolls 15 times.\n\nGood luck!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp." }
WordHunterWoW_QuestEN[33426] = { title = "New Course: South Sprint", description = "You're running this trial well, but did you know there's another course here in Northshire?\n\nSpeak with my colleague down the road and learn about it.", objectives = "" }
WordHunterWoW_QuestEN[33427] = { title = "Ours is the Fury", description = "Drek'Thar will be fine, once he adjusts. The vision the elemental has bestowed upon him is powerful, and he is on the path of becoming this world's greatest shaman.\n\nYou may wish to inform Warmaster Zog in your garrison of what has transpired here.\n\nHe should be able to deploy some of your troops to the area to further secure the area.", objectives = "Speak with Warmaster Zog at your Garrison in Frostfire Ridge.", completion = "Well done, commander. I shall see what forces we can dispatch to the area for further clean-up." }
WordHunterWoW_QuestEN[33428] = { title = "Elwynn Forest Racing", description = "You've done great here, now are you ready to run bigger races?\n\nFind the Elwynn Race Official on the outskirts of Goldshire, and see what she has in store.", objectives = "" }
WordHunterWoW_QuestEN[33429] = { title = "Elwynn Long Distance Trial: 25", description = "For this challenge: run through the arch, then get to the blue marker, the green marker, and finally return here before the bell tolls 25 times.", objectives = "Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp." }
