WordHunterWoW_QuestEN[33443] = { title = "Barrier Destroyed", description = "", objectives = "" }
WordHunterWoW_QuestEN[33444] = { title = "Eatercology", description = "Drek'Thar thinks the portions of Exurotus consumed by the goren might be worthless. I am not about to step before the fury without at least trying to recover as many of these \"motes\" as possible.\n\nSlay any goren you find at Magnarok and see if you can extract the motes of Frostfire from them.", objectives = "Collect 10 Motes of Frostfire.", progress = "Have you had any luck recovering those motes?", completion = "Goren are abominations. They were created to eat the world. Your have done well." }
WordHunterWoW_QuestEN[33447] = { title = "Treasure: Bladespire Craftsman", description = "", objectives = "" }
WordHunterWoW_QuestEN[33448] = { title = "REUSE", description = "", objectives = "" }
WordHunterWoW_QuestEN[33449] = { title = "Northwestern Medicine", description = "There is an herb which grows in the crevices and crags of Frostfire Ridge, in places where the icy breath of the sky sips the boiling blood of the earth. Thunderlord climbers gather it often, for it has potent healing properties.\n\nLook for stores of these herbs in Thunderfall, and take what you can. Give them to me when next we meet, and they can be used to save lives in Stonefang.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Gather 20 Redleaf Herbs from supply bags in Thunderfall." }
WordHunterWoW_QuestEN[33450] = { title = "The Warlord's Guard", description = "I don't know what you are accustomed to, traveler, but these lands devour the weak. Perhaps Durotan wishes to rid himself of you. We shall see.\n\nYou must kill the Warlord of the Circle of Blood. Do this and the ogres here will be defeated. But first, you must find him.\n\nI have located his bodyguards nearby. Slay them and bring me their heads. With them, we shall lure the Warlord into the open.", objectives = "Gather the Head of Thunk, the Head of Gullok, and the Head of Splorg.", progress = "You still draw breath, hmm?\n\nHave you dealt with the warlord's underlings?", completion = "You have done well in this, but do not become proud. This land has dangers far greater than what you have seen here." }
WordHunterWoW_QuestEN[33454] = { title = "The Cure", description = "Cowards! A curse on these wretched meatbags!\n\nThe Bladespire have always taunted the orc clans by taking our wounded as slaves to fight like dogs in their pits.\n\nIn retaliation for our assault they have poisoned their orc prisoners, leaving them to suffer and die an excruciating death.\n\nOnly their geomancers carry the antidote, traveler. Use it to cure the Frostwolf prisoners.", objectives = "Cure 5 Frostwolf Gladiators.", completion = "You have done the Frostwolf Clan a service, traveler. I shall be sure to tell Durotan of your deeds." }
WordHunterWoW_QuestEN[33455] = { title = "Westfall Race Practice UNUSED", description = "Run through the arch...\nGet to the blue marker...\nGet to the green marker...\nthen return here.\n\nYou have all the time you need.You will receive:", objectives = "Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp." }
WordHunterWoW_QuestEN[33456] = { title = "Catapult Vision", description = "", objectives = "" }
WordHunterWoW_QuestEN[33457] = { title = "Catapult Vision", description = "", objectives = "" }
WordHunterWoW_QuestEN[33458] = { title = "Catapult Vision", description = "", objectives = "" }
WordHunterWoW_QuestEN[33461] = { title = "Gloomshade Game Hunter", description = "<You find a list on a piece of parchment.\n\nArsenio needs some ingredients for a new recipe he's preparing at your garrison.>", objectives = "Collect ingredients in Gloomshade Grove.", progress = "Did you find all the ingredients I need?", completion = "Nice! Thanks so much! I can use these to make a delicious wolf meat, frog leg, mushroom stew." }
WordHunterWoW_QuestEN[33462] = { title = "Thunderlord for a Day", description = "Pieces of a Thunderlord chain lay on the ground. It is of a very simple design, but effective.\n\nWith enough parts, even the most unskilled person could assemble a chain and grapple as effective as those used by the Thunderlord Grapplers.", objectives = "Build a Thunderlord Grapple.", progress = "This shoddy, beaten anvil is used mostly for crafting chains and what little other metal working the Thunderlord require.", completion = "With a quick tap of a hammer and a snip of the rings, the Thunderlord Grapple is as good as new." }
WordHunterWoW_QuestEN[33463] = { title = "The Iron Tide", description = "The majority of Karabor's defensive troops are dealing with the main battle front, just west of here. We must not ignore our flanks while dealing with that assault.\n\nOne of the enemy leaders, Arnokk, is directing the mayhem on this side of the temple. Take him out, along with as many of his orcish followers as you can stomach.\n\nOnce you've finished, meet me in front of the temple.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay Arnokk the Burner and 10 Iron Horde troops within Karabor." }
WordHunterWoW_QuestEN[33464] = { title = "From Over the Walls", description = "Karabor is falling. The Iron Horde will not stop this assault until every last one of us is dead and cold on the ground.\n\nI don't know about you, but I don't plan on letting that happen.\n\nNow, there must be something we can do to prevent them from scaling the walls...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Dislodge 6 Blackrock Grappling Hooks near Karabor's outer walls." }
WordHunterWoW_QuestEN[33466] = { title = "Rally the Artificers", description = "I have several lieutenants out there on the battlefield, doing what they can to hold this temple together. I need all of them, but first and foremost, I need my artificers.\n\nThe artificers are masters of technology and artifacts. If any one of my followers can understand the mechanics of those siege engines, it would be them.\n\nRommul is their leader. Send him to me.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Convince Rommul to return to Velen near Karabor's western entrance." }
WordHunterWoW_QuestEN[33467] = { title = "The Fall of the Warlord", description = "You've managed to survive this long, stranger. All that remains to be done here is to fell the Warlord of the arena.\n\nThis will be your first true test here. Bult would provide a challenge to even a battle-hardened Frostwolf.\n\nPlace the heads you've collected on spikes in the Frostfire Arena. They are sure to enrage the warlord and lure him into battle.\n\nCome out of the arena victorious and it will show that Durotan's trust in you was not misplaced.", objectives = "Kill Warlord Bult.", progress = "Yes, traveler?", completion = "Impressive work." }
WordHunterWoW_QuestEN[33468] = { title = "Save Wolf Home", description = "Cowardly Thunderlords...\n\nDuring the battle for the citadel, runners informed me that the Iron Wolf is striking at our home. He'll find no easy footing there, Draka will make them pay tenfold for any of ours that they slay, but we must return quickly and chase the mongrels off.\n\nYou and your forces have proven valuable allies of the Frostwolves. We'd welcome your aid in securing our Wor'gol.\n\nI'll see you on the battlefield if you choose to come.", objectives = "Save Wor'gol from the Thunderlord clan.", progress = "There are more Thunderlord to be killed.", completion = "Durotan's trust in you is well-placed, <name>. You have mine as well." }
WordHunterWoW_QuestEN[33469] = { title = "The Farseer", description = "The Thunderlord warleader... {name}, you have to stop him.\n\nHe went to attack Drek'Thar at the Pool of Visions to the northwest!", objectives = "Get to the Pool of Visions and kill Warleader Gargrak.", progress = "Wolf Home will not be safe until this coward is dead!", completion = "Wolf Home is saved, but I sense a stronger enemy just over the horizon." }
WordHunterWoW_QuestEN[33470] = { title = "Pool of Visions", description = "A terrible storm gathers on the horizon, {class}.\n\nI have prepared a ritual. You must consult the pool to see what destiny holds for us all.", objectives = "Speak with Farseer Drek'Thar at the Pool of Visions to begin the ritual of vision.", completion = "This Iron Tide threatens to sweep over all of Draenor.\n\nThe pool has shown you a possible future. This vision of the Frostwolf clan's destruction must not be allowed to come to pass.\n\nYou must stop it, <name>." }
WordHunterWoW_QuestEN[33473] = { title = "Back to Bladespire Citadel", description = "Durotan must be told of your vision. Pul Windcarver will offer you a flight back.\n\nThe fate of the Frostwolf... of Draenor, depends upon you, {name}.", objectives = "Return to Durotan at Bladespire Citadel.", completion = "Grim news indeed, <name>.\n\nFor saving Wolf Home, I would name you wolf-brother.\n\nNow we must defend Frostfire Ridge from the Thunderlord clan and the Iron Horde." }
WordHunterWoW_QuestEN[33483] = { title = "Mulverick's Plight", description = "You were sent here to free me? It seems that makes us allies.\n\nSlavemaster Turgall within the Soostained Mines will certainly have the key to this cage.\n\nWhile you're in there, do you think you could see which of those spineless taskmasters took my axes?", objectives = "Get the key from Slavemaster Turgall and find Mulverick's Axes.", progress = "These ogres will be seeing the other side of my axes soon.", completion = "You have my sincere gratitude, <name>." }
WordHunterWoW_QuestEN[33484] = { title = "The Slavemaster's Demise", description = "Share word with the others of the Frostwolves you saved this day. They will be glad to know that some made it out of the mines alive.", objectives = "Speak to Guse at Bladespire Citadel.", completion = "You found Mulverick?\n\nIt shouldn't be long before those ogres clear out after you defeated their master." }
WordHunterWoW_QuestEN[33485] = { title = "Multiplayer Race", description = "Run through the arch...\nGet to the blue marker...\nGet to the green marker...\nGet to the red marker\nGet to the purple marker\nReturn here...\nThen do it all again. That's right - 2 laps!\n\nGood luck!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Run through the arch, hit the blue marker, then the green marker, the red marker, the purple marker, then return to the Ironelf games camp." }
WordHunterWoW_QuestEN[33492] = { title = "Northshire Sprint Practice", description = "Welcome to the Irongnome games! For this challenge: run through the arch...\nGet to the blue marker...\nGet to the green marker...\nthen return here.\n\nYou have all the time you need for this.", objectives = "Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp." }
WordHunterWoW_QuestEN[33493] = { title = "Return to the Pack", description = "Part of me agrees with Karg - we COULD challenge the Iron Wolf right now. My fists clench at the mention of his name. My muscles scream for vengeance.\n\nBut then, in my heart, I feel Asha. Calming me. Guiding me. I do not deserve her wisdom, but it is a gift I will not waste.\n\n<Lokra squints at the sky.>\n\nDurotan and the others will be gathering at your garrison about now. We should meet them.", objectives = "Speak with Durotan at your garrison.", completion = "Lokra has always lacked the patience and control of her older sister. She approaches problems head-first, and relies on her raw talents to succeed.\n\nSeeing the way her and Karg look at each other, I am not surprised she chased him all the way to Grom'gar. What surprises me is that they made it back.\n\nAs usual, I expect we have you to thank for that. You continue to honor us with your deeds." }
WordHunterWoW_QuestEN[33496] = { title = "Iron Horde in Karabor", description = "", objectives = "" }
WordHunterWoW_QuestEN[33497] = { title = "Vignette: Time-Warped Brute Falling 2", description = "", objectives = "" }
