WordHunterWoW_QuestEN[33500] = { title = "Treasure: Slave's Stash", description = "", objectives = "" }
WordHunterWoW_QuestEN[33501] = { title = "Treasure: Arena Spectator", description = "", objectives = "" }
WordHunterWoW_QuestEN[33502] = { title = "Treasure: Carved Obsidian Idol", description = "", objectives = "" }
WordHunterWoW_QuestEN[33504] = { title = "Vignette: Shaman Fire Stone", description = "", objectives = "" }
WordHunterWoW_QuestEN[33505] = { title = "Treasure: Wiggling Chimaera Egg", description = "", objectives = "" }
WordHunterWoW_QuestEN[33509] = { title = "Unexpected Assault", description = "Thank the Light you're here. The Bonechewer orcs have invaded!\n\nWe've dealt with the occasional raid before, but they've never attacked Auchindoun with such numbers before.\n\nWe arrived as quickly as we could to respond to the threat, but the local guard had already fallen. We cannot afford to lose more men!\n\nKill all of the Bonechewer you can and help consolidate our forces back to our defensive line. The Bonechewer must not be allowed to step foot in Auchindoun!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 1 Bonechewer Orcs and direct $2oa Auchenai to safety in the Court of Souls." }
WordHunterWoW_QuestEN[33510] = { title = "Unexpected Assault", description = "My scouts have reported that the Bonechewer clan is attacking Auchindoun, <name>. The Auchenai guard are here, but I fear they won't be enough.\n\nI sense a dark presence nearby... we cannot chance leaving their defenses weak. Too much power lies within those hallowed halls.\n\nSlay the Bonechewer and direct any of the Auchenai injured back to their defensive line. I will direct my scouts throughout the area to try to ascertain the Bonechewers' motives.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Slay 1 Bonechewer Orcs and direct $2oa Auchenai to safety in the Court of Souls." }
WordHunterWoW_QuestEN[33511] = { title = "Vignette: Sacrifice Pit", description = "", objectives = "" }
WordHunterWoW_QuestEN[33512] = { title = "Vignette: Lava-Gorged Goren", description = "", objectives = "" }
WordHunterWoW_QuestEN[33513] = { title = "Blackthorn's Lieutenants", description = "Amnennar's reincarnation is imminent. In order to protect the ceremony Death Speaker Blackthorn has placed his most trusted lieutenants between us and him.\n\nAarux, a plagued spider nests near his young, tended to by the Death's Head Aranomancers. Mordresh rallies Amnennar's forces upon the Bone Pile. Finally, Mushlump stands guarding the entrance to the Spiral of Thorns.\n\nOnce you defeat these guardians I will join you and together we will confront Blackthorn.", objectives = "Kill Aarux, Mordresh, and Mushlump.", progress = "Have you cleared the way?", completion = "You have done well, but this is only half of the battle. With his support structure in disarray it is time to strike at Death Speaker Blackthorn." }
WordHunterWoW_QuestEN[33514] = { title = "The Ritual", description = "You are good to have come so quickly.  I must ask you to put your lives in danger once more in order to save Kalimdor.\n\nAmnennar's apprentice, Death Speaker Blackthorn, hopes to return his master to the realm of the living!  We must quickly make our way atop the Spiral of Thorns and defeat him before the ritual can be completed.  We must strike together, only with our combined force can we hope to stop him!", objectives = "Kill Amnennar the Coldbringer.", progress = "Quickly <name>, you must stop the ritual!  Amnennar cannot be allowed to return.", completion = "A job well done, <name>. With Amnennar's phylactery now protected by the Red dragonflight we can now rest at ease." }
WordHunterWoW_QuestEN[33516] = { title = "Un-Safety First", description = "These plans were designed to be read by even the most unskilled of metallurgists. It has big symbols on specific pipes for what valves NOT to turn unless risking woeful amounts of destruction.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Disable 4 Safety Valves." }
WordHunterWoW_QuestEN[33521] = { title = "Save Auchenai Caretakers", description = "I was fortunate enough to be delivering a report to the Exarch when the demons attacked, but the rest of my brethren were out tending to the Court of Lights!\n\nWe caretakers are not the fighters of our order. Go to the court northwest of here and help direct them to safety.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Direct 6 Auchenai Caretakers to safety in the Court of Lights in Talador." }
WordHunterWoW_QuestEN[33522] = { title = "Felblood", description = "Fascinating. The doomguard in the courtyard southwest of here have disguised themselves as orcs and do not die when defeated in battle.\n\nYou see, they are powerful magical beings, and their essence manifests nearby as a blood creature that revives its body upon reaching it.\n\nI would like to study these essences without dealing with the demons myself. Bring me a few samples, would you?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Collect 6 Felblood Samples by killing Stormreaver Fearmongers in the Court of Lights in Talador." }
WordHunterWoW_QuestEN[33525] = { title = "Treasure: Orc Couple", description = "", objectives = "" }
WordHunterWoW_QuestEN[33526] = { title = "These Colors Don't Run", description = "Bladespire has been a plague on my people for many years.\n\nThat ends today!\n\nNow to explain it to the ogres in a way they will understand.\n\nIf you still wish to help us, place our banner in the corpses of our adversaries. \n\nTheir courage will falter as they behold a field of Frostwolf trophies!\n\nThis is our way. I will meet with you ahead when you have completed this deed.", objectives = "Use 8 Frostwolf Banners on Bladespire Ogre corpses.", progress = "Yes?", completion = "These are no ordinary enemies, yet you did not show any signs of weakness." }
WordHunterWoW_QuestEN[33527] = { title = "Last Steps", description = "In a rage, Ga'nar ascended to fight Gorr'thog, the ogre king.\n\nHe is alone, and the ramp to the throne room is now blocked.\n\nYou've proven resourceful. Perhaps you could find another way up?\n\nI sustained wounds on my way here, but I will work to cut my way through and up the ramp so we may rejoin.\n\nHurry traveler, ensure that the Frostwolf clan wins our assault on the citadel.", objectives = "Climb the chain and kill Gorr'thog.", completion = "We called you outsider, <race>, but you have shown the strength and heart of a Frostwolf." }
WordHunterWoW_QuestEN[33529] = { title = "Nightmare in the Tomb", description = "In the tomb... horrible... bodies everywhere...\n\nA dark ritual... please... you must stop it...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Investigate the ritual in the Tomb of Souls." }
WordHunterWoW_QuestEN[33530] = { title = "Nightmare in the Tomb", description = "Down there... horrible... bodies everywhere...\n\nDark ritual... please... you must stop it...", objectives = "Investigate the ritual in the Tomb of Souls.", completion = "If this Teron'gor gains control of Auchindoun, the results would be catastrophic!\n\nWe must stop him before his power grows!" }
WordHunterWoW_QuestEN[33531] = { title = "Treasure: Fallen Ogre", description = "", objectives = "" }
WordHunterWoW_QuestEN[33532] = { title = "Treasure: Ogre Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[33533] = { title = "The Secrets of Gorgrond", description = "Our victory today was costly. Too costly. There is no guarantee that we can turn another attack.\n\nWe need to know what the Iron Horde is up to, and there is only one place we can go to find out.\n\nGorgrond.\n\nIt is a savage land that few ever return from.\n\nI mean to go there, I mean to find their stronghold at Blackrock, and I mean to learn how we can defeat these vile orcs.\n\nWill you join me, Commander?", objectives = "Seek Yrel at the Wildwood Wash in Gorgrond. Speak with your Garrison Gryphon Master to fly there.", completion = "Welcome to Gorgrond, Commander. We only just arrived ourselves." }
WordHunterWoW_QuestEN[33534] = { title = "Find D'kaan", description = "D'kaan's nearby. He said something about unusual tracks. Hardly what we need to be focusing on at a time like this.\n\nWe need to leave soon. Help him, would you?You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find Rangari D'kaan at Tailthrasher Basin in Gorgrond.D'kaan's nearby. He said something about unusual tracks. Hardly what we need to be focusing on at a time like this.\n\nWe need to leave soon. Help him, would you?You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33536] = { title = "The Element of Demise", description = "The Frostwolves are a fierce and noble clan, but distrustful of outsiders.\n\nWe have arrived amidst their assault on a mighty ogre citadel. I will remain here to offer counsel to their chieftain, Durotan.\n\nYou are a proven hero of Azeroth, <name>. Demonstrate your value to the Frostwolves. We need them as allies.\n\nUse my totem to thwart the ogre counterattack. This should serve to get their attention.\n\nThe rest is up to you.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Place Thrall's totem at the center of the bridge." }
WordHunterWoW_QuestEN[33540] = { title = "Treasure: Uzko's Knickknacks", description = "", objectives = "" }
WordHunterWoW_QuestEN[33543] = { title = "The Laughing Skull", description = "Ah, {name}, good. I need someone who is not of my clan to negotiate with the Laughing Skull.\n\nWe could use their help navigating this land, but they are dangerous and unpredictable, much like Gorgrond itself.\n\nFollow this road and seek out someone willing to speak with you.\n\nPerhaps they will see you as something new and be willing to talk first and stab later.", objectives = "Find a Laughing Skull clansman.", completion = "Ha! Curious. What are you?" }
WordHunterWoW_QuestEN[33544] = { title = "Goren, Goren, Gone!", description = "We... we left the goren alone for too long. They have grown bold and forgotten who we are.\n\nKill them! Kill them all. Rip them apart until they scream. Remind them what happens to anyone who tries to attack a Laughing Skull village.\n\nOh, and welcome to Gorgrond.", objectives = "Slay 8 Acidtooth Devourers.", completion = "Ripfist's dying wish has been satisfied. Goren corpses litter the ground, and these corpses have not gone unnoticed by the nearby goren." }
WordHunterWoW_QuestEN[33545] = { title = "Arkonite Crystals", description = "Mage-Lord Bloodsworn and I recently completed the first of our new blood golems. Once we're in full production, we won't need to risk lives in the field!Unfortunately, they still need a core power crystal.\n\nWe spotted a Draenei mine overrun with crystal-hungry Goren nearby. Do what you must to get enough crystals to power our golems!", objectives = "Gather 8 Arkonite Crystals at the Overload Mine in Talador." }
WordHunterWoW_QuestEN[33546] = { title = "Deeds Left Undone", description = "In his haste, Ga'nar advanced before this area was secured. He is a matchless warrior, mind you, but his tactics are sometimes costly.\n\nGol'kosh and his troops were ordered to destroy enemy supplies, but ogres have stolen the oil he needs.\n\nRetrieve the oil and see that their mission is carried out, traveler. Then, if they still live, direct them to rejoin me at the citadel's entrance.\n\nI must see my wounded brothers to safety.", objectives = "Collect barrels of Frostwolf Oil and deliver it to Gol'kosh in the supply room.", progress = "Lok'tar, traveler.", completion = "Gol'kosh has completed his mission, then." }
WordHunterWoW_QuestEN[33547] = { title = "Desperate Times", description = "I have heard of the orcs you saw in the tomb before... this is not good news.\n\nIf they seek the key to Auchindoun, we must stop them from obtaining the remaining key fragments. Nyami was right; the fragments are no longer safe where they lay.\n\nThere's no time to waste. We will ride together to the Tomb of Lights and secure them ourselves.", objectives = "Ride to the Tomb of Lights with Exarch Maladaar." }
WordHunterWoW_QuestEN[33548] = { title = "We Die Laughing!", description = "Are you here to help or hinder?\n\nThis village is being eaten, and we must move quickly to salvage what we can.\n\nGather the masks of our fallen Laughing Skull brothers and sisters and meet me on the western side of the village.\n\nI will need them if our clan is to rebuild.", objectives = "Collect 5 Laughing Skull Masks.", progress = "We are the Laughing Skull! We do not flinch in the face of death. We laugh at it.", completion = "These are more than fancy facewear. With a mask and some proper incentive, we can make anyone a Laughing Skull." }
WordHunterWoW_QuestEN[33549] = { title = "The Cost of Chaos", description = "Durotan had a plan.\n\nThere were many paths to victory, but his was the most wise. His would cost the least blood.\n\nHis brother, Ga'nar, is one of our most revered warriors, but he is prone to give in to blood lust. As the first Frostwolf fell, his temper won over his discipline. He ordered the bulk of our forces headlong into the citadel.\n\nThis is not the first time Durotan's brother has abandoned reason, but it may be the most costly.\n\nFind them, stranger. Do what you can to salvage our assault.", objectives = "Find Lorgosh in Bladespire CitadelDurotan had a plan.\n\nThere were many paths to victory, but his was the most wise. His would cost the least blood.\n\nHis brother, Ga'nar, is one of our most revered warriors, but he is prone to give in to blood lust. As the first Frostwolf fell, his temper won over his discipline. He ordered the bulk of our forces headlong into the citadel.\n\nThis is not the first time Durotan's brother has abandoned reason, but it may be the most costly.\n\nFind them, stranger. Do what you can to salvage our assault." }
WordHunterWoW_QuestEN[33557] = { title = "Muddy Waters", description = "<Cough>\n\nNot feeling so strong... dehydrated...\n\n<Cough>\n\nNeed nutrients for leaves... need revenge...You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Find nutritious mud in the Spinebloom Spires to revive Jagahari." }
WordHunterWoW_QuestEN[33560] = { title = "Light's Rest", description = "This map you found seems to show the locations of the other portals. By the Light, they have it surrounded!\n\nWe have a small staging area not far from the nearest portal. Let's go.\n\nNYI. Cheat this quest and go to the camp.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Ride with Exarch Maladaar to Light's Rest in Talador." }
WordHunterWoW_QuestEN[33561] = { title = "Multiplayer Race", description = "Run through the arch...\nGet to the blue marker...\nGet to the green marker...\nGet to the red marker\nGet to the purple marker\nReturn here...\nThen do it all again. That's right - 2 laps!\n\nGood luck!You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Run through the arch, hit the blue marker, then the green marker, the red marker, the purple marker, then return to the Ironelf games camp." }
WordHunterWoW_QuestEN[33562] = { title = "Trophy: Gorg'ak's Obsidian Spines", description = "", objectives = "" }
WordHunterWoW_QuestEN[33563] = { title = "Eye Candy", description = "You! Get in the fight or get out of our way.\n\nThis is no ordinary goren attack. Look over there, a gronnling is sacking our grubhall. That hunchbacked gorebucket bit a chunk out of my lovely Marrow!\n\nRip the eye out of its forehead and bring it to me.\n\nThat should buy me enough time to get her clear of this goren hole.", objectives = "Collect Skothwa's Eye.", progress = "Did you make that thing scream? Did it beg for mercy? Did you kill it before taking its eye? Tell me everything.", completion = "These puppets of the magnaron will pay for the skulls they claimed today.\n\nFor now, I shall wear this eye across my waist so this fool you have slain may watch as I slowly slaughter his brethren until my dying breath." }
WordHunterWoW_QuestEN[33564] = { title = "Treasure: Hanging Satchel", description = "", objectives = "" }
WordHunterWoW_QuestEN[33565] = { title = "Treasure: Chimaera Scale", description = "", objectives = "" }
