WordHunterWoW_QuestEN[33575] = { title = "Treasure: Demonic Cache", description = "", objectives = "" }
WordHunterWoW_QuestEN[33577] = { title = "A New Threat", description = "Aruuna, a draenei mining settlement to the northeast, has been sacked. Strangely, it doesn't sound like the work of the Iron Horde.\n\nMy scouts describe the attackers as \"giant fire-breathing birdmen.\"\n\nI suppose nothing in this place should surprise me anymore...\n\n<QUESTGIVER points to her map.>\n\nRefugees have been seen fleeing along this road. Help them if possible, and learn whatever you can about the attackers.\n\nif these \"birdmen\" are a threat, we need to know.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Speak with Crystal-Shaper Barum at the crossroads northwest of Aruuna.Aruuna, a draenei mining settlement to the northeast, has been sacked. Strangely, it doesn't sound like the work of the Iron Horde.\n\nMy scouts describe the attackers as \"giant fire-breathing birdmen.\"\n\nI suppose nothing in this place should surprise me anymore...\n\n<QUESTGIVER points to her map.>\n\nRefugees have been seen fleeing along this road. Help them if possible, and learn whatever you can about the attackers.\n\nif these \"birdmen\" are a threat, we need to know.You will receive:\n\nUpon completion of this quest you will gain:" }
WordHunterWoW_QuestEN[33578] = { title = "Pyrophobia", description = "W- we have done n-n-nothing to provoke the arakkoa... w-why would they attack Aruuna? What do they want from us?\n\nI want to run, but I'm... too afraid. That leader of theirs will burn me to a crisp, I just know it!\n\nH-he's just inside the inn...", objectives = "Slay Sun-Sage Kairyx.", progress = "SHH! K-k-keep your voice down... they'll find us!", completion = "You killed him? Oh, oh thank you!\n\nBut what was that he said about an artifact?" }
WordHunterWoW_QuestEN[33579] = { title = "What the Draenei Found", description = "They came here for an artifact? The miners must have found something in our crystal mine to the north.\n\nBy the Light, can you imagine how powerful that thing must be, to attract them all the way here from their spires?\n\nI suppose it is in their hands now... You'd have to be crazy to go looking for it...", objectives = "Examine the Ancient Prism in the Aruuna Crystal Mine.", completion = "I was worried my little act wouldn't fool you, but you played your role perfectly.\n\nIn fact, I would like to ask for your help again." }
WordHunterWoW_QuestEN[33580] = { title = "The Purge of Veil Shadar", description = "Not all arakkoa are alike.\n\n<Iskar lifts his sleeve to reveal a mangled, useless wing.>\n\nIt is no illusion. They did this to me. Before I was even given a name, I was given a place in society: at the bottom.\n\nWe are many. We make our homes in the places this world has forgotten.\n\nVeil Shadar was such a place, but the Adherents have found it and started a purge. For morale. For fun.\n\nHelp my people escape, and we'll be in your debt.\n\nWhen the sky burns, it pays to have allies in the shadows.", objectives = "Help 8 Arakkoa Outcasts evacuate from Veil Shadar.", completion = "Mark my words, <race>: Aruuna and Veil Shadar were only the beginning." }
WordHunterWoW_QuestEN[33581] = { title = "Forbidden Knowledge", description = "<Darkscryer Raastok narrows his eyes and looks you up and down.>\n\nSo, you are Iskar's hired hand? Well, I care not whether you are a {race} or an overgrown moth, so long as you are willing to help.\n\nThe Adherents of Rukhmar are closed-minded fools! They forbid the study of shadow magic, branding as heretics anyone who dares to seek answers in the dark.\n\nWe kept many tomes of forbidden knowledge in Veil Shadar. Bring any you find to me, and I will reward you for keeping them from the flames.", objectives = "Recover 6 Shadow Tomes from Veil Shadar.", progress = "What kind of sick individual burns a book full of perfectly good dark arts?!", completion = "Yes, yes. Excellent work, these are some of my favorites.\n\nKnowledge is power, and now I can leave for the spires feeling well-armed." }
WordHunterWoW_QuestEN[33582] = { title = "Kura's Vengeance", description = "I was a wing-guard myself, once upon a time.\n\nOne afternoon, I was caught away from my post. I just wanted an hour to watch the festival... Kuuan was supposed to cover for me, but instead he sold me out to gain favor with our superiors.\n\nThey plucked my eyes, broke my wings, and threw me off the spire.\n\nYet I am the fortunate one, for if Iskar hadn't found me, I'd have died there. And now Kuuan shows his face in Veil Shadar on the same day that you show up willing to kill for coin. Fortunate, indeed.", objectives = "Slay Wing-Guard Kuuan in Veil Shadar.", completion = "Speaking of fortune, count yourself lucky that I was not among the defenders in Aruuna, for you'd have seen both ends of your guts before you laid eyes on the Fire-Sage.\n\nAh, sometimes I miss those days.\n\nHere is your coin." }
WordHunterWoW_QuestEN[33584] = { title = "Treasure: Ashes of A'kumbo", description = "", objectives = "" }
WordHunterWoW_QuestEN[33586] = { title = "Chasing Shadows", description = "Not all of the Shadowmoon orcs followed Ner'zhul's alliance with the Iron Horde.\n\nAmong them, there is one orc whom I befriended many years ago. She may be able to tell us more about Ner'zhul's plans for this \"Dark Star.\"\n\nShe can be found at Exile's Rise to the northeast. I will send word ahead so she expects your arrival.", objectives = "Speak to Rulkan at Exile's Rise.", completion = "I felt that this day would come. The draenei prophet is not wrong to seek me, traveler.\n\nThough we do not speak often, he and I have a deep mutual respect for one another.\n\nI know the trouble that his people are suffering, and I no longer believe the Shadowmoon are following our ancestor's path.\n\nFor those reasons, I will help you." }
WordHunterWoW_QuestEN[33588] = { title = "Task: Break Corrupt Deathweb Eggs", description = "", objectives = "" }
WordHunterWoW_QuestEN[33593] = { title = "A Flare for the Dramatic", description = "I received a strange object with a note attached. Here, it seems to be written in your tongue, commander.\n\n<Dear Mister Durotan,\n\nI'm Penny... you know, from Azeroth? We met briefly back at {name}'s garrison. \n\nAnyway, like I told you, I have a fifth degree black hammer in engineering and I'm eager to serve. The more danger the better!\n\nYou just fire this old flare whenever you're in trouble and I'll be there, quick as a quark!\n\nHopefully,\n\nPenny>", objectives = "Shoot Penny's Flare Gun while in Deadgrin.", progress = "Hey there, commander!", completion = "That didn't seem to do much, commander, except to give away our position to every creature in Gorgrond.\n\nWait, did you hear something?" }
WordHunterWoW_QuestEN[33597] = { title = "Tracking Quest - First - The Obliterator", description = "", objectives = "" }
WordHunterWoW_QuestEN[33602] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[33603] = { title = "Short-Supply Reward", description = "", objectives = "" }
WordHunterWoW_QuestEN[33609] = { title = "Northshire Dash Practice", description = "Welcome to the Irongnome games! For this challenge: run through the arch, then get to the blue marker and return here as fast as you can.\n\nYou have all the time you need.", objectives = "Run through the arch, hit the blue marker, then return to the Ironelf games camp." }
