WordHunterWoW_QuestEN[33614] = { title = "Treasure: Greka's Urn", description = "", objectives = "" }
WordHunterWoW_QuestEN[33622] = { title = "To the Slaughter", description = "This entrance to the fortress is clear again, thanks to your help.\n\nInside is another story. Find your way inside and leave no ogre standing as you go.", objectives = "Kill 10 ogres in Bladespire Citadel.", progress = "Yes?", completion = "Again we meet..." }
WordHunterWoW_QuestEN[33633] = { title = "Rooter the Ravenous", description = "The stray boar is digging through garbage left behind by the iron horde. He stops chewing and stares at you-then he burps.\n\nHe smells terrible.\n\nIt looks like he's chewing on a chunk of rotten meat. Maybe you can find something a bit healthier for him to snack on?", objectives = "Find food for Rooter at Rooter's Pass in Gorgrond.", progress = "That rotten meat looks gross. Find rooter something healthy to eat.", completion = "You feed the hungry boar the nopales. He devours them whole and smacks his lips.\n\nRooter jumps up onto you and licks your face with his disgusting tongue.\n\nIt looks like you have made a new friend." }
WordHunterWoW_QuestEN[33634] = { title = "Maldo's Test Quest", description = "[DNT] Quest Description", objectives = "[DNT] Log Description" }
WordHunterWoW_QuestEN[33635] = { title = "FLAG - Seen Gazebo Explosion", description = "", objectives = "" }
WordHunterWoW_QuestEN[33638] = { title = "Insatiable Swarms", description = "Something has spurred the podlings that live in the nearby forest to come here. They are scaring the talbuk, eating the crops, and slaughtering my people!\n\nI led refugees from Tuurem here in search of safety from the Iron Horde, and now we have to contend with these foul creatures!\n\nPlease, you must help us! I need to attend to my wife's wounds and guide her to safety. Meet me inside the farm proper towards the back when their numbers have been culled back.You will receive:\n\nUpon completion of this quest you will gain:", objectives = "Kill 20 Podlings at Kuuros Farm." }
